// Текст диалога Платона «Парменид», 201 раздел по Стефанусу.
// Греческий: J. Burnet, Platonis Opera II, OUP 1901 (Perseus Digital Library, CC BY-SA 3.0).
// Русский: пер. В. Н. Карпова, «Сочинения Платона», ч. VI, СПб. 1879 — общественное достояние.
export type Sec = { g: string; r: string };
export type Chapter = { slug: string; title: string; note: string; part: number; first: string; last: string; sections: string[] };
export const sections: Record<string, Sec> = {"126a": {"g": "ἐπειδὴ Ἀθήναζε οἴκοθεν ἐκ Κλαζομενῶν ἀφικόμεθα, κατʼ ἀγορὰν ἐνετύχομεν Ἀδειμάντῳ τε καὶ Γλαύκωνι· καί μου λαβόμενος τῆς χειρὸς ὁ Ἀδείμαντος, Χαῖρʼ, ἔφη, ὦ Κέφαλε, καὶ εἴ του δέῃ τῶν τῇδε ὧν ἡμεῖς δυνατοί, φράζε. ἀλλὰ μὲν δή, εἶπον ἐγώ, πάρειμί γε ἐπʼ αὐτὸ τοῦτο, δεησόμενος ὑμῶν. λέγοις ἄν, ἔφη, τὴν δέησιν.", "r": "Прибыв с родины, из Клазомен, в Афины, мы встретились на площади с Адимантом и Главконом; и Адимант, взяв меня за руку, сказал: Здравствуй, Кефал, и говори, не нужно ли тебе здесь чего-нибудь, что находится в нашем распоряжении. — Да я за тем-то и пришел сюда, чтобы просить вас, — был мой ответ. — Так не угодно ли объявить свою просьбу, — сказал он. — И я начал: Как звали вашего брата одной с вами матери? Я не припомню. Он был еще в детстве, когда я приезжал"}, "126b": {"g": "καὶ ἐγὼ εἶπον· τῷ ἀδελφῷ ὑμῶν τῷ ὁμομητρίῳ τί ἦν ὄνομα; οὐ γὰρ μέμνημαι. παῖς δέ που ἦν, ὅτε τὸ πρότερον ἐπεδήμησα δεῦρο ἐκ Κλαζομενῶν· πολὺς δὲ ἤδη χρόνος ἐξ ἐκείνου. τῷ μὲν γὰρ πατρί, δοκῶ, Πυριλάμπης ὄνομα. πάνυ γε, ἔφη. αὐτῷ δέ γε; Ἀντιφῶν. ἀλλὰ τί μάλιστα πυνθάνῃ; οἵδε, εἶπον ἐγώ, πολῖταί τʼ ἐμοί εἰσι, μάλα φιλόσοφοι, ἀκηκόασί τε ὅτι οὗτος ὁ Ἀντιφῶν Πυθοδώρῳ τινὶ Ζήνωνος", "r": "сюда раньше из Клазомен. С той поры протекло уже много времени. Ведь отца, кажется, зовут Перилампом? — Конечно, отвечал он; а его-то Антифоном. Но к чему этот вопрос? — Это — мои сограждане, сказал я, — большие философы; они слышали, что этот Антифон часто ходил к Пифодору, одному из друзей Зенона, и, нередко слыша от Пифодора беседы, какие некогда вели Сократ, Зенон"}, "126c": {"g": "ἑταίρῳ πολλὰ ἐντετύχηκε, καὶ τοὺς λόγους, οὕς ποτε Σωκράτης καὶ Ζήνων καὶ Παρμενίδης διελέχθησαν, πολλάκις ἀκούσας τοῦ Πυθοδώρου ἀπομνημονεύει. ἀληθῆ, ἔφη, λέγεις. τούτων τοίνυν, εἶπον, δεόμεθα διακοῦσαι. ἀλλʼ οὐ χαλεπόν, ἔφη· μειράκιον γὰρ ὢν αὐτοὺς εὖ μάλα διεμελέτησεν, ἐπεὶ νῦν γε κατὰ τὸν πάππον τε καὶ ὁμώνυμον πρὸς ἱππικῇ τὰ πολλὰ διατρίβει. ἀλλʼ εἰ δεῖ, ἴωμεν παρʼ αὐτόν· ἄρτι γὰρ ἐνθένδε οἴκαδε οἴχεται, οἰκεῖ δὲ ἐγγὺς ἐν Μελίτῃ.", "r": "и Парменид, припоминает их. — Ты говоришь правду, примолвил он. — Так мы желаем переслушать их, сказал я. — Это не трудно, продолжал он: Антифон в ранней молодости очень много занимался ими, хотя теперь-то, по примеру деда, своего соименника, занимается по большей части верховою ездою. Если надобно, пойдем к нему; он недавно пошел отсюда домой, а живет он близко, в Мелите. Сказав это, мы пошли, и застали Антифона"}, "127a": {"g": "ταῦτα εἰπόντες ἐβαδίζομεν, καὶ κατελάβομεν τὸν Ἀντιφῶντα οἴκοι, χαλινόν τινα χαλκεῖ ἐκδιδόντα σκευάσαι· ἐπειδὴ δὲ ἐκείνου ἀπηλλάγη οἵ τε ἀδελφοὶ ἔλεγον αὐτῷ ὧν ἕνεκα παρεῖμεν, ἀνεγνώρισέν τέ με ἐκ τῆς προτέρας ἐπιδημίας καί με ἠσπάζετο, καὶ δεομένων ἡμῶν διελθεῖν τοὺς λόγους, τὸ μὲν πρῶτον ὤκνει—πολὺ γὰρ ἔφη ἔργον εἶναι— ἔπειτα μέντοι διηγεῖτο. ἔφη δὲ δὴ ὁ Ἀντιφῶν λέγειν τὸν Πυθόδωρον ὅτι ἀφίκοιντό ποτε εἰς Παναθήναια τὰ μεγάλα", "r": "дома — отдававшим слесарю исправить какую-то узду. Когда отпустил он слесаря, братья сказали ему, зачем мы пришли. Антифон узнал меня, не видавши с времени первого моего приезда в Афины, и обнял. Мы стали просить пересказать нам те беседы; но он сперва отказывался, — дело, говорит, большое; — однакож потом рассказал.\n\nПо словам Антифона, Пифодор говорил, что некогда Зенон и Парменид пришли на великие панафинеи. Парменид"}, "127b": {"g": "Ζήνων τε καὶ Παρμενίδης. τὸν μὲν οὖν Παρμενίδην εὖ μάλα ἤδη πρεσβύτην εἶναι, σφόδρα πολιόν, καλὸν δὲ κἀγαθὸν τὴν ὄψιν, περὶ ἔτη μάλιστα πέντε καὶ ἑξήκοντα· Ζήνωνα δὲ ἐγγὺς τῶν τετταράκοντα τότε εἶναι, εὐμήκη δὲ καὶ χαρίεντα ἰδεῖν, καὶ λέγεσθαι αὐτὸν παιδικὰ τοῦ Παρμενίδου γεγονέναι. καταλύειν δὲ αὐτοὺς ἔφη παρὰ τῷ", "r": "был уже очень стар, совершенно сед, но на вид красив и показен, — имел от роду около шестидесяти пяти лет; а Зенон был тогда лет почти сорока, росту высокого и приятной наружности. Про него рассказывали, что он был любимцем Парменида. Квартировали они, говорил, у Пифодора, в Керамике, что за стеною. Сюда-то пришли и Сократ, и многие другие с ним, кому хотелось"}, "127c": {"g": "Πυθοδώρῳ ἐκτὸς τείχους ἐν Κεραμεικῷ· οἷ δὴ καὶ ἀφικέσθαι τόν τε Σωκράτη καὶ ἄλλους τινὰς μετʼ αὐτοῦ πολλούς, ἐπιθυμοῦντας ἀκοῦσαι τῶν τοῦ Ζήνωνος γραμμάτων—τότε γὰρ αὐτὰ πρῶτον ὑπʼ ἐκείνων κομισθῆναι—Σωκράτη δὲ εἶναι τότε σφόδρα νέον. ἀναγιγνώσκειν οὖν αὐτοῖς τὸν Ζήνωνα αὐτόν, τὸν δὲ Παρμενίδην τυχεῖν ἔξω ὄντα· καὶ εἶναι πάνυ βραχὺ ἔτι λοιπὸν τῶν λόγων ἀναγιγνωσκομένων, ἡνίκα", "r": "послушать сочинения Зенона, которые тогда в первый раз были принесены ими. Сократ был в ту пору очень молод. Зенон сам стал читать свои сочинения, а Пармениду случилось выйти вон. И оставалось дочитать еще немногое из тех книг, — как, по рассказу Пифодора, вошел со двора и сам он, и с ним Парменид и Аристотель,"}, "127d": {"g": "αὐτός τε ἐπεισελθεῖν ἔφη ὁ Πυθόδωρος ἔξωθεν καὶ τὸν Παρμενίδην μετʼ αὐτοῦ καὶ Ἀριστοτέλη τὸν τῶν τριάκοντα γενόμενον, καὶ σμίκρʼ ἄττα ἔτι ἐπακοῦσαι τῶν γραμμάτων· οὐ μὴν αὐτός γε, ἀλλὰ καὶ πρότερον ἀκηκοέναι τοῦ Ζήνωνος. τὸν οὖν Σωκράτη ἀκούσαντα πάλιν τε κελεῦσαι τὴν πρώτην ὑπόθεσιν τοῦ πρώτου λόγου ἀναγνῶναι, καὶ ἀναγνωσθείσης,", "r": "впоследствии один из «тридцати», так что лишь немногое пришлось им прослушать из написанного; впрочем сам-то Пифодор уже прежде слушал Зенона.\n\nПрослушав сочинение, Сократ просил снова прочитать первое положение первой книги, и когда оно было прочитано, сказал: Как ты говоришь Зенон? Если существующее"}, "127e": {"g": "πῶς, φάναι, ὦ Ζήνων, τοῦτο λέγεις; εἰ πολλά ἐστι τὰ ὄντα, ὡς ἄρα δεῖ αὐτὰ ὅμοιά τε εἶναι καὶ ἀνόμοια, τοῦτο δὲ δὴ ἀδύνατον· οὔτε γὰρ τὰ ἀνόμοια ὅμοια οὔτε τὰ ὅμοια ἀνόμοια οἷόν τε εἶναι; οὐχ οὕτω λέγεις; οὕτω, φάναι τὸν Ζήνωνα. οὐκοῦν εἰ ἀδύνατον τά τε ἀνόμοια ὅμοια εἶναι καὶ τὰ ὅμοια ἀνόμοια, ἀδύνατον δὴ καὶ πολλὰ εἶναι; εἰ γὰρ πολλὰ εἴη, πάσχοι ἂν τὰ ἀδύνατα. ἆρα τοῦτό ἐστιν ὃ βούλονταί σου οἱ λόγοι, οὐκ ἄλλο τι ἢ διαμάχεσθαι παρὰ πάντα τὰ λεγόμενα ὡς οὐ πολλά ἐστι; καὶ τούτου αὐτοῦ οἴει σοι τεκμήριον εἶναι ἕκαστον τῶν λόγων, ὥστε καὶ ἡγῇ τοσαῦτα τεκμήρια παρέχεσθαι, ὅσουσπερ λόγους γέγραφας, ὡς οὐκ", "r": "есть многое, то оно должно быть вместе и подобное и не подобное? Но этого не может быть: ибо ни не подобному нельзя быть подобным, ни подобному — неподобным. Не так ли ты говоришь? — Так, отвечал Зенон. — Если же невозможно, чтобы не подобное было подобным, и подобное — не подобным, то не может быть и многое; ведь если бы было многое, то оно испытывало бы то, что невозможно. Не этого ли хотят твои книги? Не иного чего, то есть, хотят они, как, вопреки всему, что говорится, спорить, что многого нет? И доказательство этого самого представляет у тебя, думаешь, каждая книга; так что, по твоему мнению, предложено у тебя столько доказательств тому,"}, "128a": {"g": "ἔστι πολλά; οὕτω λέγεις, ἢ ἐγὼ οὐκ ὀρθῶς καταμανθάνω; οὔκ, ἀλλά, φάναι τὸν Ζήνωνα, καλῶς συνῆκας ὅλον τὸ γράμμα ὃ βούλεται. μανθάνω, εἰπεῖν τὸν Σωκράτη, ὦ Παρμενίδη, ὅτι Ζήνων ὅδε οὐ μόνον τῇ ἄλλῃ σου φιλίᾳ βούλεται ᾠκειῶσθαι, ἀλλὰ καὶ τῷ συγγράμματι. ταὐτὸν γὰρ γέγραφε τρόπον τινὰ ὅπερ σύ, μεταβάλλων δὲ ἡμᾶς πειρᾶται ἐξαπατᾶν ὡς ἕτερόν τι λέγων. σὺ μὲν γὰρ ἐν τοῖς ποιήμασιν ἓν φῂς εἶναι τὸ", "r": "что многого нет, сколько написал ты книг. Так ли ты говоришь, или я неправильно понимаю? — Нет, сказал Зенон, ты хорошо выразумел всё сочинение, чего оно хочет. — Я замечаю, Парменид, продолжал Сократ, что этот Зенон хочет угодить тебе не только другими знаками дружбы, но и сочинением; потому что он написал в некотором роде то же, что и ты, и только ловким изворотом старается обмануть нас, будто говорит что-то другое. Ты в своих поэмах полагаешь, что всё есть одно, и приводишь на то прекрасные доказательства: а этот утверждает, что"}, "128b": {"g": "πᾶν, καὶ τούτων τεκμήρια παρέχῃ καλῶς τε καὶ εὖ· ὅδε δὲ αὖ οὐ πολλά φησιν εἶναι, τεκμήρια δὲ καὶ αὐτὸς πάμπολλα καὶ παμμεγέθη παρέχεται. τὸ οὖν τὸν μὲν ἓν φάναι, τὸν δὲ μὴ πολλά, καὶ οὕτως ἑκάτερον λέγειν ὥστε μηδὲν τῶν αὐτῶν εἰρηκέναι δοκεῖν σχεδόν τι λέγοντας ταὐτά, ὑπὲρ ἡμᾶς τοὺς ἄλλους φαίνεται ὑμῖν τὰ εἰρημένα εἰρῆσθαι. ναί, φάναι τὸν Ζήνωνα, ὦ Σώκρατες. σὺ δʼ οὖν τὴν ἀλήθειαν τοῦ γράμματος οὐ πανταχοῦ ᾔσθησαι. καίτοι", "r": "существующее не есть многое, и тоже представляет много весьма сильных доказательств. Итак, у одного из вас полагается одно, у другого — не многое, и оба вы выражаетесь так, что, говоря почти то же самое, по-видимому, не высказываете ничего тожественного. Такой способ выражений, кажется, выше наших понятий. — Да, Сократ, сказал Зенон: — но истину сочинения ты постиг не вполне,"}, "128c": {"g": "ὥσπερ γε αἱ Λάκαιναι σκύλακες εὖ μεταθεῖς τε καὶ ἰχνεύεις τὰ λεχθέντα· ἀλλὰ πρῶτον μέν σε τοῦτο λανθάνει, ὅτι οὐ παντάπασιν οὕτω σεμνύνεται τὸ γράμμα, ὥστε ἅπερ σὺ λέγεις διανοηθὲν γραφῆναι, τοὺς ἀνθρώπους δὲ ἐπικρυπτόμενον ὥς τι μέγα διαπραττόμενον· ἀλλὰ σὺ μὲν εἶπες τῶν συμβεβηκότων τι, ἔστι δὲ τό γε ἀληθὲς βοήθειά τις ταῦτα τὰ γράμματα τῷ Παρμενίδου λόγῳ πρὸς τοὺς ἐπιχειροῦντας", "r": "хотя, будто лакедемонский щенок, хорошо преследуешь и ловишь чутьем читаемое. От тебя, во-первых, утаилось, что мое сочинение вовсе не так заносчиво, чтобы задаваться задними мыслями, о которых ты говоришь, — как будто бы, то есть, я совершал что-то важное, скрывая это от людей. Затем, ты привел это как побочный вывод, но это и есть настоящая цель моего сочинения — оказать некоторую поддержку положению Парменида против тех, которые решаются смеяться над ним, говоря, что если"}, "128d": {"g": "αὐτὸν κωμῳδεῖν ὡς εἰ ἕν ἐστι, πολλὰ καὶ γελοῖα συμβαίνει πάσχειν τῷ λόγῳ καὶ ἐναντία αὑτῷ. ἀντιλέγει δὴ οὖν τοῦτο τὸ γράμμα πρὸς τοὺς τὰ πολλὰ λέγοντας, καὶ ἀνταποδίδωσι ταὐτὰ καὶ πλείω, τοῦτο βουλόμενον δηλοῦν, ὡς ἔτι γελοιότερα πάσχοι ἂν αὐτῶν ἡ ὑπόθεσις, εἰ πολλά ἐστιν, ἢ ἡ τοῦ ἓν εἶναι, εἴ τις ἱκανῶς ἐπεξίοι. διὰ τοιαύτην δὴ φιλονικίαν ὑπὸ νέου ὄντος ἐμοῦ ἐγράφη, καί τις αὐτὸ ἔκλεψε γραφέν, ὥστε οὐδὲ βουλεύσασθαι ἐξεγένετο εἴτʼ", "r": "есть одно, то положению его приходится вынести много и смешного и противоречивого. Так это сочинение дает отпор тем, которые допускают многое, и воздает им тем же и еще бо̀льшим, стараясь показать, что гораздо смешнее окажется собственное их положение, будто есть многое, чем положение об одном, если кто будет достаточно последователен. Из такого рода задора, я писал еще в молодости; но мое писанье кто-то похитил, так что не было места и вопросу, выпускать ли эти"}, "128e": {"g": "ἐξοιστέον αὐτὸ εἰς τὸ φῶς εἴτε μή. ταύτῃ οὖν σε λανθάνει, ὦ Σώκρατες, ὅτι οὐχ ὑπὸ νέου φιλονικίας οἴει αὐτὸ γεγράφθαι, ἀλλʼ ὑπὸ πρεσβυτέρου φιλοτιμίας· ἐπεί, ὅπερ γʼ εἶπον, οὐ κακῶς ἀπῄκασας. ἀλλʼ ἀποδέχομαι, φάναι τὸν Σωκράτη, καὶ ἡγοῦμαι ὡς λέγεις ἔχειν. τόδε δέ μοι εἰπέ· οὐ νομίζεις εἶναι αὐτὸ καθʼ", "r": "книги в свет, или нет. Так вот в чём ошибся ты, Сократ: что мое сочинение, ты думаешь, написано не из юношеского задора, а из честолюбия более зрелых лет. Впрочем, что̀ я в нём говорил-то, ты схватил не худо. — Я принимаю это, примолвил Сократ, и полагаю так, ка̀к ты говоришь. Но скажи мне вот что: не думаешь"}, "129a": {"g": "αὑτὸ εἶδός τι ὁμοιότητος, καὶ τῷ τοιούτῳ αὖ ἄλλο τι ἐναντίον, ὃ ἔστιν ἀνόμοιον· τούτοιν δὲ δυοῖν ὄντοιν καὶ ἐμὲ καὶ σὲ καὶ τἆλλα ἃ δὴ πολλὰ καλοῦμεν μεταλαμβάνειν; καὶ τὰ μὲν τῆς ὁμοιότητος μεταλαμβάνοντα ὅμοια γίγνεσθαι ταύτῃ τε καὶ κατὰ τοσοῦτον ὅσον ἂν μεταλαμβάνῃ, τὰ δὲ τῆς ἀνομοιότητος ἀνόμοια, τὰ δὲ ἀμφοτέρων ἀμφότερα; εἰ δὲ καὶ πάντα ἐναντίων ὄντων ἀμφοτέρων μεταλαμβάνει, καὶ ἔστι τῷ μετέχειν ἀμφοῖν ὅμοιά τε καὶ ἀνόμοια αὐτὰ", "r": "ли ты, что есть некоторый вид подобия сам по себе, и есть опять иной, такому виду противный, то есть, действительно не подобный? и что этим двум видам причастны и я, и ты, и всё прочее, что мы называем многим? И то, что принимает подобие, не делается ли подобным так и настолько, насколько принимает, что̀ неподобие — не подобным, а что̀ то и другое — тем и другим? Да что удивительного, если даже и всё принимает эти противности, — ту и другую, и, став причастно"}, "129b": {"g": "αὑτοῖς, τί θαυμαστόν; εἰ μὲν γὰρ αὐτὰ τὰ ὅμοιά τις ἀπέφαινεν ἀνόμοια γιγνόμενα ἢ τὰ ἀνόμοια ὅμοια, τέρας ἂν οἶμαι ἦν· εἰ δὲ τὰ τούτων μετέχοντα ἀμφοτέρων ἀμφότερα ἀποφαίνει πεπονθότα, οὐδὲν ἔμοιγε, ὦ Ζήνων, ἄτοπον δοκεῖ, οὐδέ γε εἰ ἓν ἅπαντα ἀποφαίνει τις τῷ μετέχειν τοῦ ἑνὸς καὶ ταὐτὰ ταῦτα πολλὰ τῷ πλήθους αὖ μετέχειν. ἀλλʼ εἰ ὃ ἔστιν ἕν, αὐτὸ τοῦτο πολλὰ ἀποδείξει καὶ αὖ τὰ πολλὰ δὴ", "r": "обеих, может быть подобным и не подобным само себе? Ведь если бы кто объявил, что само подобное бывает не подобным, или неподобное — подобным, то это было бы, думаю, чудовищно: напротив, если бы захотел кто утверждать, что вещи, причастные обеих этих крайностей, принимают свойства той и другой, то, мне кажется, Зенон, тут не было бы ничего странного, — как и в том-то, если бы кто сказал, что всё есть одно чрез причастность одному, и то же самое есть опять многое чрез причастность множеству. Но как скоро начнут доказывать, что одно само в себе — это именно есть многое, и, наоборот, многое — одно, то я уже удивлюсь. То же самое и"}, "129c": {"g": "ἕν, τοῦτο ἤδη θαυμάσομαι. καὶ περὶ τῶν ἄλλων ἁπάντων ὡσαύτως· εἰ μὲν αὐτὰ τὰ γένη τε καὶ εἴδη ἐν αὑτοῖς ἀποφαίνοι τἀναντία ταῦτα πάθη πάσχοντα, ἄξιον θαυμάζειν· εἰ δʼ ἐμὲ ἕν τις ἀποδείξει ὄντα καὶ πολλά, τί θαυμαστόν, λέγων, ὅταν μὲν βούληται πολλὰ ἀποφῆναι, ὡς ἕτερα μὲν τὰ ἐπὶ δεξιά μού ἐστιν, ἕτερα δὲ τὰ ἐπʼ ἀριστερά, καὶ ἕτερα μὲν τὰ πρόσθεν, ἕτερα δὲ τὰ ὄπισθεν, καὶ ἄνω καὶ κάτω ὡσαύτως—πλήθους γὰρ οἶμαι μετέχω—ὅταν δὲ ἕν, ἐρεῖ ὡς", "r": "в отношении прочего: если, то есть, объявляют, что самые роды и виды заключают в себе эти противные свойства, этому можно удивиться. А когда будет кто доказывать, что я, напр., вместе и одно и многое, — что тут удивительного? В этом случае, желая выставить многое, он сказал бы, что я представляю иное с правой стороны и иное с левой, иное спереди и иное сзади, иное также сверху и иное снизу, — ибо я причастен, думаю, множества; а выставляя одно, скажет, что между нами семерыми, как"}, "129d": {"g": "ἑπτὰ ἡμῶν ὄντων εἷς ἐγώ εἰμι ἄνθρωπος μετέχων καὶ τοῦ ἑνός· ὥστε ἀληθῆ ἀποφαίνει ἀμφότερα. ἐὰν οὖν τις τοιαῦτα ἐπιχειρῇ πολλὰ καὶ ἓν ταὐτὸν ἀποφαίνειν, λίθους καὶ ξύλα καὶ τὰ τοιαῦτα, τὶ φήσομεν αὐτὸν πολλὰ καὶ ἓν ἀποδεικνύναι, οὐ τὸ ἓν πολλὰ οὐδὲ τὰ πολλὰ ἕν, οὐδέ τι θαυμαστὸν λέγειν, ἀλλʼ ἅπερ ἂν πάντες ὁμολογοῖμεν· ἐὰν δέ τις ὧν νυνδὴ ἐγὼ ἔλεγον πρῶτον μὲν διαιρῆται χωρὶς αὐτὰ καθʼ αὑτὰ τὰ εἴδη, οἷον ὁμοιότητά τε καὶ ἀνομοιότητα καὶ πλῆθος", "r": "человек, я — один, — ибо причастен и одного; так что справедливо скажет и то и другое. Итак, кто пытался бы такого рода предметы представлять как одно и многое, — камни, дерева̀ и прочее, — тот, мы скажем, доказывал бы многое и одно, — но не одно как многое, и не многое как одно, — не что-нибудь удивительное утверждал бы он, а то, в чём все мы можем соглашаться. Но если бы он, как говорил я сейчас, взял, во-первых, виды особо сами по себе, — как-то, подобие и неподобие, множество и"}, "129e": {"g": "καὶ τὸ ἓν καὶ στάσιν καὶ κίνησιν καὶ πάντα τὰ τοιαῦτα, εἶτα ἐν ἑαυτοῖς ταῦτα δυνάμενα συγκεράννυσθαι καὶ διακρίνεσθαι ἀποφαίνῃ, ἀγαίμην ἂν ἔγωγʼ, ἔφη, θαυμαστῶς, ὦ Ζήνων. ταῦτα δὲ ἀνδρείως μὲν πάνυ ἡγοῦμαι πεπραγματεῦσθαι· πολὺ μεντἂν ὧδε μᾶλλον, ὡς λέγω, ἀγασθείην εἴ τις ἔχοι τὴν αὐτὴν ταύτην ἀπορίαν ἐν αὐτοῖς τοῖς εἴδεσι", "r": "единство, стояние и движение, и всё такое, — потом объявил бы, что они могут между собою смешиваться и разделяться; то я, говорит, чрезвычайно обрадовался бы, Зенон. Твоя мысль, я нахожу, обработана весьма стойко; но этой, полагаю, обрадовался бы я более: если бы кто то же самое недоумение, — как вы усматриваете его завитым в вещах видимых, — мог показать и в тех, которые подлежат рассудку, различным образом завитое в"}, "130a": {"g": "παντοδαπῶς πλεκομένην, ὥσπερ ἐν τοῖς ὁρωμένοις διήλθετε, οὕτως καὶ ἐν τοῖς λογισμῷ λαμβανομένοις ἐπιδεῖξαι. λέγοντος δή, ἔφη ὁ Πυθόδωρος, τοῦ Σωκράτους ταῦτα αὐτὸς μὲν ἂν οἴεσθαι ἐφʼ ἑκάστου ἄχθεσθαι τόν τε Παρμενίδην καὶ τὸν Ζήνωνα, τοὺς δὲ πάνυ τε αὐτῷ προσέχειν τὸν νοῦν καὶ θαμὰ εἰς ἀλλήλους βλέποντας μειδιᾶν ὡς ἀγαμένους τὸν Σωκράτη. ὅπερ οὖν καὶ παυσαμένου αὐτοῦ εἰπεῖν τὸν Παρμενίδην· ὦ Σώκρατες, φάναι, ὡς ἄξιος εἶ", "r": "самых видах.\n\nПифодор, по его словам, думал, что, когда Сократ говорил это, Парменид и Зенон, при каждой мысли, должны были питать досаду; а они очень внимательно слушали его и, часто взглядывая друг на друга, улыбались, с выражением удивления Сократу. И вот, как только прекратил"}, "130b": {"g": "ἄγασθαι τῆς ὁρμῆς τῆς ἐπὶ τοὺς λόγους. καί μοι εἰπέ, αὐτὸς σὺ οὕτω διῄρησαι ὡς λέγεις, χωρὶς μὲν εἴδη αὐτὰ ἄττα, χωρὶς δὲ τὰ τούτων αὖ μετέχοντα; καί τί σοι δοκεῖ εἶναι αὐτὴ ὁμοιότης χωρὶς ἧς ἡμεῖς ὁμοιότητος ἔχομεν, καὶ ἓν δὴ καὶ πολλὰ καὶ πάντα ὅσα νυνδὴ Ζήνωνος ἤκουες; ἔμοιγε, φάναι τὸν Σωκράτη. ἦ καὶ τὰ τοιαῦτα, εἰπεῖν τὸν Παρμενίδην, οἷον δικαίου τι εἶδος αὐτὸ καθʼ αὑτὸ καὶ καλοῦ καὶ ἀγαθοῦ καὶ πάντων αὖ τῶν τοιούτων; ναί, φάναι.", "r": "он свою речь, Парменид сказал: Сократ! твоя ревность к исследованиям достойна удивления. Но скажи мне: сам ли ты так различил, как говоришь, особо — некоторые виды сами в себе, и особо — то, что̀ им причастно? и кажется ли тебе само подобие чем-нибудь отдельным от того, которое есть у нас, равно как одно, многое и всё; про что теперь слышал ты от Зенона? — Кажется, отвечал Сократ. — И ты принимаешь, спросил Парменид, особый некоторый вид для таких явлений, как справедливое, прекрасное, доброе и всё такое? — Да, сказал он. — Что же? — и"}, "130c": {"g": "τί δʼ, ἀνθρώπου εἶδος χωρὶς ἡμῶν καὶ τῶν οἷοι ἡμεῖς ἐσμεν πάντων, αὐτό τι εἶδος ἀνθρώπου ἢ πυρὸς ἢ καὶ ὕδατος; ἐν ἀπορίᾳ, φάναι, πολλάκις δή, ὦ Παρμενίδη, περὶ αὐτῶν γέγονα, πότερα χρὴ φάναι ὥσπερ περὶ ἐκείνων ἢ ἄλλως. ἦ καὶ περὶ τῶνδε, ὦ Σώκρατες, ἃ καὶ γελοῖα δόξειεν ἂν εἶναι, οἷον θρὶξ καὶ πηλὸς καὶ ῥύπος ἢ ἄλλο τι ἀτιμότατόν τε καὶ φαυλότατον, ἀπορεῖς εἴτε χρὴ φάναι καὶ τούτων", "r": "вид человека, особый от нас и от всего такого, каковы мы, — то есть, некоторый самобытный вид человека, или огня, или воды? — Касательно этих предметов, Парменид, отвечал Сократ, часто был я в недоумении, должно ли полагать о них то же, что о других, или иное. — Не недоумеваешь ли ты и в отношении таких вещей, Сократ, — для них оно было бы и смешно, — каковы, например, волос, грязь, нечистота, или что-либо иное, самое презренное и ничтожное: должно ли и для каждой из них полагать особый вид, отличный от того, что берем мы руками, или не"}, "130d": {"g": "ἑκάστου εἶδος εἶναι χωρίς, ὂν ἄλλο αὖ ἢ ὧν τι ἡμεῖς μεταχειριζόμεθα, εἴτε καὶ μή; οὐδαμῶς, φάναι τὸν Σωκράτη, ἀλλὰ ταῦτα μέν γε ἅπερ ὁρῶμεν, ταῦτα καὶ εἶναι· εἶδος δέ τι αὐτῶν οἰηθῆναι εἶναι μὴ λίαν ᾖ ἄτοπον. ἤδη μέντοι ποτέ με καὶ ἔθραξε μή τι ᾖ περὶ πάντων ταὐτόν· ἔπειτα ὅταν ταύτῃ στῶ, φεύγων οἴχομαι, δείσας μή ποτε εἴς τινα βυθὸν φλυαρίας ἐμπεσὼν διαφθαρῶ· ἐκεῖσε δʼ οὖν ἀφικόμενος, εἰς ἃ νυνδὴ ἐλέγομεν εἴδη ἔχειν, περὶ ἐκεῖνα πραγματευόμενος διατρίβω.", "r": "должно? — Никак, отвечал Сократ; в этих-то, что̀ мы видим, то̀ одно и есть: представлять, еще некоторый вид таких вещей ка̀к бы не было слишком странно. Меня впрочем уже беспокоит иногда мысль, не вышло бы того же и со всем другим: но если остановлюсь на этом, я готов потом бежать, из страха, как бы не провалиться и не погибнуть в какой-то бездонной болтовне. И вот, пришедши мышлением сюда, — к тем видам, о которых теперь только говорили, — я рассуждаю о них испытательно. — Потому что"}, "130e": {"g": "νέος γὰρ εἶ ἔτι, φάναι τὸν Παρμενίδην, ὦ Σώκρατες, καὶ οὔπω σου ἀντείληπται φιλοσοφία ὡς ἔτι ἀντιλήψεται κατʼ ἐμὴν δόξαν, ὅτε οὐδὲν αὐτῶν ἀτιμάσεις· νῦν δὲ ἔτι πρὸς ἀνθρώπων ἀποβλέπεις δόξας διὰ τὴν ἡλικίαν. τόδε δʼ οὖν μοι εἰπέ. δοκεῖ σοι, ὡς φῄς, εἶναι εἴδη ἄττα, ὧν τάδε τὰ ἄλλα μεταλαμβάνοντα τὰς ἐπωνυμίας αὐτῶν ἴσχειν, οἷον", "r": "ты еще молод, Сократ, сказал Парменид, и философия пока не охватила тебя, как охватит, по моему мнению, когда не будешь пренебрегать ничем этим. Теперь ты, по своему возрасту, смотришь еще на человеческие мнения. Скажи-ка мне вот что: тебе кажется, говоришь, что есть"}, "131a": {"g": "ὁμοιότητος μὲν μεταλαβόντα ὅμοια, μεγέθους δὲ μεγάλα, κάλλους δὲ καὶ δικαιοσύνης δίκαιά τε καὶ καλὰ γίγνεσθαι; πάνυ γε, φάναι τὸν Σωκράτη. οὐκοῦν ἤτοι ὅλου τοῦ εἴδους ἢ μέρους ἕκαστον τὸ μεταλαμβάνον μεταλαμβάνει; ἢ ἄλλη τις ἂν μετάληψις χωρὶς τούτων γένοιτο; καὶ πῶς ἄν; εἶπεν. πότερον οὖν δοκεῖ σοι ὅλον τὸ εἶδος ἐν ἑκάστῳ εἶναι τῶν πολλῶν ἓν ὄν, ἢ πῶς; τί γὰρ κωλύει, φάναι τὸν Σωκράτη, ὦ Παρμενίδη, ἓν εἶναι ;", "r": "некоторые виды, от которых прочие вещи, по участию в них, получают свои названия; причастная, например, подобию становится подобною, величине — великою, красоте и справедливости — справедливою и прекрасною. — Конечно, сказал Сократ. — Но каждая, воспринимающая вид, весь ли его воспринимает, или часть? или воспринятие возможно еще иное, помимо этого? — Но какое же? сказал он. — Так думаешь ли, что весь вид, составляя одно, содержится в каждой из многих вещей, — или как? — Да что же препятствует, Парменид, содержаться ему? отвечал Сократ. —"}, "131b": {"g": "ἓν ἄρα ὂν καὶ ταὐτὸν ἐν πολλοῖς καὶ χωρὶς οὖσιν ὅλον ἅμα ἐνέσται, καὶ οὕτως αὐτὸ αὑτοῦ χωρὶς ἂν εἴη. οὐκ ἄν, εἴ γε, φάναι, οἷον εἰ ἡμέρα εἴη μία καὶ ἡ αὐτὴ οὖσα πολλαχοῦ ἅμα ἐστὶ καὶ οὐδέν τι μᾶλλον αὐτὴ αὑτῆς χωρίς ἐστιν, εἰ οὕτω καὶ ἕκαστον τῶν εἰδῶν ἓν ἐν πᾶσιν ἅμα ταὐτὸν εἴη. ἡδέως γε, φάναι, ὦ Σώκρατες, ἓν ταὐτὸν ἅμα πολλαχοῦ ποιεῖς, οἷον εἰ ἱστίῳ καταπετάσας πολλοὺς ἀνθρώπους φαίης ἓν ἐπὶ πολλοῖς εἶναι ὅλον· ἢ οὐ τὸ τοιοῦτον ἡγῇ λέγειν;", "r": "Следовательно, будучи одним и тем же самым — во многих вещах, существующих особо, он будет содержаться во всех всецело, и таким образом обособится сам от себя. — Не обособится, возразил Сократ: как, например, день, будучи одним и тем же, в одно и то же время находится во многих местах, и оттого нисколько не отделяется сам от себя; так, может быть, и каждый из видов содержится во всём, как один и тот же. — Куда любезен ты, Сократ, сказал Парменид, что одно и то же полагаешь во многих местах, — всё равно, как если бы, закрыв завесою многих людей, говорил, что одно находится на многих всецело. Или не это, думаешь,"}, "131c": {"g": "ἴσως, φάναι. ἦ οὖν ὅλον ἐφʼ ἑκάστῳ τὸ ἱστίον εἴη ἄν, ἢ μέρος αὐτοῦ ἄλλο ἐπʼ ἄλλῳ; μέρος. μεριστὰ ἄρα, φάναι, ὦ Σώκρατες, ἔστιν αὐτὰ τὰ εἴδη, καὶ τὰ μετέχοντα αὐτῶν μέρους ἂν μετέχοι, καὶ οὐκέτι ἐν ἑκάστῳ ὅλον, ἀλλὰ μέρος ἑκάστου ἂν εἴη. φαίνεται οὕτω γε. ἦ οὖν ἐθελήσεις, ὦ Σώκρατες, φάναι τὸ ἓν εἶδος ἡμῖν τῇ ἀληθείᾳ μερίζεσθαι, καὶ ἔτι ἓν ἔσται; οὐδαμῶς, εἰπεῖν. ὅρα γάρ, φάναι· εἰ αὐτὸ τὸ μέγεθος μεριεῖς καὶ ἕκαστον", "r": "выражают твои слова? — Может быть, отвечал он. — Так вся ли завеса была бы на каждом, или части её, — по одной? — Части. — Стало быть, и самые виды делимы, Сократ, сказал Парменид, — и причастное им должно быть причастно частей, и в каждой вещи будет уже не целый вид, а всегда часть. — Представляется, конечно, так. — Что же? захочешь ли утверждать, Сократ, что вид, как одно, у нас действительно делится и, делясь, всё-таки будет одно? — Отнюдь нет, отвечал он. — Смотри-ка, продолжал Парменид: если ты будешь делить самую великость, и каждый из многих больших предметов"}, "131d": {"g": "τῶν πολλῶν μεγάλων μεγέθους μέρει σμικροτέρῳ αὐτοῦ τοῦ μεγέθους μέγα ἔσται, ἆρα οὐκ ἄλογον φανεῖται; πάνυ γʼ, ἔφη. τί δέ; τοῦ ἴσου μέρος ἕκαστον σμικρὸν ἀπολαβόν τι ἕξει ᾧ ἐλάττονι ὄντι αὐτοῦ τοῦ ἴσου τὸ ἔχον ἴσον τῳ ἔσται; ἀδύνατον. ἀλλὰ τοῦ σμικροῦ μέρος τις ἡμῶν ἕξει, τούτου δὲ αὐτοῦ τὸ σμικρὸν μεῖζον ἔσται ἅτε μέρους ἑαυτοῦ ὄντος, καὶ οὕτω δὴ αὐτὸ τὸ σμικρὸν μεῖζον ἔσται· ᾧ δʼ ἂν προστεθῇ τὸ", "r": "окажется велик её частью, которая меньше самой великости, — не представится ли это несообразным? — Конечно, сказал он. — Что же? каждая вещь, получив какую-нибудь часть равного, — которая меньше в сравнении с самым равным, — будет ли заключать в себе нечто, чем сравняется с какою-либо вещию? — Невозможно. — Но положим, кто-либо из нас примет часть малости: сама малость будет больше её, так как это её часть. И тогда как сама малость окажется больше, то̀, к чему приложится"}, "131e": {"g": "ἀφαιρεθέν, τοῦτο σμικρότερον ἔσται ἀλλʼ οὐ μεῖζον ἢ πρίν. οὐκ ἂν γένοιτο, φάναι, τοῦτό γε. τίνα οὖν τρόπον, εἰπεῖν, ὦ Σώκρατες, τῶν εἰδῶν σοι τὰ ἄλλα μεταλήψεται, μήτε κατὰ μέρη μήτε κατὰ ὅλα μεταλαμβάνειν δυνάμενα; οὐ μὰ τὸν Δία, φάναι, οὔ μοι δοκεῖ εὔκολον εἶναι τὸ τοιοῦτον οὐδαμῶς διορίσασθαι. τί δὲ δή; πρὸς τόδε πῶς ἔχεις; τὸ ποῖον;", "r": "отнятое, станет, напротив, меньше, а не больше, чем прежде. — И этого-то быть не должно, сказал Сократ — Каким же образом, Сократ, спросил Парменид, всё прочее будет причастно у тебя видов, когда не может принимать их ни по частям, ни целыми? — Клянусь Зевсом! отвечал Сократ: такое дело, мне кажется, вовсе не легко решить. — Что же теперь? Как ты думаешь"}, "132a": {"g": "οἶμαί σε ἐκ τοῦ τοιοῦδε ἓν ἕκαστον εἶδος οἴεσθαι εἶναι· ὅταν πόλλʼ ἄττα μεγάλα σοι δόξῃ εἶναι, μία τις ἴσως δοκεῖ ἰδέα ἡ αὐτὴ εἶναι ἐπὶ πάντα ἰδόντι, ὅθεν ἓν τὸ μέγα ἡγῇ εἶναι. ἀληθῆ λέγεις, φάναι. τί δʼ αὐτὸ τὸ μέγα καὶ τἆλλα τὰ μεγάλα, ἐὰν ὡσαύτως τῇ ψυχῇ ἐπὶ πάντα ἴδῃς, οὐχὶ ἕν τι αὖ μέγα φανεῖται, ᾧ ταῦτα πάντα μεγάλα φαίνεσθαι; ἔοικεν. ἄλλο ἄρα εἶδος μεγέθους ἀναφανήσεται, παρʼ αὐτό τε τὸ μέγεθος γεγονὸς καὶ τὰ μετέχοντα αὐτοῦ· καὶ ἐπὶ τούτοις αὖ", "r": "вот о чём? — О чём? — Я полагаю, что ты каждый вид почитаешь одним по следующей причине. Когда покажется тебе много каких-нибудь величин, ты, смотря на все их, представляешь, может быть, одну какую-то идею, и отсюда великое почитаешь одним. — Это правда, сказал он. — А что̀ само великое с прочими величинами? Если таким же образом взглянешь душою на всё, не представится ли опять одно великое, чрез которое по необходимости всё это является великим? — Вероятно. — Стало быть, тут представится иной вид великости, происшедший независимо от самой великости и от того, что̀"}, "132b": {"g": "πᾶσιν ἕτερον, ᾧ ταῦτα πάντα μεγάλα ἔσται· καὶ οὐκέτι δὴ ἓν ἕκαστόν σοι τῶν εἰδῶν ἔσται, ἀλλὰ ἄπειρα τὸ πλῆθος. ἀλλά, φάναι, ὦ Παρμενίδη, τὸν Σωκράτη, μὴ τῶν εἰδῶν ἕκαστον ᾖ τούτων νόημα, καὶ οὐδαμοῦ αὐτῷ προσήκῃ ἐγγίγνεσθαι ἄλλοθι ἢ ἐν ψυχαῖς· οὕτω γὰρ ἂν ἕν γε ἕκαστον εἴη καὶ οὐκ ἂν ἔτι πάσχοι ἃ νυνδὴ ἐλέγετο. τί οὖν; φάναι, ἓν ἕκαστόν ἐστι τῶν νοημάτων, νόημα δὲ οὐδενός; ἀλλʼ ἀδύνατον, εἰπεῖν. ἀλλὰ τινός; ναί.", "r": "причастно ей, а над этими всеми — опять другой, по которому выйдут велики эти, — и каждый из видов уже не будет у тебя один, но откроется их бесконечное множество. — Но каждый из видов, Парменид, заметил Сократ, не есть ли мысль? а мысли негде больше быть, как в душах: так-то каждый остался бы, конечно, одним, и не подвергался бы уже тому, о чём сейчас было говорено. — Так что же? спросил Парменид: каждая мысль будет одно, но мысль — ни о чём? — Но это невозможно, отвечал он. — Значит, о чём-нибудь? — Да. — Существующем или не существующем? — Существующем. Не об одном ли чём, что̀ мыслится как присущее"}, "132c": {"g": "ὄντος ἢ οὐκ ὄντος; ὄντος. οὐχ ἑνός τινος, ὃ ἐπὶ πᾶσιν ἐκεῖνο τὸ νόημα ἐπὸν νοεῖ, μίαν τινὰ οὖσαν ἰδέαν; ναί. εἶτα οὐκ εἶδος ἔσται τοῦτο τὸ νοούμενον ἓν εἶναι, ἀεὶ ὂν τὸ αὐτὸ ἐπὶ πᾶσιν; ἀνάγκη αὖ φαίνεται. τί δὲ δή; εἰπεῖν τὸν Παρμενίδην, οὐκ ἀνάγκῃ ᾗ τἆλλα φῂς τῶν εἰδῶν μετέχειν ἢ δοκεῖ σοι ἐκ νοημάτων ἕκαστον εἶναι καὶ πάντα νοεῖν, ἢ νοήματα ὄντα ἀνόητα εἶναι; ἀλλʼ οὐδὲ τοῦτο, φάναι, ἔχει λόγον, ἀλλʼ, ὦ Παρμενίδη,", "r": "всему и представляет одну некоторую идею? — Да. — Так не вид ли будет это мыслимое одно, всегда тожественное во всём? — Необходимо. — Что же теперь? спросил Парменид: если все прочие вещи причастны, говоришь, видов; то не необходимо ли тебе думать, что либо каждая вещь относится к мыслям и всё мыслит, либо относящееся к мыслям несмысленно? — Но и это не имело бы"}, "132d": {"g": "μάλιστα ἔμοιγε καταφαίνεται ὧδε ἔχειν· τὰ μὲν εἴδη ταῦτα ὥσπερ παραδείγματα ἑστάναι ἐν τῇ φύσει, τὰ δὲ ἄλλα τούτοις ἐοικέναι καὶ εἶναι ὁμοιώματα, καὶ ἡ μέθεξις αὕτη τοῖς ἄλλοις γίγνεσθαι τῶν εἰδῶν οὐκ ἄλλη τις ἢ εἰκασθῆναι αὐτοῖς. εἰ οὖν τι, ἔφη, ἔοικεν τῷ εἴδει, οἷόν τε ἐκεῖνο τὸ εἶδος μὴ ὅμοιον εἶναι τῷ εἰκασθέντι, καθʼ ὅσον αὐτῷ ἀφωμοιώθη; ἢ ἔστι τις μηχανὴ τὸ ὅμοιον μὴ ὁμοίῳ ὅμοιον εἶναι; οὐκ ἔστι. τὸ δὲ ὅμοιον τῷ ὁμοίῳ ἆρʼ οὐ μεγάλη ἀνάγκη ἑνὸς τοῦ", "r": "смысла, отвечал он. Впрочем, мне-то, Парменид, скорее всего представляется так: эти виды стоят в природе как бы образцы, а прочие вещи подходят к ним и становятся подобиями; так что самая причастность их видам есть не иное что, как уподобление им. — Но когда что подошло к виду, сказал Парменид, — может ли тот вид не быть подобным уподобившемуся, насколько что ему уподобилось? Или есть какая-нибудь возможность — подобному не быть подобным подобному? — Нет. — Но подобному с подобным не крайне ли необходимо быть причастным одного и того же вида?"}, "132e": {"g": "αὐτοῦ εἴδους μετέχειν; ἀνάγκη. οὗ δʼ ἂν τὰ ὅμοια μετέχοντα ὅμοια ᾖ, οὐκ ἐκεῖνο ἔσται αὐτὸ τὸ εἶδος; παντάπασι μὲν οὖν. οὐκ ἄρα οἷόν τέ τι τῷ εἴδει ὅμοιον εἶναι, οὐδὲ τὸ εἶδος ἄλλῳ· εἰ δὲ μή, παρὰ τὸ εἶδος ἀεὶ ἄλλο ἀναφανήσεται εἶδος,", "r": "— Необходимо. — А то, чего причащаясь, подобное становится подобным, — не будет ли это именно тот вид? — Без сомнения. — Следовательно, невозможно, чтобы нечто уподоблялось виду, вид же уподоблялся иной вещи; а не то, — помимо вида всегда явится иной вид, и если этот"}, "133a": {"g": "καὶ ἂν ἐκεῖνό τῳ ὅμοιον ᾖ, ἕτερον αὖ, καὶ οὐδέποτε παύσεται ἀεὶ καινὸν εἶδος γιγνόμενον, ἐὰν τὸ εἶδος τῷ ἑαυτοῦ μετέχοντι ὅμοιον γίγνηται. ἀληθέστατα λέγεις. οὐκ ἄρα ὁμοιότητι τἆλλα τῶν εἰδῶν μεταλαμβάνει, ἀλλά τι ἄλλο δεῖ ζητεῖν ᾧ μεταλαμβάνει. ἔοικεν. ὁρᾷς οὖν, φάναι, ὦ Σώκρατες, ὅση ἡ ἀπορία ἐάν τις ὡς εἴδη ὄντα αὐτὰ καθʼ αὑτὰ διορίζηται; καὶ μάλα. εὖ τοίνυν ἴσθι, φάναι, ὅτι ὡς ἔπος εἰπεῖν οὐδέπω ἅπτῃ", "r": "будет подобен чему-нибудь, — опять иной, и никогда не перестанет представляться новый вид, как скоро вид становится подобным тому, что причастно его. — Ты говоришь весьма справедливо. — Стало быть, вещи делаются причастными видов не подобием: надобно искать чего-нибудь инаго, чем условливается эта причастность их. — Вероятно. — Так видишь ли, Сократ, сказал Парменид, сколько возникает затруднений, когда кто допускает бытие видов как бы самих по себе? — И очень. — Знай же хорошо, продолжал он, что до сих пор ты, просто сказать, и не подозреваешь, как велика в этом случае трудность, если что-либо из вещей существующих, постоянно их разграничивая, будешь полагать как один вид. —"}, "133b": {"g": "αὐτῆς ὅση ἐστὶν ἡ ἀπορία, εἰ ἓν εἶδος ἕκαστον τῶν ὄντων ἀεί τι ἀφοριζόμενος θήσεις. πῶς δή; εἰπεῖν. πολλὰ μὲν καὶ ἄλλα, φάναι, μέγιστον δὲ τόδε. εἴ τις φαίη μηδὲ προσήκειν αὐτὰ γιγνώσκεσθαι ὄντα τοιαῦτα οἷά φαμεν δεῖν εἶναι τὰ εἴδη, τῷ ταῦτα λέγοντι οὐκ ἂν ἔχοι τις ἐνδείξασθαι ὅτι ψεύδεται, εἰ μὴ πολλῶν μὲν τύχοι ἔμπειρος ὢν ὁ ἀμφισβητῶν καὶ μὴ ἀφυής, ἐθέλοι δὲ πάνυ πολλὰ καὶ πόρρωθεν πραγματευομένου τοῦ ἐνδεικνυμένου ἕπεσθαι, ἀλλʼ", "r": "Как это? спросил Сократ. — Тут много и другого, сказал Парменид, но самое важное вот что. Если бы кто сказал, что такие виды, какими они, говорим, должны быть, даже не доступны и для познания; то говорящему это никто не мог бы доказать, что он лжет, — кроме того случая, если возражающий против такого положения окажется человеком обширной опытности и хороших дарований, и будет расположен следовать за многими и издалека взятыми в пользу положения доказательствами; иначе, настаивающий, что виды не подлежат познанию, был бы непобедим. — Почему же, Парменид? спросил Сократ. —"}, "133c": {"g": "ἀπίθανος εἴη ὁ ἄγνωστα ἀναγκάζων αὐτὰ εἶναι. πῇ δή, ὦ Παρμενίδη; φάναι τὸν Σωκράτη. ὅτι, ὦ Σώκρατες, οἶμαι ἂν καὶ σὲ καὶ ἄλλον, ὅστις αὐτήν τινα καθʼ αὑτὴν ἑκάστου οὐσίαν τίθεται εἶναι, ὁμολογῆσαι ἂν πρῶτον μὲν μηδεμίαν αὐτῶν εἶναι ἐν ἡμῖν. πῶς γὰρ ἂν αὐτὴ καθʼ αὑτὴν ἔτι εἴη; φάναι τὸν Σωκράτη. καλῶς λέγεις, εἰπεῖν. οὐκοῦν καὶ ὅσαι τῶν ἰδεῶν πρὸς ἀλλήλας εἰσὶν αἵ εἰσιν, αὐταὶ πρὸς αὑτὰς τὴν οὐσίαν ἔχουσιν, ἀλλʼ οὐ πρὸς τὰ παρʼ", "r": "Потому, Сократ, что и ты, и другой, полагающий бытие некоторой самой по себе сущности каждого явления, прежде всего допустит, думаю, что у нас нет ни одной из них. — Иначе как же была бы она сама по себе? спросил Сократ. — Хорошо сказано, продолжал он. Значит, все, какие есть, идеи, находясь во взаимном отношении,"}, "133d": {"g": "ἡμῖν εἴτε ὁμοιώματα εἴτε ὅπῃ δή τις αὐτὰ τίθεται, ὧν ἡμεῖς μετέχοντες εἶναι ἕκαστα ἐπονομαζόμεθα· τὰ δὲ παρʼ ἡμῖν ταῦτα ὁμώνυμα ὄντα ἐκείνοις αὐτὰ αὖ πρὸς αὑτά ἐστιν ἀλλʼ οὐ πρὸς τὰ εἴδη, καὶ ἑαυτῶν ἀλλʼ οὐκ ἐκείνων ὅσα αὖ ὀνομάζεται οὕτως. πῶς λέγεις; φάναι τὸν Σωκράτη. οἷον, φάναι τὸν Παρμενίδην, εἴ τις ἡμῶν του δεσπότης ἢ δοῦλός ἐστιν, οὐκ αὐτοῦ δεσπότου δήπου, ὃ ἔστι δεσπότης,", "r": "имеют сущность сами для себя, а не для тех, что у нас, подобий, — или как иначе назовут их, — которым, будучи их причастны, мы придаем отдельные имена. Находящиеся же у нас, будучи одноименны с теми, существуют опять сами для себя, а не для видов, и относятся к себе, а не к тем видам, которые одинаково с ними наименованы. — Ка̀к ты говоришь? спросил Сократ. — Положим, например, сказал Парменид, кто-нибудь из нас"}, "133e": {"g": "ἐκείνου δοῦλός ἐστιν, οὐδὲ αὐτοῦ δούλου, ὃ ἔστι δοῦλος, δεσπότης ὁ δεσπότης, ἀλλʼ ἄνθρωπος ὢν ἀνθρώπου ἀμφότερα ταῦτʼ ἐστίν· αὐτὴ δὲ δεσποτεία αὐτῆς δουλείας ἐστὶν ὅ ἐστι, καὶ δουλεία ὡσαύτως αὐτὴ δουλεία αὐτῆς δεσποτείας, ἀλλʼ οὐ τὰ ἐν ἡμῖν πρὸς ἐκεῖνα τὴν δύναμιν ἔχει οὐδὲ ἐκεῖνα πρὸς ἡμᾶς, ἀλλʼ, ὃ λέγω, αὐτὰ αὑτῶν καὶ πρὸς αὑτὰ ἐκεῖνά τέ ἐστι, καὶ", "r": "— господин или слуга: слуга есть слуга не самого по себе господина, — как мы разумеем господина, — и господин есть господин не самого слуги, — как разумеем слугу, — но оба они — в отношениях человека к человеку; самое же господство есть то, что есть, в отношении к самому же рабству, как и самое рабство — к самому господству. Так ни то, что̀ у нас, не имеет значения по отношению к тем, ни те — к нам; но те, говорю, относятся сами к себе и существуют для себя, а находящееся у нас, подобным"}, "134a": {"g": "τὰ παρʼ ἡμῖν ὡσαύτως πρὸς αὑτά. ἢ οὐ μανθάνεις ὃ λέγω; πάνυ γʼ, εἰπεῖν τὸν Σωκράτη, μανθάνω. οὐκοῦν καὶ ἐπιστήμη, φάναι, αὐτὴ μὲν ὃ ἔστι ἐπιστήμη τῆς ὃ ἔστιν ἀλήθεια αὐτῆς ἂν ἐκείνης εἴη ἐπιστήμη; πάνυ γε. ἑκάστη δὲ αὖ τῶν ἐπιστημῶν, ἣ ἔστιν, ἑκάστου τῶν ὄντων, ὃ ἔστιν, εἴη ἂν ἐπιστήμη· ἢ οὔ; ναί. ἡ δὲ παρʼ ἡμῖν ἐπιστήμη οὐ τῆς παρʼ ἡμῖν ἂν ἀληθείας εἴη, καὶ αὖ ἑκάστη ἡ παρʼ ἡμῖν ἐπιστήμη τῶν παρʼ ἡμῖν", "r": "же образом, — для себя. Или ты не понимаешь моих слов? — Очень понимаю, отвечал Сократ. — Поэтому и знание, продолжал Парменид, — само знание, как оно есть, должно быть знанием самой той истины, как она есть. — Конечно. — И каждое частное опять знание, как оно есть, должно быть знанием каждой существенности, как она есть. Или нет? — Да. — А знание, что̀ у нас, не относится ли и к истине той, что у нас? И каждому опять знанию у нас не приходится ли быть знанием каждой существенности у нас?"}, "134b": {"g": "ὄντων ἑκάστου ἂν ἐπιστήμη συμβαίνοι εἶναι; ἀνάγκη. ἀλλὰ μὴν αὐτά γε τὰ εἴδη, ὡς ὁμολογεῖς, οὔτε ἔχομεν οὔτε παρʼ ἡμῖν οἷόν τε εἶναι. οὐ γὰρ οὖν. γιγνώσκεται δέ γέ που ὑπʼ αὐτοῦ τοῦ εἴδους τοῦ τῆς ἐπιστήμης αὐτὰ τὰ γένη ἃ ἔστιν ἕκαστα; ναί. ὅ γε ἡμεῖς οὐκ ἔχομεν. οὐ γάρ. οὐκ ἄρα ὑπό γε ἡμῶν γιγνώσκεται τῶν εἰδῶν οὐδέν, ἐπειδὴ αὐτῆς ἐπιστήμης οὐ μετέχομεν. οὐκ ἔοικεν. ἄγνωστον ἄρα ἡμῖν καὶ αὐτὸ τὸ καλὸν ὃ ἔστι καὶ", "r": "— Необходимо. — Между тем самых-то видов, как ты соглашаешься, и не имеем мы, и невозможны они у нас. — Конечно, нет. — Но самим в себе видом знания познаются, вероятно, и сами в себе роды, каждый как он есть. — Да. — А вида-то мы не имеем. — Нет. — Стало быть, нами-то не познается ни один из видов, так как мы не причастны самого знания. — Походит, что нет. — Следовательно, не познаваемо для нас и само прекрасное, как оно есть, и доброе, и всё, что разумеем мы как идеи"}, "134c": {"g": "τὸ ἀγαθὸν καὶ πάντα ἃ δὴ ὡς ἰδέας αὐτὰς οὔσας ὑπολαμβάνομεν. κινδυνεύει. ὅρα δὴ ἔτι τούτου δεινότερον τόδε. τὸ ποῖον; φαίης ἄν που, εἴπερ ἔστιν αὐτό τι γένος ἐπιστήμης, πολὺ αὐτὸ ἀκριβέστερον εἶναι ἢ τὴν παρʼ ἡμῖν ἐπιστήμην, καὶ κάλλος καὶ τἆλλα πάντα οὕτω. ναί. οὐκοῦν εἴπερ τι ἄλλο αὐτῆς ἐπιστήμης μετέχει, οὐκ ἄν τινα μᾶλλον ἢ θεὸν φαίης ἔχειν τὴν ἀκριβεστάτην ἐπιστήμην; ἀνάγκη.", "r": "сами в себе. — Должно быть. — Но, смотри, еще ужаснее этого вот что. — Что такое? — Подтвердишь ли ты, или нет? Если есть какой-нибудь самый род знания, то не гораздо ли совершеннее он, чем знание у нас? Так и красота, и всё прочее. — Да. — Поэтому, как скоро что иное причастно сего знания, то кому больше, как не Богу, приписал бы ты знание совершеннейшее? — Необходимо. — Но Бог,"}, "134d": {"g": "ἆρʼ οὖν οἷός τε αὖ ἔσται ὁ θεὸς τὰ παρʼ ἡμῖν γιγνώσκειν αὐτὴν ἐπιστήμην ἔχων; τί γὰρ οὔ; ὅτι, ἔφη ὁ Παρμενίδης, ὡμολόγηται ἡμῖν, ὦ Σώκρατες, μήτε ἐκεῖνα τὰ εἴδη πρὸς τὰ παρʼ ἡμῖν τὴν δύναμιν ἔχειν ἣν ἔχει, μήτε τὰ παρʼ ἡμῖν πρὸς ἐκεῖνα, ἀλλʼ αὐτὰ πρὸς αὑτὰ ἑκάτερα. ὡμολόγηται γάρ. οὐκοῦν εἰ παρὰ τῷ θεῷ αὕτη ἐστὶν ἡ ἀκριβεστάτη δεσποτεία καὶ αὕτη ἡ ἀκριβεστάτη ἐπιστήμη, οὔτʼ ἂν ἡ δεσποτεία ἡ ἐκείνων ἡμῶν ποτὲ ἂν δεσπόσειεν, οὔτʼ ἂν", "r": "имея само знание, будет ли в состоянии знать то, что у нас? — Почему же не быть? — Потому, сказал Парменид, что ни те виды, как мы согласились, Сократ, не имеют значения, какое имеют, по отношению к тому, что̀ у нас, ни то, что̀ у нас — по отношению к ним, — но что то̀ и другое относится само к себе. — Да, согласились. — Посему если у Бога — само совершеннейшее господство и само совершеннейшее"}, "134e": {"g": "ἐπιστήμη ἡμᾶς γνοίη οὐδέ τι ἄλλο τῶν παρʼ ἡμῖν, ἀλλὰ ὁμοίως ἡμεῖς τε ἐκείνων οὐκ ἄρχομεν τῇ παρʼ ἡμῖν ἀρχῇ οὐδὲ γιγνώσκομεν τοῦ θείου οὐδὲν τῇ ἡμετέρᾳ ἐπιστήμῃ, ἐκεῖνοί τε αὖ κατὰ τὸν αὐτὸν λόγον οὔτε δεσπόται ἡμῶν εἰσὶν οὔτε γιγνώσκουσι τὰ ἀνθρώπεια πράγματα θεοὶ ὄντες. ἀλλὰ μὴ λίαν, ἔφη, ᾖ θαυμαστὸς ὁ λόγος, εἴ τις τὸν θεὸν ἀποστερήσει τοῦ εἰδέναι. ταῦτα μέντοι, ὦ Σώκρατες, ἔφη ὁ Παρμενίδης, καὶ ἔτι", "r": "знание, то ни господство их никогда не могло бы над нами господствовать, ни знание их не могло бы нас, или что иное у нас, знать. Как мы не начальствуем над ними действующим у нас начальствованием, и не знаем ничего божественного нашим знанием; таким же образом и они, — если боги, то не господа наши, и не знают человеческих дел. — Но не слишком ли странно будет это положение, сказал Сократ, если кто Богу откажет в"}, "135a": {"g": "ἄλλα πρὸς τούτοις πάνυ πολλὰ ἀναγκαῖον ἔχειν τὰ εἴδη, εἰ εἰσὶν αὗται αἱ ἰδέαι τῶν ὄντων καὶ ὁριεῖταί τις αὐτό τι ἕκαστον εἶδος· ὥστε ἀπορεῖν τε τὸν ἀκούοντα καὶ ἀμφισβητεῖν ὡς οὔτε ἔστι ταῦτα, εἴ τε ὅτι μάλιστα εἴη, πολλὴ ἀνάγκη αὐτὰ εἶναι τῇ ἀνθρωπίνῃ φύσει ἄγνωστα, καὶ ταῦτα λέγοντα δοκεῖν τε τὶ λέγειν καί, ὃ ἄρτι ἐλέγομεν, θαυμαστῶς ὡς δυσανάπειστον εἶναι. καὶ ἀνδρὸς πάνυ μὲν εὐφυοῦς τοῦ δυνησομένου μαθεῖν ὡς ἔστι γένος τι ἑκάστου καὶ οὐσία αὐτὴ", "r": "знании? — Однакож это, Сократ, продолжал Парменид, и весьма многое иное кроме этого, необходимо связано с видами, если они суть идеи существенностей, и если будем каждый из них определять как что-то само по себе; так что слушатель станет недоумевать и сомневаться: есть ли в самом деле такие виды, а когда они непременно есть, то ведь крайне необходимо быть им для природы человеческой не познаваемыми. И кто так говорит, тому не только кажется, что он судит здраво, но даже, как мы сейчас сказали, удивительно было бы, если бы говорящего это можно было переуверить. Надо быть человеком очень даровитым, чтобы уразуметь, что есть некоторый род каждой вещи и сущность сама по себе; но"}, "135b": {"g": "καθʼ αὑτήν, ἔτι δὲ θαυμαστοτέρου τοῦ εὑρήσοντος καὶ ἄλλον δυνησομένου διδάξαι ταῦτα πάντα ἱκανῶς διευκρινησάμενον. συγχωρῶ σοι, ἔφη, ὦ Παρμενίδη, ὁ Σωκράτης· πάνυ γάρ μοι κατὰ νοῦν λέγεις. ἀλλὰ μέντοι, εἶπεν ὁ Παρμενίδης, εἴ γέ τις δή, ὦ Σώκρατες, αὖ μὴ ἐάσει εἴδη τῶν ὄντων εἶναι, εἰς πάντα τὰ νυνδὴ καὶ ἄλλα τοιαῦτα ἀποβλέψας, μηδέ τι ὁριεῖται εἶδος ἑνὸς ἑκάστου, οὐδὲ ὅποι τρέψει τὴν διάνοιαν ἕξει, μὴ ἐῶν", "r": "еще более удивительным, чтоб и открыть самому, и суметь наставить другого, разобрав всё это достаточно. — Я уступаю тебе, Парменид, сказал Сократ; потому что слова твои мне очень по мысли. — Между тем, Сократ, продолжал Парменид, если уже кто, смотря на всё, что было теперь говорено, и на другое подобное, не допустит, чтоб были виды существенностей, и не будет определять вида для каждой вещи, то, не допуская идеи каждой из"}, "135c": {"g": "ἰδέαν τῶν ὄντων ἑκάστου τὴν αὐτὴν ἀεὶ εἶναι, καὶ οὕτως τὴν τοῦ διαλέγεσθαι δύναμιν παντάπασι διαφθερεῖ. τοῦ τοιούτου μὲν οὖν μοι δοκεῖς καὶ μᾶλλον ᾐσθῆσθαι. ἀληθῆ λέγεις, φάναι. τί οὖν ποιήσεις φιλοσοφίας πέρι; πῇ τρέψῃ ἀγνοουμένων τούτων; οὐ πάνυ μοι δοκῶ καθορᾶν ἔν γε τῷ παρόντι. πρῲ γάρ, εἰπεῖν, πρὶν γυμνασθῆναι, ὦ Σώκρατες, ὁρίζεσθαι ἐπιχειρεῖς καλόν τέ τι καὶ δίκαιον καὶ ἀγαθὸν καὶ ἓν", "r": "существенностей, как идеи всегда тожественной, он и не найдется, к чему направить свою мысль, — и таким образом совершенно упразднит возможность собеседования. Это, мне кажется, ты больше всего чувствовал. — Правда, сказал Сократ. —\n\nЧто же ты будешь делать по философии? Куда направишься, когда не знаешь этого? — В настоящую-то минуту представляю не так ясно. — Рано же, значит, Сократ, сказал Парменид, браться определять, что̀ такое прекрасное, справедливое, доброе, и каждый отдельный вид, — не упражнявшись наперед в этом. То же ведь заметил я и прежде,"}, "135d": {"g": "ἕκαστον τῶν εἰδῶν. ἐνενόησα γὰρ καὶ πρῴην σου ἀκούων διαλεγομένου ἐνθάδε Ἀριστοτέλει τῷδε. καλὴ μὲν οὖν καὶ θεία, εὖ ἴσθι, ἡ ὁρμὴ ἣν ὁρμᾷς ἐπὶ τοὺς λόγους· ἕλκυσον δὲ σαυτὸν καὶ γύμνασαι μᾶλλον διὰ τῆς δοκούσης ἀχρήστου εἶναι καὶ καλουμένης ὑπὸ τῶν πολλῶν ἀδολεσχίας, ἕως ἔτι νέος εἶ· εἰ δὲ μή, σὲ διαφεύξεται ἡ ἀλήθεια. τίς οὖν ὁ τρόπος, φάναι, ὦ Παρμενίδη, τῆς γυμνασίας; οὗτος, εἶπεν, ὅνπερ ἤκουσας Ζήνωνος. πλὴν τοῦτό γέ", "r": "когда слушал здесь твой разговор с этим Аристотелем. Так знай хорошо, прекрасное и божественное дело — иметь такое стремление к рассуждениям, какое ты имеешь: но, пока молод, сдержись, и упражняй себя больше посредством той бесполезной на вид болтовни, — как ее называет большинство; — а не то, истина будет убегать от тебя. — Но каким способом упражняться, Парменид? спросил Сократ. — Таким, отвечал он, о каком ты слышал от Зенона."}, "135e": {"g": "σου καὶ πρὸς τοῦτον ἠγάσθην εἰπόντος, ὅτι οὐκ εἴας ἐν τοῖς ὁρωμένοις οὐδὲ περὶ ταῦτα τὴν πλάνην ἐπισκοπεῖν, ἀλλὰ περὶ ἐκεῖνα ἃ μάλιστά τις ἂν λόγῳ λάβοι καὶ εἴδη ἂν ἡγήσαιτο εἶναι. δοκεῖ γάρ μοι, ἔφη, ταύτῃ γε οὐδὲν χαλεπὸν εἶναι καὶ ὅμοια καὶ ἀνόμοια καὶ ἄλλο ὁτιοῦν τὰ ὄντα πάσχοντα ἀποφαίνειν. καὶ καλῶς γʼ, ἔφη. χρὴ δὲ καὶ τόδε ἔτι πρὸς τούτῳ ποιεῖν, μὴ μόνον εἰ ἔστιν ἕκαστον ὑποτιθέμενον σκοπεῖν τὰ", "r": "Впрочем, тому-то я очень обрадовался, что̀ ты сказал ему, — что, то есть, не позволяешь себе держаться в видимом и здесь искать обмана, но восходишь к тому, что̀ схватывает кто-нибудь особенно умом и почитает видами. — — Потому что таким-то образом, сказал он, не трудно, мне кажется, доказать, что существующее бывает подобно и не подобно, и принимает какое бы то ни было иное качество. — И хорошо, примолвил Парменид. Но сверх того надобно делать и следующее: предположив бытие чего-нибудь, не только наблюдать, что̀ вытекает из предположения, но с тою же целью предполагать и небытие, —"}, "136a": {"g": "συμβαίνοντα ἐκ τῆς ὑποθέσεως, ἀλλὰ καὶ εἰ μὴ ἔστι τὸ αὐτὸ τοῦτο ὑποτίθεσθαι, εἰ βούλει μᾶλλον γυμνασθῆναι. πῶς λέγεις; φάναι. οἷον, ἔφη, εἰ βούλει, περὶ ταύτης τῆς ὑποθέσεως ἣν Ζήνων ὑπέθετο, εἰ πολλά ἐστι, τί χρὴ συμβαίνειν καὶ αὐτοῖς τοῖς πολλοῖς πρὸς αὑτὰ καὶ πρὸς τὸ ἓν καὶ τῷ ἑνὶ πρός τε αὑτὸ καὶ πρὸς τὰ πολλά· καὶ αὖ εἰ μή ἐστι πολλά, πάλιν σκοπεῖν τί συμβήσεται καὶ τῷ ἑνὶ καὶ τοῖς πολλοῖς καὶ πρὸς", "r": "если хочешь доставить себе больше упражнения. — Ка̀к ты говоришь? спросил он. — Возьми, например, если хочешь, то самое предположение, сказал Парменид, какое сделал Зенон. Пусть будет многое: что̀ должно произойти с самим многим, и в отношении к нему, и в отношении к одному, и что̀ — с одним, в отношении к нему самому и ко многому? Пусть опять не будет многого: то же наблюдай, — что̀ произойдет с одним, и со многим, как в отношении их к самим себе, так и в отношении одного к другому. Таким же образом опять, если будет"}, "136b": {"g": "αὑτὰ καὶ πρὸς ἄλληλα· καὶ αὖθις αὖ ἐὰν ὑποθῇ εἰ ἔστιν ὁμοιότης ἢ εἰ μὴ ἔστιν, τί ἐφʼ ἑκατέρας τῆς ὑποθέσεως συμβήσεται καὶ αὐτοῖς τοῖς ὑποτεθεῖσιν καὶ τοῖς ἄλλοις καὶ πρὸς αὑτὰ καὶ πρὸς ἄλληλα. καὶ περὶ ἀνομοίου ὁ αὐτὸς λόγος καὶ περὶ κινήσεως καὶ περὶ στάσεως καὶ περὶ γενέσεως καὶ φθορᾶς καὶ περὶ αὐτοῦ τοῦ εἶναι καὶ τοῦ μὴ εἶναι· καὶ ἑνὶ λόγῳ, περὶ ὅτου ἂν ἀεὶ ὑποθῇ ὡς ὄντος καὶ ὡς οὐκ ὄντος καὶ ὁτιοῦν ἄλλο πάθος πάσχοντος, δεῖ σκοπεῖν τὰ συμβαίνοντα", "r": "предположено бытие или небытие подобного, — смотри, что̀ выйдет из того и другого предположения как для самых предметов предположенных, так и для другого, в отношении их к себе и в отношении взаимном. Это же самое и о не подобном, о движении и стоянии, о рождении и разрушении, и о самом бытии или небытии. Одним словом: что бы ни было тобою предположено как существующее или не существующее, либо имеющее какое-нибудь иное свойство, — надобно наблюдать, что произойдет для самого этого, и для отдельной единичности, которую ты"}, "136c": {"g": "πρὸς αὑτὸ καὶ πρὸς ἓν ἕκαστον τῶν ἄλλων, ὅτι ἂν προέλῃ, καὶ πρὸς πλείω καὶ πρὸς σύμπαντα ὡσαύτως· καὶ τἆλλα αὖ πρὸς αὑτά τε καὶ πρὸς ἄλλο ὅτι ἂν προαιρῇ ἀεί, ἐάντε ὡς ὂν ὑποθῇ ὃ ὑπετίθεσο, ἄντε ὡς μὴ ὄν, εἰ μέλλεις τελέως γυμνασάμενος κυρίως διόψεσθαι τὸ ἀληθές. ἀμήχανόν γʼ ἔφη, λέγεις, ὦ Παρμενίδη, πραγματείαν, καὶ οὐ σφόδρα μανθάνω. ἀλλά μοι τί οὐ διῆλθες αὐτὸς ὑποθέμενός τι, ἵνα μᾶλλον καταμάθω;", "r": "предызбрал, и для большего числа их, и для всех. Та̀к и прочее, подобно этому, должно поставлять в отношение и к тому самому и к иному, что ни было бы тобою предызбрано, — предположил ли ты нечто как существующее, что предположил, или как не существующее, — если хочешь подготовить себя совершенным образом, чтобы точно различать истину. — Об упражнении неодолимо трудном говоришь ты, Парменид, сказал Сократ, и я не совсем понимаю его: проведи пожалуйста этот способ сам, предположив что-нибудь, — чтобы я лучше понял. — Ты, Сократ, навязываешь"}, "136d": {"g": "πολὺ ἔργον, φάναι, ὦ Σώκρατες, προστάττεις ὡς τηλικῷδε. ἀλλὰ σύ, εἰπεῖν τὸν Σωκράτη, Ζήνων, τί οὐ διῆλθες ἡμῖν; καὶ τὸν Ζήνωνα ἔφη γελάσαντα φάναι· αὐτοῦ, ὦ Σώκρατες, δεώμεθα Παρμενίδου· μὴ γὰρ οὐ φαῦλον ᾖ ὃ λέγει. ἢ οὐχ ὁρᾷς ὅσον ἔργον προστάττεις; εἰ μὲν οὖν πλείους ἦμεν, οὐκ ἂν ἄξιον ἦν δεῖσθαι· ἀπρεπῆ γὰρ τὰ τοιαῦτα πολλῶν ἐναντίον λέγειν ἄλλως τε καὶ τηλικούτῳ·", "r": "на меня, такого старика, большое дело, примолвил Парменид. — Так ты, Зенон, не проведешь ли нам его? спросил Сократ. — А Зенон засмеялся, говорит, и сказал: попросим-ка, Сократ, самого Парменида; ведь то, что он говорит, не безделица. Разве не видишь, какое затеваешь ты дело? Если бы нас было больше, просить и не годилось бы; ведь говорить об этом в присутствии толпы, особенно еще такому старику, неприлично, так как толпа не знает,"}, "136e": {"g": "ἀγνοοῦσιν γὰρ οἱ πολλοὶ ὅτι ἄνευ ταύτης τῆς διὰ πάντων διεξόδου τε καὶ πλάνης ἀδύνατον ἐντυχόντα τῷ ἀληθεῖ νοῦν σχεῖν. ἐγὼ μὲν οὖν, ὦ Παρμενίδη, Σωκράτει συνδέομαι, ἵνα καὶ αὐτὸς διακούσω διὰ χρόνου. ταῦτα δὴ εἰπόντος τοῦ Ζήνωνος, ἔφη ὁ Ἀντιφῶν φάναι τὸν Πυθόδωρον, αὐτόν τε δεῖσθαι τοῦ Παρμενίδου καὶ τὸν Ἀριστοτέλη καὶ τοὺς ἄλλους, ἐνδείξασθαι ὃ λέγοι καὶ μὴ ἄλλως ποιεῖν. τὸν οὖν Παρμενίδην· ἀνάγκη, φάναι, πείθεσθαι. καίτοι δοκῶ μοι τὸ τοῦ Ἰβυκείου ἵππου πεπονθέναι,", "r": "что без такого рода околичностей и пересудов обо всём невозможно добраться до истинного взгляда. Так я, Парменид, вместе с Сократом прошу тебя о том, — чтобы и самому мне после долгого времени тебя послушать.\n\nКогда Зенон выразил это, говорил Антифон, стали, по словам Пифодора, просить Парменида и сам он, и Аристотель, и другие, чтобы он подтвердил опытом, что̀ говорит, и не уклонялся. — Так необходимо"}, "137a": {"g": "ᾧ ἐκεῖνος ἀθλητῇ ὄντι καὶ πρεσβυτέρῳ, ὑφʼ ἅρματι μέλλοντι ἀγωνιεῖσθαι καὶ διʼ ἐμπειρίαν τρέμοντι τὸ μέλλον, ἑαυτὸν ἀπεικάζων ἄκων ἔφη καὶ αὐτὸς οὕτω πρεσβύτης ὢν εἰς τὸν ἔρωτα ἀναγκάζεσθαι ἰέναι· κἀγώ μοι δοκῶ μεμνημένος μάλα φοβεῖσθαι πῶς χρὴ τηλικόνδε ὄντα διανεῦσαι τοιοῦτόν τε καὶ τοσοῦτον πέλαγος λόγων· ὅμως δὲ δεῖ γὰρ χαρίζεσθαι, ἐπειδὴ καί, ὃ Ζήνων λέγει, αὐτοί ἐσμεν. πόθεν οὖν δὴ", "r": "послушаться, сказал тогда Парменид, — хотя со мною происходит кажется, то же, что̀ с конем Ивика, — конем-рысаком, уже состарившимся на бегах, когда он готовится к новому бегу в колеснице, и трепещет, зная по опыту то, что̀ предстоит, — которому уподобляя себя, Ивик сказал: «вот и самому мне, такому старику, приходится поневоле идти на встречу любви». Так-то, кажется, и я очень страшусь, представляя, ка̀к в таких летах переплыть мне столь глубокое и широкое море речей. Однако надобно же угодить, когда и Зенон так говорит; мы же ведь"}, "137b": {"g": "ἀρξόμεθα καὶ τί πρῶτον ὑποθησόμεθα; ἢ βούλεσθε, ἐπειδήπερ δοκεῖ πραγματειώδη παιδιὰν παίζειν, ἀπʼ ἐμαυτοῦ ἄρξωμαι καὶ τῆς ἐμαυτοῦ ὑποθέσεως, περὶ τοῦ ἑνὸς αὐτοῦ ὑποθέμενος, εἴτε ἕν ἐστιν εἴτε μὴ ἕν, τί χρὴ συμβαίνειν; πάνυ μὲν οὖν, φάναι τὸν Ζήνωνα. τίς οὖν, εἰπεῖν, μοὶ ἀποκρινεῖται; ἢ ὁ νεώτατος; ἥκιστα γὰρ ἂν πολυπραγμονοῖ, καὶ ἃ οἴεται μάλιστα ἂν ἀποκρίνοιτο· καὶ ἅμα ἐμοὶ ἀνάπαυλα ἂν εἴη ἡ ἐκείνου ἀπόκρισις.", "r": "тут одни. Итак, с чего начнем, и что сперва предположим? Хотите ли, — хотя игра предстоит хлопотливая, — начну от себя и со своего предположения: поставлю вопрос об одном, — одно ли существует, или не одно, — какое получится следствие? — Конечно, сказал Зенон. — Кто же будет отвечать мне? спросил он: разве самый младший? потому что он был бы менее придирчив, и отвечал бы именно то, что думает; а между тем его ответ давал бы мне минуту для отдыха. —"}, "137c": {"g": "ἕτοιμός σοι, ὦ Παρμενίδη, φάναι, τοῦτο, τὸν Ἀριστοτέλη· ἐμὲ γὰρ λέγεις τὸν νεώτατον λέγων. ἀλλὰ ἐρώτα ὡς ἀποκρινουμένου. εἶεν δή , φάναι· εἰ ἕν ἐστιν, ἄλλο τι οὐκ ἂν εἴη πολλὰ τὸ ἕν; πῶς γὰρ ἄν; οὔτε ἄρα μέρος αὐτοῦ οὔτε ὅλον αὐτὸ δεῖ εἶναι. τί δή; τὸ μέρος που ὅλου μέρος ἐστίν. ναί. τί δὲ τὸ ὅλον; οὐχὶ οὗ ἂν μέρος μηδὲν ἀπῇ ὅλον ἂν εἴη; πάνυ γε. ἀμφοτέρως ἄρα τὸ ἓν ἐκ μερῶν ἂν εἴη, ὅλον τε ὂν καὶ μέρη ἔχον. ἀνάγκη. ἀμφοτέρως ἂν ἄρα", "r": "Я готов, Парменид, сказал тот (упомянутый выше) Аристотель; потому что я, как говоришь, самый младший. Спрашивай же, — буду отвечать. \n\nТак положим, начал Парменид, что есть одно. Не правда ли, что одно не будет многое? — Ка̀к ему быть! — Следовательно, у него не должно быть частей, и оно не будет целым. — Как? — Часть, вероятно, есть часть целого. — Да. — А что такое целое? Не то ли было бы целое, что̀ не имело бы недостатка ни в одной части? — Конечно. — Стало быть, одно, в обоих случаях, будучи целым и"}, "137d": {"g": "οὕτως τὸ ἓν πολλὰ εἴη ἀλλʼ οὐχ ἕν. ἀληθῆ. δεῖ δέ γε μὴ πολλὰ ἀλλʼ ἓν αὐτὸ εἶναι. δεῖ. οὔτʼ ἄρα ὅλον ἔσται οὔτε μέρη ἕξει, εἰ ἓν ἔσται τὸ ἕν. οὐ γάρ. οὐκοῦν εἰ μηδὲν ἔχει μέρος, οὔτʼ ἂν ἀρχὴν οὔτε τελευτὴν οὔτε μέσον ἔχοι· μέρη γὰρ ἂν ἤδη αὐτοῦ τὰ τοιαῦτα εἴη. ὀρθῶς. καὶ μὴν τελευτή γε καὶ ἀρχὴ πέρας ἑκάστου. πῶς δʼ οὔ; ἄπειρον ἄρα τὸ ἕν, εἰ μήτε ἀρχὴν μήτε τελευτὴν ἔχει. ἄπειρον. καὶ ἄνευ σχήματος ἄρα· οὔτε γὰρ", "r": "имея части, состояло бы из частей? — Необходимо. — Одно таким образом было бы, в обоих случаях, многое, а не одно. — Правда. — А между тем должно-то быть не многому, а одному. — Должно. — Следовательно, если одно будет одно, то оно не будет ни целым, ни состоящим из частей. — Не будет. — А когда оно не имеет частей, то не имеет ни начала, ни конца, ни средины: потому что это были бы уже его части. — Правильно. — А конец-то и начало суть предел каждой вещи. — Ка̀к не предел. — Стало"}, "137e": {"g": "στρογγύλου οὔτε εὐθέος μετέχει. πῶς; στρογγύλον γέ πού ἐστι τοῦτο οὗ ἂν τὰ ἔσχατα πανταχῇ ἀπὸ τοῦ μέσου ἴσον ἀπέχῃ. ναί. καὶ μὴν εὐθύ γε, οὗ ἂν τὸ μέσον ἀμφοῖν τοῖν ἐσχάτοιν ἐπίπροσθεν ᾖ. οὕτως. οὐκοῦν μέρη ἂν ἔχοι τὸ ἓν καὶ πολλὰ ἂν εἴη, εἴτε εὐθέος σχήματος εἴτε περιφεροῦς μετέχοι. πάνυ μὲν οὖν. οὔτε ἄρα εὐθὺ οὔτε", "r": "быть, одно беспредельно, если оно не имеет ни начала, ни конца. — Беспредельно. — Следовательно, и без образа оно, потому что не причастно ни круглоты, ни прямизны. — Как? — Круглота-то; вероятно, есть то, у чего оконечности"}, "138a": {"g": "περιφερές ἐστιν, ἐπείπερ οὐδὲ μέρη ἔχει. ὀρθῶς. καὶ μὴν τοιοῦτόν γε ὂν οὐδαμοῦ ἂν εἴη· οὔτε γὰρ ἐν ἄλλῳ οὔτε ἐν ἑαυτῷ εἴη. πῶς δή; ἐν ἄλλῳ μὲν ὂν κύκλῳ που ἂν περιέχοιτο ὑπʼ ἐκείνου ἐν ᾧ ἐνείη, καὶ πολλαχοῦ ἂν αὐτοῦ ἅπτοιτο πολλοῖς· τοῦ δὲ ἑνός τε καὶ ἀμεροῦς καὶ κύκλου μὴ μετέχοντος ἀδύνατον πολλαχῇ κύκλῳ ἅπτεσθαι. ἀδύνατον. ἀλλὰ μὴν αὐτό γε ἐν ἑαυτῷ ὂν κἂν ἑαυτῷ εἴη περιέχον οὐκ ἄλλο ἢ αὑτό, εἴπερ καὶ ἐν", "r": "везде равно отстоят от средины. — Да. — А прямота-то, — у чего средина закрывает собою оба конца. — Так. — Поэтому одно, будь оно причастно прямой или круглой фигуры, имело бы части и было бы многим. — Конечно. — Если же оно не имеет частей, то не есть ни прямое, ни круглое. — Правильно. — А будучи таким-то, не будет нигде, потому что не будет ни в ином, ни в себе. — Как это? — Будучи в ином, одно, вероятно, обнималось бы сферою того, в чём заключено, и во многих местах его прикасалось бы ко многому; тогда как одному, не причастному ни частей, ни круга, невозможно во многих местах прикасаться к кругу. — Невозможно. — А находясь само-то в себе, оно себя же самого и обнимало бы, будучи не иным чем, как самим, хотя бы было и в себе; потому что быть"}, "138b": {"g": "ἑαυτῷ εἴη· ἔν τῳ γάρ τι εἶναι μὴ περιέχοντι ἀδύνατον. ἀδύνατον γάρ. οὐκοῦν ἕτερον μὲν ἄν τι εἴη αὐτὸ τὸ περιέχον, ἕτερον δὲ τὸ περιεχόμενον· οὐ γὰρ ὅλον γε ἄμφω ταὐτὸν ἅμα πείσεται καὶ ποιήσει· καὶ οὕτω τὸ ἓν οὐκ ἂν εἴη ἔτι ἓν ἀλλὰ δύο. οὐ γὰρ οὖν. οὐκ ἄρα ἐστίν που τὸ ἕν, μήτε ἐν αὑτῷ μήτε ἐν ἄλλῳ ἐνόν. οὐκ ἔστιν. ὅρα δή, οὕτως ἔχον εἰ οἷόν τέ ἐστιν ἑστάναι ἢ κινεῖσθαι. τί δὴ γὰρ οὔ; ὅτι κινούμενόν γε ἢ φέροιτο ἢ", "r": "чему-нибудь в том, что не обнимает, невозможно. — Невозможно. — Посему иное нечто было бы самое обнимающее, и иное — обнимаемое: — ибо то и другое, как целое, будучи тем же, не будет вместе страдать и действовать; и таким образом одно не было бы уже одно, а два. — Не было бы. — Стало быть, одно не находится, вероятно, ни в себе, ни в ином. — Не находится. — Смотри же, — будучи таким, может ли оно стоять, или двигаться. — Почему же бы нет? — Потому что движимое-то или переносилось бы, или изменялось; ведь эти только и бывают движения. — Да. —"}, "138c": {"g": "ἀλλοιοῖτο ἄν· αὗται γὰρ μόναι κινήσεις. ναί. ἀλλοιούμενον δὲ τὸ ἓν ἑαυτοῦ ἀδύνατόν που ἓν ἔτι εἶναι. ἀδύνατον. οὐκ ἄρα κατʼ ἀλλοίωσίν γε κινεῖται. οὐ φαίνεται. ἀλλʼ ἆρα τῷ φέρεσθαι; ἴσως. καὶ μὴν εἰ φέροιτο τὸ ἕν, ἤτοι ἐν τῷ αὐτῷ ἂν περιφέροιτο κύκλῳ ἢ μεταλλάττοι χώραν ἑτέραν ἐξ ἑτέρας. ἀνάγκη. οὐκοῦν κύκλῳ μὲν περιφερόμενον ἐπὶ μέσου βεβηκέναι ἀνάγκη, καὶ τὰ περὶ τὸ μέσον φερόμενα ἄλλα μέρη ἔχειν ἑαυτοῦ· ᾧ δὲ", "r": "Изменяющееся же против себя одно, вероятно, не может уже быть одним. — Не может. — Следовательно, в смысле изменения-то, не движется. — Явно, что не движется. — Так не в смысле ли перенесения? — Может быть. — Но если одно переносится, то либо переносится в том же месте, вращаясь вокруг себя, либо переменяет место, — одно на другое. — Необходимо. — Переносящееся же чрез вращение вокруг себя по необходимости утверждается на средине, и в переносящемся около средины имеет отличные от себя части."}, "138d": {"g": "μήτε μέσου μήτε μερῶν προσήκει, τίς μηχανὴ τοῦτο κύκλῳ ποτʼ ἐπὶ τοῦ μέσου ἐνεχθῆναι; οὐδεμία. ἀλλὰ δὴ χώραν ἀμεῖβον ἄλλοτʼ ἄλλοθι γίγνεται καὶ οὕτω κινεῖται; εἴπερ γε δή. οὐκοῦν εἶναι μέν που ἔν τινι αὐτῷ ἀδύνατον ἐφάνη; ναί. ἆρʼ οὖν γίγνεσθαι ἔτι ἀδυνατώτερον; οὐκ ἐννοῶ ὅπῃ. εἰ ἔν τῴ τι γίγνεται, οὐκ ἀνάγκη μήτε πω ἐν ἐκείνῳ εἶναι ἔτι ἐγγιγνόμενον, μήτʼ ἔτι ἔξω ἐκείνου παντάπασιν, εἴπερ ἤδη ἐγγίγνεται; ἀνάγκη. εἰ ἄρα τι", "r": "Между тем тому, чему не свойственны ни средина, ни части, какая возможность вращаться вокруг себя на средине? — Никакой. — А переменяя место, оно бывает то там, то здесь, и таким образом движется? — Да, если только движется. — Не показалось ли нам невозможным быть ему в чём-нибудь? — Да. — А бывать не менее ли еще возможно? — Не понимаю, каким образом. — Что̀ в чём-нибудь бывает, тому не необходимо ли, при вступлении, еще не быть совсем в том самом, и не быть более вне того, как скоро оно уже вступило? — Необходимо. — Следовательно, если будет подвергаться этому что-нибудь иное, то, конечно,"}, "138e": {"g": "ἄλλο πείσεται τοῦτο, ἐκεῖνο ἂν μόνον πάσχοι οὗ μέρη εἴη· τὸ μὲν γὰρ ἄν τι αὐτοῦ ἤδη ἐν ἐκείνῳ, τὸ δὲ ἔξω εἴη ἅμα· τὸ δὲ μὴ ἔχον μέρη οὐχ οἷόν τέ που ἔσται τρόπῳ οὐδενὶ ὅλον ἅμα μήτε ἐντὸς εἶναί τινος μήτε ἔξω. ἀληθῆ. οὗ δὲ μήτε μέρη εἰσὶ μήτε ὅλον τυγχάνει ὄν, οὐ πολὺ ἔτι ἀδυνατώτερον ἐγγίγνεσθαί που, μήτε κατὰ μέρη μήτε κατὰ ὅλον ἐγγιγνόμενον; φαίνεται. οὔτʼ ἄρα ποι ἰὸν καὶ ἔν", "r": "может подвергаться только то, что имеет части; ибо в одно и то же время нечто, принадлежащее предмету, могло бы находиться уже в том, и нечто — вне того; тогда как не имеющее частей никаким образом не будет в состоянии быть всё внутри и вместе вне чего-нибудь. — Правда. — А тому, что и не имеет частей, и не есть целое, не гораздо ли еще невозможнее вступать в бывание, когда оно не вступает ни частями, ни целым? — Явно. — Стало быть, одно не переменяет места ни как идущее куда"}, "139a": {"g": "τῳ γιγνόμενον χώραν ἀλλάττει, οὔτʼ ἐν τῷ αὐτῷ περιφερόμενον οὔτε ἀλλοιούμενον. οὐκ ἔοικε. κατὰ πᾶσαν ἄρα κίνησιν τὸ ἓν ἀκίνητον. ἀκίνητον. ἀλλὰ μὴν καὶ εἶναί γέ φαμεν ἔν τινι αὐτὸ ἀδύνατον. φαμὲν γάρ. οὐδʼ ἄρα ποτὲ ἐν τῷ αὐτῷ ἐστιν. τί δή; ὅτι ἤδη ἂν ἐν ἐκείνῳ εἴη ἐν ᾧ τῷ αὐτῷ ἐστιν. πάνυ μὲν οὖν. ἀλλʼ οὔτε ἐν αὑτῷ οὔτε ἐν ἄλλῳ οἷόν τε ἦν αὐτῷ ἐνεῖναι. οὐ γὰρ οὖν. οὐδέποτε ἄρα ἐστὶ τὸ ἓν ἐν τῷ αὐτῷ. οὐκ ἔοικεν.", "r": "нибудь, ни как появляющееся в чём-нибудь, (и не движется) — ни как вращающееся на месте, ни как изменяющееся само в себе. — Как видно, нет. — Следовательно, одно не движется ни каким родом движения. — Не движется. — Но и быть-то ему в чём-нибудь, говорим, тоже невозможно. — Да, говорим. — Стало быть, оно никогда не находится в том же. — Почему так? — Потому что было бы уже в том, в чём находится, как в том же. — Конечно. — Да ему невозможно было также находиться ни в себе, ни в ином. — Конечно, невозможно. — Следовательно, одно никогда не"}, "139b": {"g": "ἀλλὰ μὴν τό γε μηδέποτε ἐν τῷ αὐτῷ ὂν οὔτε ἡσυχίαν ἄγει οὔθʼ ἕστηκεν. οὐ γὰρ οἷόν τε. τὸ ἓν ἄρα, ὡς ἔοικεν, οὔτε ἕστηκεν οὔτε κινεῖται. οὔκουν δὴ φαίνεταί γε. οὐδὲ μὴν ταὐτόν γε οὔτε ἑτέρῳ οὔτε ἑαυτῷ ἔσται, οὐδʼ αὖ ἕτερον οὔτε αὑτοῦ οὔτε ἑτέρου ἂν εἴη. πῇ δή; ἕτερον μέν που ἑαυτοῦ ὂν ἑνὸς ἕτερον ἂν εἴη καὶ οὐκ ἂν εἴη ἕν. ἀληθῆ. καὶ μὴν ταὐτόν γε ἑτέρῳ ὂν ἐκεῖνο ἂν εἴη, αὐτὸ", "r": "остается на месте. — Видно, что нет. — А что никогда не остается на месте, то̀ не находится в покое, и не стоит. — Да и нельзя. — Поэтому одно и не стоит, как видно, и не движется. — Так выходит. — Притом, оно не будет тожественно ни с другим, ни с собою, и опять, не будет отлично ни от себя, ни от другого. — Каким же образом? — Будучи отлично от себя, оно, конечно, было бы отлично от одного, и уже не было бы одно. — Правда. — Будучи, притом, тожественно с другим, оно было бы то̀"}, "139c": {"g": "δʼ οὐκ ἂν εἴη· ὥστε οὐδʼ ἂν οὕτως εἴη ὅπερ ἔστιν, ἕν, ἀλλʼ ἕτερον ἑνός. οὐ γὰρ οὖν. ταὐτὸν μὲν ἄρα ἑτέρῳ ἢ ἕτερον ἑαυτοῦ οὐκ ἔσται. οὐ γάρ. ἕτερον δέ γε ἑτέρου οὐκ ἔσται, ἕως ἂν ᾖ ἕν· οὐ γὰρ ἑνὶ προσήκει ἑτέρῳ τινὸς εἶναι, ἀλλὰ μόνῳ ἑτέρῳ ἑτέρου, ἄλλῳ δὲ οὐδενί. ὀρθῶς. τῷ μὲν ἄρα ἓν εἶναι οὐκ ἔσται ἕτερον· ἢ οἴει; οὐ δῆτα. ἀλλὰ μὴν εἰ μὴ τούτῳ, οὐχ ἑαυτῷ ἔσται, εἰ δὲ μὴ αὑτῷ, οὐδὲ αὐτό· αὐτὸ δὲ μηδαμῇ ὂν ἕτερον οὐδενὸς ἔσται", "r": "другое, и не было бы само; так что не было бы тем, что̀ есть, — одним, а отличным от одного. — Конечно. — Стало быть, оно не будет ни тожественно с другим, ни отлично от себя. — Не будет. — Не будет оно также отлично от другого, пока будет одно; потому что одному нейдет быть отличным от чего-нибудь, а (идет) только отличному — от отличного, ничему больше. — Правильно. — Одно, чрез то самое, что оно — одно, не будет другим, — или думаешь? — Нет. — А если не чрез это, то и не чрез себя; когда же не чрез себя, то и не само; не будучи же отнюдь отличным само в себе, оно не будет отлично ни от чего. —"}, "139d": {"g": "ἕτερον. ὀρθῶς. οὐδὲ μὴν ταὐτόν γε ἑαυτῷ ἔσται. πῶς δʼ οὔ; οὐχ ἥπερ τοῦ ἑνὸς φύσις, αὑτὴ δήπου καὶ τοῦ ταὐτοῦ. τί δή; ὅτι οὐκ, ἐπειδὰν ταὐτὸν γένηταί τῴ τι, ἓν γίγνεται. ἀλλὰ τί μήν; τοῖς πολλοῖς ταὐτὸν γενόμενον πολλὰ ἀνάγκη γίγνεσθαι ἀλλʼ οὐχ ἕν. ἀληθῆ. ἀλλʼ εἰ τὸ ἓν καὶ τὸ ταὐτὸν μηδαμῇ διαφέρει, ὁπότε τι ταὐτὸν ἐγίγνετο, ἀεὶ ἂν ἓν ἐγίγνετο, καὶ ὁπότε ἕν, ταὐτόν.", "r": "Правильно. — Не будет оно однакож и тожественно с собою. — Как не будет? — Природа одного не та же, что природа тожественного. — Почему так? — Потому, что когда что-либо становится тожественно чему-нибудь, является не одно. — А что же? — При множестве вещей, становится тожественным многое, а не одно. — Правда. — Но если одно и то же ничем не различаются, то, как скоро происходило бы что тожественное, всегда происходило бы одно, а когда"}, "139e": {"g": "πάνυ γε. εἰ ἄρα τὸ ἓν ἑαυτῷ ταὐτὸν ἔσται, οὐχ ἓν ἑαυτῷ ἔσται· καὶ οὕτω ἓν ὂν οὐχ ἓν ἔσται. ἀλλὰ μὴν τοῦτό γε ἀδύνατον· ἀδύνατον ἄρα καὶ τῷ ἑνὶ ἢ ἑτέρου ἕτερον εἶναι ἢ ἑαυτῷ ταὐτόν. ἀδύνατον. οὕτω δὴ ἕτερόν γε ἢ ταὐτὸν τὸ ἓν οὔτʼ ἂν αὑτῷ οὔτʼ ἂν ἑτέρῳ εἴη. οὐ γὰρ οὖν. οὐδὲ μὴν ὅμοιόν τινι ἔσται οὐδʼ ἀνόμοιον οὔτε αὑτῷ οὔτε ἑτέρῳ. τί δή; ὅτι τὸ ταὐτόν που πεπονθὸς ὅμοιον. ναί. τοῦ δέ γε ἑνὸς χωρὶς ἐφάνη τὴν φύσιν τὸ ταὐτόν.", "r": "одно, — то и тожественное. — Конечно. — Стало быть, если одно будет тожественно себе, то не будет одно с собою, и таким образом, будучи одним, не будет одно. — Но это-то невозможно. — Следовательно, невозможно и то, чтобы одно было отлично от другого, или тожественно себе. — Невозможно. — Таким образом одно — отличным ли то, или тожественным — не будет ни в отношении к себе, ни в отношении к другому. — Не будет. — Не будет также ни подобным чему-нибудь, ни не подобным, как в отношении к себе, так и в отношении к другому. — Почему же? — Потому что подобное как будто разделяет свойства тожественного. — Да. — А тожественное оказалось по природе"}, "140a": {"g": "ἐφάνη γάρ. ἀλλὰ μὴν εἴ τι πέπονθε χωρὶς τοῦ ἓν εἶναι τὸ ἕν, πλείω ἂν εἶναι πεπόνθοι ἢ ἕν, τοῦτο δὲ ἀδύνατον. ναί. οὐδαμῶς ἔστιν ἄρα ταὐτὸν πεπονθὸς εἶναι τὸ ἓν οὔτε ἄλλῳ οὔτε ἑαυτῷ. οὐ φαίνεται. οὐδὲ ὅμοιον ἄρα δυνατὸν αὐτὸ εἶναι οὔτε ἄλλῳ οὔτε ἑαυτῷ. οὐκ ἔοικεν. οὐδὲ μὴν ἕτερόν γε πέπονθεν εἶναι τὸ ἕν· καὶ γὰρ οὕτω πλείω ἂν πεπόνθοι εἶναι ἢ ἕν. πλείω γάρ. τό γε μὴν ἕτερον πεπονθὸς ἢ ἑαυτοῦ ἢ ἄλλου ἀνόμοιον ἂν εἴη ἢ ἑαυτῷ", "r": "особым против одного-то. — Оказалось. — Но если бы одно получило некоторое свойство быть особым против одного, то получило бы свойство быть больше, чем одно; а это невозможно. — Да. — Стало быть, одному никак не доступно свойство быть тожественным — ни иному, ни себе. — Явно, что нет. — Следовательно, и подобным не может оно быть — ни иному, ни себе. — Как видно, нет. — Да одному не доступно свойство быть и другим-то; ибо иначе в нём получилось бы больше, чем одно. — Конечно, больше. — То, что принимает свойство отличия по отношению к себе или иному, было бы не подобно себе или иному, а что̀ свойство"}, "140b": {"g": "ἢ ἄλλῳ, εἴπερ τὸ ταὐτὸν πεπονθὸς ὅμοιον. ὀρθῶς. τὸ δέ γε ἕν, ὡς ἔοικεν, οὐδαμῶς ἕτερον πεπονθὸς οὐδαμῶς ἀνόμοιόν ἐστιν οὔτε αὑτῷ οὔτε ἑτέρῳ. οὐ γὰρ οὖν. οὔτε ἄρα ὅμοιον οὔτε ἀνόμοιον οὔθʼ ἑτέρῳ οὔτε ἑαυτῷ ἂν εἴη τὸ ἕν. οὐ φαίνεται. καὶ μὴν τοιοῦτόν γε ὂν οὔτε ἴσον οὔτε ἄνισον ἔσται οὔτε ἑαυτῷ οὔτε ἄλλῳ. πῇ; ἴσον μὲν ὂν τῶν αὐτῶν μέτρων ἔσται ἐκείνῳ ᾧ ἂν ἴσον ᾖ. ναί. μεῖζον δέ που", "r": "тожества — подобно. — Правильно. — Но одно-то, как видно, никак не принимая свойства отличия, никак не не подобно ни себе, ни другому. — Конечно, нет. — Стало быть, одно не будет ни подобно, ни неподобно — ни себе, ни другому. — Явно, что нет. — А будучи таким-то, оно не будет ни равно, ни не равно, как себе, так и другому. — Каким же образом? — Как равное, оно будет той же меры с тем, чему было бы равно. — Да. — Если же оно больше или меньше, по сравнению с тем, чему соразмеримо, то относительно к"}, "140c": {"g": "ἢ ἔλαττον ὄν, οἷς μὲν ἂν σύμμετρον ᾖ, τῶν μὲν ἐλαττόνων πλείω μέτρα ἕξει, τῶν δὲ μειζόνων ἐλάττω. ναί. οἷς δʼ ἂν μὴ σύμμετρον, τῶν μὲν σμικροτέρων, τῶν δὲ μειζόνων μέτρων ἔσται. πῶς γὰρ οὔ; οὐκοῦν ἀδύνατον τὸ μὴ μετέχον τοῦ αὐτοῦ ἢ μέτρων τῶν αὐτῶν εἶναι ἢ ἄλλων ὡντινωνοῦν τῶν αὐτῶν; ἀδύνατον. ἴσον μὲν ἄρα οὔτʼ ἂν ἑαυτῷ οὔτε ἄλλῳ εἴη μὴ τῶν αὐτῶν μέτρων ὄν. οὔκουν φαίνεταί γε. ἀλλὰ μὴν πλειόνων γε μέτρων ὂν ἢ ἐλαττόνων, ὅσωνπερ μέτρων, τοσούτων καὶ μερῶν ἂν εἴη· καὶ", "r": "меньшему будет иметь меру высшую, а относительно к большему — нисшую. — Да. — С чем же не соразмеримо, — мерою будет иной раз больше, другой — меньше. — Как же иначе. — Но возможно ли, чтобы не причастное тожества было или той же меры, или чего бы то ни было того же? — Невозможно. — А что̀ не той же меры, то не может быть равно ни себе, ни иному. — Это-то явно. — Будучи же высшей или нисшей меры, — сколько будет меры, столько будет содержать и частей; и таким образом выйдет опять уже не одно, а"}, "140d": {"g": "οὕτω αὖ οὐκέτι ἓν ἔσται ἀλλὰ τοσαῦτα ὅσαπερ καὶ τὰ μέτρα. ὀρθῶς. εἰ δέ γε ἑνὸς μέτρου εἴη, ἴσον ἂν γίγνοιτο τῷ μέτρῳ· τοῦτο δὲ ἀδύνατον ἐφάνη, ἴσον τῳ αὐτὸ εἶναι. ἐφάνη γάρ. οὔτε ἄρα ἑνὸς μέτρου μετέχον οὔτε πολλῶν οὔτε ὀλίγων, οὔτε τὸ παράπαν τοῦ αὐτοῦ μετέχον, οὔτε ἑαυτῷ ποτε, ὡς ἔοικεν, ἔσται ἴσον οὔτε ἄλλῳ· οὔτε αὖ μεῖζον οὐδὲ ἔλαττον οὔτε ἑαυτοῦ οὔτε ἑτέρου. παντάπασι μὲν οὖν οὕτω.", "r": "столько, сколько будет меры. — Правильно. — Если же будет в одну единицу меры, то вышло бы равно мере; но это оказалось невозможным, чтобы оно было равно чему-нибудь. — Да, оказалось. — Стало быть, не причастное ни одной единицы меры, ни многих, ни немногих, и вообще не причастное того же, оно не будет, как видно, равно ни себе, ни иному, и опять, не будет ни больше, ни меньше — ни"}, "140e": {"g": "τί δέ; πρεσβύτερον ἢ νεώτερον ἢ τὴν αὐτὴν ἡλικίαν ἔχειν τὸ ἓν δοκεῖ τῳ δυνατὸν εἶναι; τί δὴ γὰρ οὔ; ὅτι που ἡλικίαν μὲν τὴν αὐτὴν ἔχον ἢ αὑτῷ ἢ ἄλλῳ ἰσότητος χρόνου καὶ ὁμοιότητος μεθέξει, ὧν ἐλέγομεν οὐ μετεῖναι τῷ ἑνί, οὔτε ὁμοιότητος οὔτε ἰσότητος. ἐλέγομεν γὰρ οὖν. καὶ μὴν καὶ ὅτι ἀνομοιότητός τε καὶ ἀνισότητος οὐ μετέχει, καὶ τοῦτο ἐλέγομεν. πάνυ μὲν οὖν. πῶς οὖν", "r": "себя, ни другого. — Без сомнения. — Что же? кажется ли, что одно может быть или старше, или моложе, или того же с чем-нибудь возраста. — Почему же бы нет? — Потому, что, имея тот же возраст, оно будет причастно равенству во времени и подобию либо себе, либо иному; мы же говорили, что одно не причастно ни подобия, ни равенства. — Да, конечно, говорили. — Что не причастно также ни неподобия,"}, "141a": {"g": "οἷόν τε ἔσται τινὸς ἢ πρεσβύτερον ἢ νεώτερον εἶναι ἢ τὴν αὐτὴν ἡλικίαν ἔχειν τῳ τοιοῦτον ὄν; οὐδαμῶς. οὐκ ἄρα ἂν εἴη νεώτερόν γε οὐδὲ πρεσβύτερον οὐδὲ τὴν αὐτὴν ἡλικίαν ἔχον τὸ ἓν οὔτε αὑτῷ οὔτε ἄλλῳ. οὐ φαίνεται. ἆρʼ οὖν οὐδὲ ἐν χρόνῳ τὸ παράπαν δύναιτο ἂν εἶναι τὸ ἕν, εἰ τοιοῦτον εἴη; ἢ οὐκ ἀνάγκη, ἐάν τι ᾖ ἐν χρόνῳ, ἀεὶ αὐτὸ αὑτοῦ πρεσβύτερον γίγνεσθαι; ἀνάγκη. οὐκοῦν τό γε πρεσβύτερον ἀεὶ νεωτέρου πρεσβύτερον; τί μήν;", "r": "ни неравенства, — и это говорили. — Конечно. — Как же можно быть ему либо старше, либо моложе чего-нибудь, либо иметь тот же с чем-нибудь возраст, если оно таково? — Никак. — Стало быть, одно не может быть ни моложе, ни старше, ни иметь тот же возраст — ни с собою, ни с иным. — Явно, что нет. — Да может ли одно быть даже вообще во времени, если оно таково? Разве не необходимо, чтобы находящееся во времени становилось постоянно старше? — Необходимо. — Старшее-то не старше ли всегда младшего? — Как же. — Следовательно, то, что бывает старше себя,"}, "141b": {"g": "τὸ πρεσβύτερον ἄρα ἑαυτοῦ γιγνόμενον καὶ νεώτερον ἑαυτοῦ ἅμα γίγνεται, εἴπερ μέλλει ἔχειν ὅτου πρεσβύτερον γίγνηται. πῶς λέγεις; ὧδε· διάφορον ἕτερον ἑτέρου οὐδὲν δεῖ γίγνεσθαι ἤδη ὄντος διαφόρου, ἀλλὰ τοῦ μὲν ἤδη ὄντος ἤδη εἶναι, τοῦ δὲ γεγονότος γεγονέναι, τοῦ δὲ μέλλοντος μέλλειν, τοῦ δὲ γιγνομένου οὔτε γεγονέναι οὔτε μέλλειν οὔτε εἶναί πω διάφορον, ἀλλὰ γίγνεσθαι καὶ ἄλλως", "r": "бывает вместе и моложе себя, если то же самое имеет выйти старше чего-нибудь. — Как ты говоришь? — Вот как: одно, различающееся от другого, не нуждается ни в чём для различия, если уже есть различие; и только, когда оно уже есть, — чтобы ему быть; когда оно сбылось, — чтобы сбыться; когда оно имеет произойти, — чтобы ему произойти; когда же оно бывает, то нет нужды, сбылось ли, есть, или имеет быть различие, — лишь бы оно бывало, — и ничего больше. — Да, необходимо. — Но старшее-то есть нечто отличное от младшего, а не от чего инаго. — Конечно. — Стало быть,"}, "141c": {"g": "οὐκ εἶναι. ἀνάγκη γὰρ δή. ἀλλὰ μὴν τό γε πρεσβύτερον διαφορότης νεωτέρου ἐστὶν καὶ οὐδενὸς ἄλλου. ἔστι γάρ. τὸ ἄρα πρεσβύτερον ἑαυτοῦ γιγνόμενον ἀνάγκη καὶ νεώτερον ἅμα ἑαυτοῦ γίγνεσθαι. ἔοικεν. ἀλλὰ μὴν καὶ μήτε πλείω ἑαυτοῦ γίγνεσθαι χρόνον μήτε ἐλάττω, ἀλλὰ τὸν ἴσον χρόνον καὶ γίγνεσθαι ἑαυτῷ καὶ εἶναι καὶ γεγονέναι καὶ μέλλειν ἔσεσθαι. ἀνάγκη γὰρ οὖν καὶ ταῦτα. ἀνάγκη ἄρα ἐστίν, ὡς ἔοικεν, ὅσα γε ἐν χρόνῳ ἐστὶν", "r": "бывающее старше себя необходимо бывает также и моложе себя. — Походит. — Но по времени, конечно, оно не бывает ни больше себя, ни меньше, но и бывает, и есть, и было, и будет себе равновременно. — Да, необходимо и это. — Значит, необходимо, как видно, чтобы всё, находящееся во времени-то и причастное ему, имело тот"}, "141d": {"g": "καὶ μετέχει τοῦ τοιούτου, ἕκαστον αὐτῶν τὴν αὐτήν τε αὐτὸ αὑτῷ ἡλικίαν ἔχειν καὶ πρεσβύτερόν τε αὑτοῦ ἅμα καὶ νεώτερον γίγνεσθαι. κινδυνεύει. ἀλλὰ μὴν τῷ γε ἑνὶ τῶν τοιούτων παθημάτων οὐδὲν μετῆν. οὐ γὰρ μετῆν. οὐδὲ ἄρα χρόνου αὐτῷ μέτεστιν, οὐδʼ ἔστιν ἔν τινι χρόνῳ. οὔκουν δή, ὥς γε ὁ λόγος αἱρεῖ. τί οὖν; τὸ ἦν καὶ τὸ γέγονε καὶ τὸ ἐγίγνετο οὐ χρόνου μέθεξιν δοκεῖ σημαίνειν τοῦ ποτὲ γεγονότος; καὶ μάλα.", "r": "же само с собою возраст, и было как старше, так вместе и моложе себя. — Должно быть. — Но из таких свойств одному-то ничто не было причастно. — Да, не было. — Стало быть, ему не причастно и время, и оно существует не во времени. — Конечно, нет, — как требует этого, по крайней мере, ход речи. — Что же? было, сбылось, происходило, — не кажется ли это означением причастности времени когда-то бывшего? — И очень. — Что еще? будет, произойдет, сбудется, — не означается ли этим,"}, "141e": {"g": "τί δέ; τὸ ἔσται καὶ τὸ γενήσεται καὶ τὸ γενηθήσεται οὐ τοῦ ἔπειτα τοῦ μέλλοντος ; ναί. τὸ δὲ δὴ ἔστι καὶ τὸ γίγνεται οὐ τοῦ νῦν παρόντος; πάνυ μὲν οὖν. εἰ ἄρα τὸ ἓν μηδαμῇ μηδενὸς μετέχει χρόνου, οὔτε ποτὲ γέγονεν οὔτʼ ἐγίγνετο οὔτʼ ἦν ποτέ, οὔτε νῦν γέγονεν οὔτε γίγνεται οὔτε ἔστιν, οὔτʼ ἔπειτα γενήσεται οὔτε γενηθήσεται οὔτε ἔσται. ἀληθέστατα. ἔστιν οὖν οὐσίας ὅπως ἄν τι μετάσχοι ἄλλως ἢ κατὰ τούτων τι; οὐκ ἔστιν. οὐδαμῶς ἄρα τὸ ἓν οὐσίας μετέχει. οὐκ ἔοικεν. οὐδαμῶς ἄρα ἔστι τὸ ἕν. οὐ φαίνεται. οὐδʼ ἄρα οὕτως ἔστιν ὥστε ἓν εἶναι· εἴη γὰρ ἂν ἤδη ὂν καὶ οὐσίας μετέχον· ἀλλʼ ὡς ἔοικεν, τὸ ἓν οὔτε ἕν ἐστιν οὔτε ἔστιν, εἰ δεῖ τῷ", "r": "что̀ будет потом? — Да. — А словами-то есть и бывает не на настоящее ли указывается? — Конечно, так. — Если же одно никак и никакого не причастно времени, то оно и не сбылось никогда, и не происходило, и не было, и теперь не сбывается, не происходит и не есть, и после не произойдет, не сбудется и не будет. — Весьма справедливо. — А есть ли возможность приобщиться сущности иначе, как по которому-нибудь из этих способов? — Нет. — Следовательно, одно никак не причастно сущности. — Походит, что нет. — Поэтому одно совсем не существует. — Явно, что нет. — Стало быть, оно не таково, чтобы ему быть одним: ибо тогда было бы оно уже существующим и причастным сущности. Но одно, как видно, и не одно, и не существует,"}, "142a": {"g": "τοιῷδε λόγῳ πιστεύειν. κινδυνεύει. ὃ δὲ μὴ ἔστι, τούτῳ τῷ μὴ ὄντι εἴη ἄν τι αὐτῷ ἢ αὐτοῦ; καὶ πῶς; οὐδʼ ἄρα ὄνομα ἔστιν αὐτῷ οὐδὲ λόγος οὐδέ τις ἐπιστήμη οὐδὲ αἴσθησις οὐδὲ δόξα. οὐ φαίνεται. οὐδʼ ὀνομάζεται ἄρα οὐδὲ λέγεται οὐδὲ δοξάζεται οὐδὲ γιγνώσκεται, οὐδέ τι τῶν ὄντων αὐτοῦ αἰσθάνεται. οὐκ ἔοικεν. ἦ δυνατὸν οὖν περὶ τὸ ἓν ταῦτα οὕτως ἔχειν; οὔκουν ἔμοιγε δοκεῖ.", "r": "если положиться на такое рассуждение. — Должно быть. — А что̀ не существует, тому — не существующему — может ли что принадлежать, либо как в нём, либо как его? — Не может. — Стало быть, для него нет ни имени, ни слова, ни какого либо знания, ни чувства, ни мнения. — Явно, что нет. — Следовательно, оно и не именуется, и не высказывается, и не мнится, и не познается, и ничто из его существенностей не чувствуется. — Походит, что нет. — Итак, возможно ли, чтобы в отношении к одному это было так? — Мне кажется, нет. \n\nХочешь ли, опять сначала возвратимся к предположению,"}, "142b": {"g": "βούλει οὖν ἐπὶ τὴν ὑπόθεσιν πάλιν ἐξ ἀρχῆς ἐπανέλθωμεν, ἐάν τι ἡμῖν ἐπανιοῦσιν ἀλλοῖον φανῇ; πάνυ μὲν οὖν βούλομαι. οὐκοῦν ἓν εἰ ἔστιν , φαμέν, τὰ συμβαίνοντα περὶ αὐτοῦ, ποῖά ποτε τυγχάνει ὄντα, διομολογητέα ταῦτα· οὐχ οὕτω; ναί. ὅρα δὴ ἐξ ἀρχῆς. ἓν εἰ ἔστιν , ἆρα οἷόν τε αὐτὸ εἶναι μέν, οὐσίας δὲ μὴ μετέχειν; οὐχ οἷόν τε. οὐκοῦν καὶ ἡ οὐσία τοῦ ἑνὸς εἴη ἂν οὐ ταὐτὸν οὖσα τῷ ἑνί· οὐ γὰρ ἂν ἐκείνη ἦν ἐκείνου οὐσία, οὐδʼ ἂν", "r": "— иначе ли что-нибудь представится нам при восхождении? — Уж конечно, хочу. — Итак, положив, что есть одно, нам надо, говорим, согласиться между собою, какие могут выйти для него из этого последствия. Не так ли? — Да. — Смотри же сначала.\n\nЕсли одно есть, — возможно ли ему быть, не приобщаясь сущности? — Невозможно. — Так она будет сущностью и одного, но не то же самое с одним; ибо иначе не была бы его сущностью, и то одно не было бы её причастно, — но всё"}, "142c": {"g": "ἐκεῖνο, τὸ ἕν, ἐκείνης μετεῖχεν, ἀλλʼ ὅμοιον ἂν ἦν λέγειν ἕν τε εἶναι καὶ ἓν ἕν. νῦν δὲ οὐχ αὕτη ἐστὶν ἡ ὑπόθεσις, εἰ ἓν ἕν , τί χρὴ συμβαίνειν, ἀλλʼ εἰ ἓν ἔστιν · οὐχ οὕτω; πάνυ μὲν οὖν. οὐκοῦν ὡς ἄλλο τι σημαῖνον τὸ ἔστι τοῦ ἕν ; ἀνάγκη. ἆρα οὖν ἄλλο ἢ ὅτι οὐσίας μετέχει τὸ ἕν, τοῦτʼ ἂν εἴη τὸ λεγόμενον, ἐπειδάν τις συλλήβδην εἴπῃ ὅτι ἓν ἔστιν; πάνυ γε. πάλιν δὴ λέγωμεν, ἓν εἰ ἔστιν , τί συμβήσεται. σκόπει οὖν εἰ οὐκ ἀνάγκη ταύτην τὴν ὑπόθεσιν τοιοῦτον ὂν τὸ ἓν σημαίνειν, οἷον", "r": "равно было бы говорить: «одно есть», и «одно — одно». Задача же теперь не в том, что̀ произойдет, если «одно — одно», а что̀, если «одно есть». Так ли? — Конечно, так. — Поэтому словом «есть» здесь означается иное, чем словом «одно». — Необходимо. — Так иное ли выражается положением, что одно причастно сущности, чем то, когда кто сказал бы кратко, что одно есть? — Конечно, не иное. — Скажем опять: Одно есть; — что же выйдет из этого? Наблюдай-ка: это предположение не принимает ли необходимо одно в значении чего-то состоящего из частей? — Как? — Вот как: если"}, "142d": {"g": "μέρη ἔχειν; πῶς; ὧδε· εἰ τὸ ἔστι τοῦ ἑνὸς ὄντος λέγεται καὶ τὸ ἓν τοῦ ὄντος ἑνός, ἔστι δὲ οὐ τὸ αὐτὸ ἥ τε οὐσία καὶ τὸ ἕν, τοῦ αὐτοῦ δὲ ἐκείνου οὗ ὑπεθέμεθα, τοῦ ἑνὸς ὄντος, ἆρα οὐκ ἀνάγκη τὸ μὲν ὅλον ἓν ὂν εἶναι αὐτό, τούτου δὲ γίγνεσθαι μόρια τό τε ἓν καὶ τὸ εἶναι; ἀνάγκη. πότερον οὖν ἑκάτερον τῶν μορίων τούτων μόριον μόνον προσεροῦμεν, ἢ τοῦ ὅλου μόριον τό γε μόριον προσρητέον; τοῦ ὅλου. καὶ ὅλον ἄρα ἐστί, ὃ ἂν ἓν ᾖ, καὶ μόριον ἔχει. πάνυ γε. τί οὖν; τῶν μορίων ἑκάτερον", "r": "слово «есть» принадлежит тому, что̀ одно, и слово «одно» — тому, что есть, а сущность и одно — не то же, и однакож принадлежат тому, что мы положили как сущее одно; то не необходимо ли, чтобы само одно было целым, а одно и сущее — его частями? — Необходимо. — Но ту и другую из этих частей назовем ли мы только частью, или часть-то надобно назвать частью целого? — Целого. — И целое, стало быть,"}, "142e": {"g": "τούτων τοῦ ἑνὸς ὄντος, τό τε ἓν καὶ τὸ ὄν, ἆρα ἀπολείπεσθον ἢ τὸ ἓν τοῦ εἶναι μορίου ἢ τὸ ὂν τοῦ ἑνὸς μορίου; οὐκ ἂν εἴη. πάλιν ἄρα καὶ τῶν μορίων ἑκάτερον τό τε ἓν ἴσχει καὶ τὸ ὄν, καὶ γίγνεται τὸ ἐλάχιστον ἐκ δυοῖν αὖ μορίοιν τὸ μόριον, καὶ κατὰ τὸν αὐτὸν λόγον οὕτως ἀεί, ὅτιπερ ἂν μόριον γένηται, τούτω τὼ μορίω ἀεὶ ἴσχει· τό τε γὰρ ἓν τὸ ὂν ἀεὶ ἴσχει καὶ τὸ ὂν τὸ ἕν· ὥστε ἀνάγκη", "r": "есть то, что — одно и имеет части. — Конечно. — Так что же? Та и другая из этих частей одного сущего, — одно и сущее, — отделяются ли — либо одно от части сущего, либо сущее от части одного? — Едва ли. — Следовательно, опять та и другая из частей содержит в себе одно и сущее, и самая малая часть состоит также из двух этих частей. Таким же точно образом всегда: какая бы ни была часть, — в ней непременно заключаются эти части; потому что одно непременно имеет в себе сущее, а сущее имеет одно; так что всегда необходимо выходит двойство, а единство никогда. —"}, "143a": {"g": "δύʼ ἀεὶ γιγνόμενον μηδέποτε ἓν εἶναι. παντάπασι μὲν οὖν. οὐκοῦν ἄπειρον ἂν τὸ πλῆθος οὕτω τὸ ἓν ὂν εἴη; ἔοικεν. ἴθι δὴ καὶ τῇδε ἔτι. πῇ; οὐσίας φαμὲν μετέχειν τὸ ἕν, διὸ ἔστιν; ναί. καὶ διὰ ταῦτα δὴ τὸ ἓν ὂν πολλὰ ἐφάνη. οὕτω. τί δέ; αὐτὸ τὸ ἕν, ὃ δή φαμεν οὐσίας μετέχειν, ἐὰν αὐτὸ τῇ διανοίᾳ μόνον καθʼ αὑτὸ λάβωμεν ἄνευ τούτου οὗ φαμεν μετέχειν, ἆρά γε ἓν μόνον φανήσεται ἢ καὶ πολλὰ τὸ αὐτὸ τοῦτο; ἕν, οἶμαι ἔγωγε.", "r": "Без сомнения. — Стало быть, одно, как сущее, не будет ли так-то беспредельно многое. — Походит. — Давай-ка рассмотрим еще и так. — Как? — Одно, говорим, причастно сущности, поколику оно есть? — Да. — По этой-то причине одно явилось многим. — Так. — Что же? само одно, которое, говорим, причастно сущности, если мы возьмем его само по себе, только рассудком, без того, чего оно причастно, явится ли чисто одним, или это само будет многое? — Я думаю, одним. — Посмотрим-ка: не необходимо ли, чтобы другое"}, "143b": {"g": "ἴδωμεν δή· ἄλλο τι ἕτερον μὲν ἀνάγκη τὴν οὐσίαν αὐτοῦ εἶναι, ἕτερον δὲ αὐτό, εἴπερ μὴ οὐσία τὸ ἕν, ἀλλʼ ὡς ἓν οὐσίας μετέσχεν. ἀνάγκη. οὐκοῦν εἰ ἕτερον μὲν ἡ οὐσία, ἕτερον δὲ τὸ ἕν, οὔτε τῷ ἓν τὸ ἓν τῆς οὐσίας ἕτερον οὔτε τῷ οὐσία εἶναι ἡ οὐσία τοῦ ἑνὸς ἄλλο, ἀλλὰ τῷ ἑτέρῳ τε καὶ ἄλλῳ ἕτερα ἀλλήλων. πάνυ μὲν οὖν. ὥστε οὐ ταὐτόν ἐστιν οὔτε τῷ ἑνὶ οὔτε τῇ οὐσίᾳ τὸ ἕτερον. πῶς γάρ;", "r": "была его сущность, и другое — само оно, если одно — не сущность, но есть одно, сделавшееся причастным сущности? — Необходимо. — Если же другое — сущность и другое — одно, то не оттого выходит другим одно, что одно существует, и не оттого — сущность, что сущность есть, но они взаимно отличны в силу отличного и инаго — Конечно, так. — Так что отличное не тожественно ни с одним, ни с сущностью. — Как же. — Что же? если бы мы избрали из них, всё равно, либо сущность и отличное, либо сущность и одно,"}, "143c": {"g": "τί οὖν; ἐὰν προελώμεθα αὐτῶν εἴτε βούλει τὴν οὐσίαν καὶ τὸ ἕτερον εἴτε τὴν οὐσίαν καὶ τὸ ἓν εἴτε τὸ ἓν καὶ τὸ ἕτερον, ἆρʼ οὐκ ἐν ἑκάστῃ τῇ προαιρέσει προαιρούμεθά τινε ὣ ὀρθῶς ἔχει καλεῖσθαι ἀμφοτέρω; πῶς; ὧδε· ἔστιν οὐσίαν εἰπεῖν; ἔστιν. καὶ αὖθις εἰπεῖν ἕν; καὶ τοῦτο. ἆρʼ οὖν οὐχ ἑκάτερον αὐτοῖν εἴρηται; ναί. τί δʼ ὅταν εἴπω οὐσία τε καὶ ἕν, ἆρα οὐκ ἀμφοτέρω; πάνυ γε. οὐκοῦν καὶ ἐὰν οὐσία τε καὶ ἕτερον ἢ ἕτερόν τε καὶ ἕν, καὶ οὕτω πανταχῶς ἐφʼ ἑκάστου ἄμφω λέγω; ναί.", "r": "либо одно и отличное, то в каждом избрании избираем не двоичное ли что-нибудь, к чему можно правильно приложить название оба? — Как? — Вот как: можно ли сказать сущность? — Можно. — И тотчас сказать одно. — И это можно. — Так называется не то ли и другое из них? — Да. — Что же, когда я скажу сущность и одно, — разве это не оба? — Конечно. — Значит, то же, когда — сущность и отличное, либо отличное и одно, и так во всех случаях, — каждый"}, "143d": {"g": "ὣ δʼ ἂν ἄμφω ὀρθῶς προσαγορεύησθον, ἆρα οἷόν τε ἄμφω μὲν αὐτὼ εἶναι, δύο δὲ μή; οὐχ οἷόν τε. ὣ δʼ ἂν δύο ἦτον, ἔστι τις μηχανὴ μὴ οὐχ ἑκάτερον αὐτοῖν ἓν εἶναι; οὐδεμία. τούτων ἄρα ἐπείπερ σύνδυο ἕκαστα συμβαίνει εἶναι, καὶ ἓν ἂν εἴη ἕκαστον. φαίνεται. εἰ δὲ ἓν ἕκαστον αὐτῶν ἐστι, συντεθέντος ἑνὸς ὁποιουοῦν ᾑτινιοῦν συζυγίᾳ οὐ τρία γίγνεται τὰ πάντα; ναί. τρία δὲ οὐ περιττὰ καὶ δύο ἄρτια; πῶς δʼ οὔ; τί δέ; δυοῖν ὄντοιν οὐκ", "r": "раз я говорю оба? — Да. — Но к чему правильно прилагается слово оба, в том возможно ли обоим-то быть, а двум нет? — Невозможно. — А в чём были два, есть ли какая-нибудь возможность тому или другому из них не быть одним? — Никакой. — Стало быть, когда они сходятся отдельно по два, то каждое отдельное будет и одно. — Явно. — Если же каждое из них есть одно, то, по сложении какого-либо одного с какою бы то ни было парою их, не выйдет ли всего три? — Да. — Но три не есть ли нечет, а два — чет? — Как же иначе. — Что же теперь? когда есть два,"}, "143e": {"g": "ἀνάγκη εἶναι καὶ δίς, καὶ τριῶν ὄντων τρίς, εἴπερ ὑπάρχει τῷ τε δύο τὸ δὶς ἓν καὶ τῷ τρία τὸ τρὶς ἕν; ἀνάγκη. δυοῖν δὲ ὄντοιν καὶ δὶς οὐκ ἀνάγκη δύο δὶς εἶναι; καὶ τριῶν καὶ τρὶς οὐκ ἀνάγκη αὖ τρία τρὶς εἶναι; πῶς δʼ οὔ; τί δέ; τριῶν ὄντων καὶ δὶς ὄντων καὶ δυοῖν ὄντοιν καὶ τρὶς ὄντοιν οὐκ ἀνάγκη τε τρία δὶς εἶναι καὶ δύο τρίς; πολλή γε. ἄρτιά τε ἄρα ἀρτιάκις ἂν εἴη καὶ", "r": "не необходимо ли есть и дважды, а когда три — трижды, если два предполагает дважды одно, а три — трижды одно? — Необходимо. — Но где есть два и дважды, там не необходимо ли быть дважды-двум? а где есть три и трижды, там не необходимо ли тоже быть трижды-трем? — Ка̀к не необходимо. — Что еще? где есть три и есть дважды, и где есть два и есть трижды, там не необходимо ли быть дважды-трем и трижды-двум? — Совершенно необходимо. — Стало"}, "144a": {"g": "περιττὰ περιττάκις καὶ ἄρτια περιττάκις καὶ περιττὰ ἀρτιάκις. ἔστιν οὕτω. εἰ οὖν ταῦτα οὕτως ἔχει, οἴει τινὰ ἀριθμὸν ὑπολείπεσθαι ὃν οὐκ ἀνάγκη εἶναι; οὐδαμῶς γε. εἰ ἄρα ἔστιν ἕν, ἀνάγκη καὶ ἀριθμὸν εἶναι. ἀνάγκη. ἀλλὰ μὴν ἀριθμοῦ γε ὄντος πολλὰ ἂν εἴη καὶ πλῆθος ἄπειρον τῶν ὄντων· ἢ οὐκ ἄπειρος ἀριθμὸς πλήθει καὶ μετέχων οὐσίας γίγνεται; καὶ πάνυ γε. οὐκοῦν εἰ πᾶς ἀριθμὸς οὐσίας μετέχει, καὶ τὸ μόριον ἕκαστον τοῦ ἀριθμοῦ μετέχοι ἂν αὐτῆς; ναί.", "r": "быть, необходимо быть и четно-чету, и нечетно-нечету, и нечетно-чету, и четно-нечету. — Это так. — А если это так, то остается ли, думаешь, какое-нибудь число, которое не являлось бы необходимо? — Отнюдь нет. — Следовательно, если есть одно, то необходимо быть и числу. — Необходимо. — А когда есть число, выйдет многое; и вещи, по множеству, будут беспредельны. Разве число, по множеству, не беспредельно, если оно бывает причастно и сущности? — Конечно, беспредельно. — Но как скоро всё число причастно сущности, то и каждая часть числа не будет ли"}, "144b": {"g": "ἐπὶ πάντα ἄρα πολλὰ ὄντα ἡ οὐσία νενέμηται καὶ οὐδενὸς ἀποστατεῖ τῶν ὄντων, οὔτε τοῦ σμικροτάτου οὔτε τοῦ μεγίστου; ἢ τοῦτο μὲν καὶ ἄλογον ἐρέσθαι; πῶς γὰρ ἂν δὴ οὐσία γε τῶν ὄντων του ἀποστατοῖ; οὐδαμῶς. κατακεκερμάτισται ἄρα ὡς οἷόν τε σμικρότατα καὶ μέγιστα καὶ πανταχῶς ὄντα, καὶ μεμέρισται πάντων μάλιστα, καὶ ἔστι", "r": "причастна её? — Да. — Стало быть, сущность разделилась по всему множеству вещей, и не отступает ни от одной существенности, — как наименьшей, так и наибольшей? Или об этом нелепо и спрашивать? ибо ка̀к сущность-то могла бы отступать от существенностей? — Никак. — Следовательно, она раздроблена до последней возможности — по наименьшему и наибольшему, и по всячески существующему, расчленена как ничто иное, и частей сущности — без конца. — Так."}, "144c": {"g": "μέρη ἀπέραντα τῆς οὐσίας. ἔχει οὕτω. πλεῖστα ἄρα ἐστὶ τὰ μέρη αὐτῆς. πλεῖστα μέντοι. τί οὖν; ἔστι τι αὐτῶν ὃ ἔστι μὲν μέρος τῆς οὐσίας, οὐδὲν μέντοι μέρος; καὶ πῶς ἄν τοι τοῦτο γένοιτο; ἀλλʼ εἴπερ γε οἶμαι ἔστιν, ἀνάγκη αὐτὸ ἀεί, ἕωσπερ ἂν ᾖ, ἕν γέ τι εἶναι, μηδὲν δὲ ἀδύνατον. ἀνάγκη. πρὸς ἅπαντι ἄρα ἑκάστῳ τῷ τῆς οὐσίας μέρει πρόσεστιν τὸ ἕν, οὐκ ἀπολειπόμενον οὔτε σμικροτέρου οὔτε μείζονος μέρους οὔτε ἄλλου οὐδενός. οὕτω. ἆρα οὖν ἓν", "r": "— Стало быть, части её многочисленны. — Конечно, многочисленны. — Так что же? есть ли какая из них, которая хотя и есть часть сущности, однако не часть? — Да как же это могло бы быть? — Но если она есть, то необходимо ей, думаю, пока есть, всегда быть чем-либо одним, и не быть одним невозможно. — Необходимо. — Стало быть, всякой отдельной части сущности присуще одно, не оставляющее ни меньшей, ни большей части, и никакой иной. — Так."}, "144d": {"g": "ὂν πολλαχοῦ ἅμα ὅλον ἐστί; τοῦτο ἄθρει. ἀλλʼ ἀθρῶ καὶ ὁρῶ ὅτι ἀδύνατον. μεμερισμένον ἄρα, εἴπερ μὴ ὅλον· ἄλλως γάρ που οὐδαμῶς ἅμα ἅπασι τοῖς τῆς οὐσίας μέρεσιν παρέσται ἢ μεμερισμένον. ναί. καὶ μὴν τό γε μεριστὸν πολλὴ ἀνάγκη εἶναι τοσαῦτα ὅσαπερ μέρη. ἀνάγκη. οὐκ ἄρα ἀληθῆ ἄρτι ἐλέγομεν λέγοντες ὡς πλεῖστα μέρη ἡ οὐσία νενεμημένη εἴη. οὐδὲ γὰρ πλείω τοῦ ἑνὸς νενέμηται, ἀλλʼ", "r": "— Будучи же повсюду одним, не есть ли оно вместе целое? Сообрази это. — Соображаю, и вижу, что это невозможно. — Стало быть, оно расчленено, если не есть целое; ибо присоединяться ко всем вместе частям сущности будет возможно, вероятно, не иначе, как расчленившись. — Да. — А расчленившемуся-то крайне необходимо быть стольким, сколько частей. — Необходимо. — Следовательно, мы неправду недавно говорили, полагая, будто бы сущность разделена на весьма многие части; ведь она в своем делении, по числу"}, "144e": {"g": "ἴσα, ὡς ἔοικε, τῷ ἑνί· οὔτε γὰρ τὸ ὂν τοῦ ἑνὸς ἀπολείπεται οὔτε τὸ ἓν τοῦ ὄντος, ἀλλʼ ἐξισοῦσθον δύο ὄντε ἀεὶ παρὰ πάντα. παντάπασιν οὕτω φαίνεται. τὸ ἓν ἄρα αὐτὸ κεκερματισμένον ὑπὸ τῆς οὐσίας πολλά τε καὶ ἄπειρα τὸ πλῆθός ἐστιν. φαίνεται. οὐ μόνον ἄρα τὸ ὂν ἓν πολλά ἐστιν, ἀλλὰ καὶ αὐτὸ τὸ ἓν ὑπὸ τοῦ ὄντος διανενεμημένον πολλὰ ἀνάγκη εἶναι. παντάπασι μὲν οὖν. καὶ μὴν ὅτι γε ὅλου τὰ μόρια μόρια, πεπερασμένον ἂν εἴη κατὰ τὸ ὅλον τὸ ἕν· ἢ οὐ περιέχεται ὑπὸ τοῦ ὅλου τὰ", "r": "частей, не больше одного, но, как видно, равна одному, так как ни сущее не расстается с одним, ни одно с сущим, но эти два всегда и во всём уравниваются. — Представляется совершенно так. — Стало быть, само одно, раздробленное сущностью, есть многое и, по множеству, беспредельное. — Явно. — Следовательно, не только сущее есть многое, но и одному, разделенному сущим, необходимо быть многим. — Без сомнения, так. — И однакож, так как части суть части именно целого, то, по целому, одно будет определенно. Разве части не объемлются целым? — Необходимо."}, "145a": {"g": "μόρια; ἀνάγκη. ἀλλὰ μὴν τό γε περιέχον πέρας ἂν εἴη. πῶς δʼ οὔ; τὸ ἓν ἄρα ὂν ἕν τέ ἐστί που καὶ πολλά, καὶ ὅλον καὶ μόρια, καὶ πεπερασμένον καὶ ἄπειρον πλήθει. φαίνεται. ἆρʼ οὖν οὐκ, ἐπείπερ πεπερασμένον, καὶ ἔσχατα ἔχον; ἀνάγκη. τί δέ; εἰ ὅλον, οὐ καὶ ἀρχὴν ἂν ἔχοι καὶ μέσον καὶ τελευτήν; ἢ οἷόν τέ τι ὅλον εἶναι ἄνευ τριῶν τούτων; κἄν του ἓν ὁτιοῦν αὐτῶν ἀποστατῇ, ἐθελήσει ἔτι ὅλον εἶναι; οὐκ ἐθελήσει. καὶ ἀρχὴν δή, ὡς ἔοικεν, καὶ", "r": "— А объемлющее-то будет предел. — Ка̀к не предел? — Стало быть, одно, как сущее, вероятно, есть и одно и многое, и целое и части, и определенное и, по множеству, беспредельное. — Явно. — А если оно определенно, то не имеет ли крайностей? — Необходимо. — Что же? если оно — целое, то не имеет ли начала, средины и конца? Разве возможно что-нибудь целое, без этих трех? И если бы отпало хотя одно из них, — будет ли уже целое? — Не будет. — Так"}, "145b": {"g": "τελευτὴν καὶ μέσον ἔχοι ἂν τὸ ἕν. ἔχοι. ἀλλὰ μὴν τό γε μέσον ἴσον τῶν ἐσχάτων ἀπέχει· οὐ γὰρ ἂν ἄλλως μέσον εἴη. οὐ γάρ. καὶ σχήματος δή τινος, ὡς ἔοικε, τοιοῦτον ὂν μετέχοι ἂν τὸ ἕν, ἤτοι εὐθέος ἢ στρογγύλου ἤ τινος μεικτοῦ ἐξ ἀμφοῖν. μετέχοι γὰρ ἄν. ἆρʼ οὖν οὕτως ἔχον οὐκ αὐτό τε ἐν ἑαυτῷ ἔσται καὶ ἐν ἄλλῳ; πῶς; τῶν μερῶν που ἕκαστον ἐν τῷ ὅλῳ ἐστὶ καὶ οὐδὲν ἐκτὸς τοῦ ὅλου. οὕτω. πάντα δὲ τὰ μέρη ὑπὸ τοῦ", "r": "одно имеет, как видно, и начало, и конец, и средину. — Имеет. — Но средина-то одинаково отстоит от крайностей, потому что иначе не была бы и срединою. — Конечно, нет. — Будучи же таким, одно причастно, как видно, и какой-нибудь фигуры, например, прямолинейной, круглой, или иной, смешанной из обеих. — Конечно, причастно. — А с таким видом не будет ли оно и в себе, и в ином? — Как? — Вероятно, каждая из его частей находится в целом, и ни одна вне целого. — Так. — И все части объемлются целым? — Да. — И одно составляют именно все"}, "145c": {"g": "ὅλου περιέχεται; ναί. καὶ μὴν τά γε πάντα μέρη τὰ αὑτοῦ τὸ ἕν ἐστι, καὶ οὔτε τι πλέον οὔτε ἔλαττον ἢ πάντα. οὐ γάρ. οὐκοῦν καὶ τὸ ὅλον τὸ ἕν ἐστιν; πῶς δʼ οὔ; εἰ ἄρα πάντα τὰ μέρη ἐν ὅλῳ τυγχάνει ὄντα, ἔστι δὲ τά τε πάντα τὸ ἓν καὶ αὐτὸ τὸ ὅλον, περιέχεται δὲ ὑπὸ τοῦ ὅλου τὰ πάντα, ὑπὸ τοῦ ἑνὸς ἂν περιέχοιτο τὸ ἕν, καὶ οὕτως ἂν ἤδη τὸ ἓν αὐτὸ ἐν ἑαυτῷ εἴη. φαίνεται. ἀλλὰ μέντοι τό γε ὅλον αὖ οὐκ ἐν τοῖς μέρεσίν ἐστιν, οὔτε ἐν πᾶσιν οὔτε", "r": "его части, — не больше что-нибудь и не меньше, как все. — Конечно, не больше и не меньше. — Поэтому одно не есть ли и целое? — Как не целое. — Следовательно, если все части находятся в целом, если все они составляют одно и само целое, и все объемлются целым; то одно будет обнимаемо одним, и таким образом одно будет уже само в себе. — Явно. — Но с другой стороны, опять, целое-то — не в частях, ни во всех, ни в некоторых; ведь если во всех, то необходимо и в одной, так как, не находясь в одной, оно, вероятно, не могло бы уже находиться и во"}, "145d": {"g": "ἐν τινί. εἰ γὰρ ἐν πᾶσιν, ἀνάγκη καὶ ἐν ἑνί· ἔν τινι γὰρ ἑνὶ μὴ ὂν οὐκ ἂν ἔτι που δύναιτο ἔν γε ἅπασιν εἶναι· εἰ δὲ τοῦτο μὲν τὸ ἓν τῶν ἁπάντων ἐστί, τὸ δὲ ὅλον ἐν τούτῳ μὴ ἔνι, πῶς ἔτι ἔν γε τοῖς πᾶσιν ἐνέσται; οὐδαμῶς. οὐδὲ μὴν ἐν τισὶ τῶν μερῶν· εἰ γὰρ ἐν τισὶ τὸ ὅλον εἴη, τὸ πλέον ἂν ἐν τῷ ἐλάττονι εἴη, ὅ ἐστιν ἀδύνατον. ἀδύνατον γάρ. μὴ ὂν δʼ ἐν πλέοσιν μηδʼ ἐν ἑνὶ μηδʼ ἐν ἅπασι τοῖς μέρεσι τὸ ὅλον οὐκ ἀνάγκη ἐν ἑτέρῳ τινὶ εἶναι ἢ μηδαμοῦ", "r": "всех-то. И если эта одна есть одна из всех, целого же в ней нет, то как будет оно заключаться во всех? — Никак. — Равно и не в некоторых из частей; ибо если бы целое находилось в некоторых, то большее заключалось бы в меньшем, что невозможно. — Конечно, невозможно. — Но как скоро, целого нет ни во многих частях, ни в одной, ни во всех, то не необходимо ли быть ему или в другом чём-либо, или уже не быть нигде? — Необходимо."}, "145e": {"g": "ἔτι εἶναι; ἀνάγκη. οὐκοῦν μηδαμοῦ μὲν ὂν οὐδὲν ἂν εἴη, ὅλον δὲ ὄν, ἐπειδὴ οὐκ ἐν αὑτῷ ἐστιν, ἀνάγκη ἐν ἄλλῳ εἶναι; πάνυ γε. ἧι μὲν ἄρα τὸ ἓν ὅλον, ἐν ἄλλῳ ἐστίν· ᾗ δὲ τὰ πάντα μέρη ὄντα τυγχάνει, αὐτὸ ἐν ἑαυτῷ· καὶ οὕτω τὸ ἓν ἀνάγκη αὐτό τε ἐν ἑαυτῷ εἶναι καὶ ἐν ἑτέρῳ. ἀνάγκη. οὕτω δὴ πεφυκὸς τὸ ἓν ἆρʼ οὐκ ἀνάγκη καὶ κινεῖσθαι καὶ ἑστάναι; πῇ; ἕστηκε μέν που, εἴπερ αὐτὸ ἐν ἑαυτῷ", "r": "— Не будучи же нигде, оно было бы ничто; а будучи целым и находясь не в себе, не необходимо ли будет оно в ином? — Конечно. — Итак, поколику одно есть целое, оно находится в ином, а поколику существует во всех частях, оно — само в себе; таким образом одно, необходимо, и само в себе, и в другом. — Необходимо. — Если же одно по природе таково, то не необходимо ли и двигаться ему, и стоять? — Каким образом? — Оно, вероятно, стоит, если находится само в себе; потому что, будучи в одном и не исходя из него, оно будет в том же, в себе. —"}, "146a": {"g": "ἐστιν· ἐν γὰρ ἑνὶ ὂν καὶ ἐκ τούτου μὴ μεταβαῖνον ἐν τῷ αὐτῷ ἂν εἴη, ἐν ἑαυτῷ. ἔστι γάρ. τὸ δέ γε ἐν τῷ αὐτῷ ἀεὶ ὂν ἑστὸς δήπου ἀνάγκη ἀεὶ εἶναι. πάνυ γε. τί δέ; τὸ ἐν ἑτέρῳ ἀεὶ ὂν οὐ τὸ ἐναντίον ἀνάγκη μηδέποτʼ ἐν ταὐτῷ εἶναι, μηδέποτε δὲ ὂν ἐν τῷ αὐτῷ μηδὲ ἑστάναι, μὴ ἑστὸς δὲ κινεῖσθαι; οὕτως. ἀνάγκη ἄρα τὸ ἕν, αὐτό τε ἐν ἑαυτῷ ἀεὶ ὂν καὶ ἐν ἑτέρῳ, ἀεὶ κινεῖσθαί τε καὶ ἑστάναι. φαίνεται. καὶ μὴν ταὐτόν γε δεῖ εἶναι αὐτὸ ἑαυτῷ καὶ ἕτερον", "r": "Конечно, так. — А что пребывает всегда в том же, тому, вероятно, необходимо всегда стоять. — Конечно. — Что же? всегда находящемуся в другом не необходимо ли, напротив, никогда не быть в том же, никогда не бывая в том же, никогда не стоять, а никогда не стоя, всегда двигаться? — Так. — Стало быть, необходимо, чтобы одно, будучи в себе и в другом, всегда двигалось и стояло. — Явно. — Притом, оно должно быть и тожественно-такис собою, и отлично от себя; равно как и в отношении к другим вещам — отожествляться с ними и отличаться"}, "146b": {"g": "ἑαυτοῦ, καὶ τοῖς ἄλλοις ὡσαύτως ταὐτόν τε καὶ ἕτερον εἶναι, εἴπερ καὶ τὰ πρόσθεν πέπονθεν. πῶς; πᾶν που πρὸς ἅπαν ὧδε ἔχει, ἢ ταὐτόν ἐστιν ἢ ἕτερον· ἢ ἐὰν μὴ ταὐτὸν ᾖ μηδʼ ἕτερον, μέρος ἂν εἴη τούτου πρὸς ὃ οὕτως ἔχει, ἢ ὡς πρὸς μέρος ὅλον ἂν εἴη. φαίνεται. ἆρʼ οὖν τὸ ἓν αὐτὸ αὑτοῦ μέρος ἐστίν; οὐδαμῶς. οὐδʼ ἄρα ὡς πρὸς μέρος αὐτὸ αὑτοῦ ὅλον ἂν εἴη, πρὸς ἑαυτὸ μέρος ὄν. οὐ γὰρ οἷόν", "r": "от них, — если принадлежат ему прежде упомянутые свойства. — Как? — Всё ко всему, вероятно, относится так: оно или то же, или отлично; или если не то же и не отлично, то, может быть, составляет часть того, к чему так относится, или же стоит к нему в отношении целаго к своей части. — Явно. — Так само одно есть ли часть себя? — Отнюдь. — Следовательно, не будет и целым самого себя, как бы части, стоя в отношении к себе, как к части. — Потому что это невозможно. — Но одно отлично ли от одного? — Ну, нет. — Стало быть, оно не"}, "146c": {"g": "τε. ἀλλʼ ἆρα ἕτερόν ἐστιν ἑνὸς τὸ ἕν; οὐ δῆτα. οὐδʼ ἄρα ἑαυτοῦ γε ἕτερον ἂν εἴη. οὐ μέντοι. εἰ οὖν μήτε ἕτερον μήτε ὅλον μήτε μέρος αὐτὸ πρὸς ἑαυτό ἐστιν, οὐκ ἀνάγκη ἤδη ταὐτὸν εἶναι αὐτὸ ἑαυτῷ; ἀνάγκη. τί δέ; τὸ ἑτέρωθι ὂν αὐτὸ ἑαυτοῦ ἐν τῷ αὐτῷ ὄντος ἑαυτῷ οὐκ ἀνάγκη αὐτὸ ἑαυτοῦ ἕτερον εἶναι, εἴπερ καὶ ἑτέρωθι ἔσται; ἔμοιγε δοκεῖ. οὕτω μὴν ἐφάνη ἔχον τὸ ἕν, αὐτό τε ἐν ἑαυτῷ ὂν ἅμα καὶ ἐν ἑτέρῳ. ἐφάνη γάρ. ἕτερον ἄρα, ὡς ἔοικεν,", "r": "отлично и от себя-то. — Конечно, нет. — Так если оно само в отношении к себе не есть ни отличное, ни целое, ни часть, то не необходимо ли уже быть ему самому для себя тем же? — Необходимо. — Что же теперь? тому, что находится в ином месте от себя, пребывающего в самом себе, не необходимо ли ему быть отличным от себя, если оно будет инуду? — Мне кажется. — А таким действительно представилось нам одно, что оно находится вместе и само в себе, и в другом. — Да, представилось. — Стало быть, таким-то образом одно, как видно, отлично"}, "146d": {"g": "εἴη ταύτῃ ἂν ἑαυτοῦ τὸ ἕν. ἔοικεν. τί οὖν; εἴ τού τι ἕτερόν ἐστιν, οὐχ ἑτέρου ὄντος ἕτερον ἔσται; ἀνάγκη. οὐκοῦν ὅσα μὴ ἕν ἐστιν, ἅπανθʼ ἕτερα τοῦ ἑνός, καὶ τὸ ἓν τῶν μὴ ἕν; πῶς δʼ οὔ; ἕτερον ἄρα ἂν εἴη τὸ ἓν τῶν ἄλλων. ἕτερον. ὅρα δή· αὐτό τε ταὐτὸν καὶ τὸ ἕτερον ἆρʼ οὐκ ἐναντία ἀλλήλοις; πῶς δʼ οὔ; ἦ οὖν ἐθελήσει ταὐτὸν ἐν τῷ ἑτέρῳ ἢ τὸ ἕτερον ἐν ταὐτῷ ποτε εἶναι; οὐκ ἐθελήσει. εἰ ἄρα τὸ ἕτερον ἐν τῷ αὐτῷ μηδέποτε ἔσται, οὐδὲν ἔστι τῶν ὄντων ἐν ᾧ ἐστὶν τὸ ἕτερον χρόνον οὐδένα·", "r": "от себя. — Походит. — Так что же? если нечто от чего-нибудь отлично, то не от отличного ли будет отлично? — Необходимо. — Поэтому, что — не одно, всё такое не отлично ли от одного, равно как одно — от того, что̀ не одно? — Ка̀к не отлично. — Стало быть одно будет отлично от инаго. — Отлично. — Смотри же, само тожественное и отличное не противны ли между собою? — Ка̀к не противны. — Так захочет ли то же быть в отличном, или отличное — в том же? — Не захочет. — Следовательно, если отличное никогда не бывает в том же, то нет ничего из существенностей, в чём отличное пребывало бы когда-нибудь; ибо если бы оно было в чём-нибудь"}, "146e": {"g": "εἰ γὰρ ὁντινοῦν εἴη ἔν τῳ, ἐκεῖνον ἂν τὸν χρόνον ἐν ταὐτῷ εἴη τὸ ἕτερον. οὐχ οὕτως; οὕτως. ἐπειδὴ δʼ οὐδέποτε ἐν τῷ αὐτῷ ἐστιν, οὐδέποτε ἔν τινι τῶν ὄντων ἂν εἴη τὸ ἕτερον. ἀληθῆ. οὔτʼ ἄρα ἐν τοῖς μὴ ἓν οὔτε ἐν τῷ ἑνὶ ἐνείη ἂν τὸ ἕτερον. οὐ γὰρ οὖν. οὐκ ἄρα τῷ ἑτέρῳ γʼ ἂν εἴη τὸ ἓν τῶν μὴ ἓν οὐδὲ τὰ μὴ ἓν τοῦ ἑνὸς ἕτερα. οὐ γάρ. οὐδὲ μὴν ἑαυτοῖς γε ἕτερʼ ἂν εἴη ἀλλήλων, μὴ μετέχοντα", "r": "когда-нибудь, то тем временем отличное было бы в том же. Не так ли? — Так. — А как оно никогда не бывает в том же, то и ни в чём существенном никогда не может быть отличного. — Правда. — Стало быть, отличное не находится ни в том, что̀ не одно, ни в одном. — Уж конечно, нет. — Поэтому не чрез отличное-то будет отлично одно — от того, что̀ не одно, и то, что̀ не одно, — от одного. — Конечно, нет. — Но, не приобщаясь отличного, они даже и чрез самих-то себя взаимно не будут отличны. — Ка̀к быть. — Если же они не отличны ни"}, "147a": {"g": "τοῦ ἑτέρου. πῶς γάρ; εἰ δὲ μήτε αὑτοῖς ἕτερά ἐστι μήτε τῷ ἑτέρῳ, οὐ πάντῃ ἤδη ἂν ἐκφεύγοι τὸ μὴ ἕτερα εἶναι ἀλλήλων; ἐκφεύγοι. ἀλλὰ μὴν οὐδὲ τοῦ ἑνός γε μετέχει τὰ μὴ ἕν· οὐ γὰρ ἂν μὴ ἓν ἦν, ἀλλά πῃ ἂν ἓν ἦν. ἀληθῆ. οὐδʼ ἂν ἀριθμὸς εἴη ἄρα τὰ μὴ ἕν· οὐδὲ γὰρ ἂν οὕτω μὴ ἓν ἦν παντάπασιν, ἀριθμόν γε ἔχοντα. οὐ γὰρ οὖν. τί δέ; τὰ μὴ ἓν τοῦ ἑνὸς ἆρα μόριά ἐστιν; ἢ κἂν οὕτω μετεῖχε τοῦ ἑνὸς τὰ μὴ ἕν; μετεῖχεν. εἰ ἄρα πάντῃ τὸ μὲν ἕν ἐστι,", "r": "чрез себя, ни чрез отличное, то не совершенно ли ускользнет всякое взаимное различие между ними? — Ускользнет. — Но ведь то, что̀ не одно, не причастно и одного-то; ибо иначе было бы оно не не одно, а некоторым образом одно. — Правда. — То, что не одно, не было бы также и числом; потому что, имея число-то, оно та̀к вовсе и не было бы не одним. — Уж конечно, нет. — Что же? то, что не одно, не представляет ли собою части одного? Или та̀к не одно было бы причастно одного? — Было бы причастно. — Следовательно, если всячески то̀ есть одно, а это — не одно, то одно не будет ни частью того, что не"}, "147b": {"g": "τὰ δὲ μὴ ἕν, οὔτʼ ἂν μόριον τῶν μὴ ἓν τὸ ἓν εἴη οὔτε ὅλον ὡς μορίων· οὔτε αὖ τὰ μὴ ἓν τοῦ ἑνὸς μόρια, οὔτε ὅλα ὡς μορίῳ τῷ ἑνί. οὐ γάρ. ἀλλὰ μὴν ἔφαμεν τὰ μήτε μόρια μήτε ὅλα μήτε ἕτερα ἀλλήλων ταὐτὰ ἔσεσθαι ἀλλήλοις. ἔφαμεν γάρ. φῶμεν ἄρα καὶ τὸ ἓν πρὸς τὰ μὴ ἓν οὕτως ἔχον τὸ αὐτὸ εἶναι αὐτοῖς; φῶμεν. τὸ ἓν ἄρα, ὡς ἔοικεν, ἕτερόν τε τῶν ἄλλων ἐστὶν καὶ ἑαυτοῦ καὶ ταὐτὸν ἐκείνοις τε καὶ ἑαυτῷ. κινδυνεύει φαίνεσθαι ἐκ γε τοῦ λόγου.", "r": "одно, ни целым из тех частей; и наоборот, то, что не одно, не представится ни частями одного, ни целым по отношению к одному, как части. — Конечно, нет. — Но мы сказали, что вещи, если они ни части, ни целое, ни взаимно различны, будут между собою тем же. — Да, сказали. — Скажем ли, стало быть, что и одно, коли оно та̀к относится к тому, что не одно, есть то же с ним? — Скажем. — Стало быть, одно, как видно, отлично и от иных вещей, и от себя, равно как тожественно и с ними, и с собою. — По ходу-то рассуждения, должно быть,"}, "147c": {"g": "ἆρʼ οὖν καὶ ὅμοιόν τε καὶ ἀνόμοιον ἑαυτῷ τε καὶ τοῖς ἄλλοις; ἴσως. ἐπειδὴ γοῦν ἕτερον τῶν ἄλλων ἐφάνη, καὶ τἆλλά που ἕτερα ἂν ἐκείνου εἴη. τί μήν; οὐκοῦν οὕτως ἕτερον τῶν ἄλλων, ὥσπερ καὶ τἆλλα ἐκείνου, καὶ οὔτε μᾶλλον οὔτε ἧττον; τί γὰρ ἄν; εἰ ἄρα μήτε μᾶλλον μήτε ἧττον, ὁμοίως. ναί. οὐκοῦν ᾗ ἕτερον εἶναι πέπονθεν τῶν ἄλλων καὶ τἆλλα ἐκείνου ὡσαύτως, ταύτῃ ταὐτὸν ἂν πεπονθότα εἶεν τό τε ἓν τοῖς ἄλλοις καὶ τἆλλα τῷ ἑνί.", "r": "так. — Так не будет ли оно и подобно, и не подобно себе и иным вещам? — Может быть. — Если ведь явилось оно отличным от иных вещей, то и иные вещи, вероятно, будут отличны от него. — Как же. — И не так же ли оно отлично от иных вещей, как иные вещи отличны от него, — ни больше, ни меньше? — Почему бы нет. — Если же ни больше, ни меньше, то одинаково. — Да. — Отсюда, насколько получило оно свойство быть отличным от иных вещей, а иные вещи, равномерно, — от него; настолько получили свойство и быть тожественными — одно с иными вещами, и иные вещи с одним. — Как ты говоришь? — Вот как: каждое из имен не"}, "147d": {"g": "πῶς λέγεις; ὧδε· ἕκαστον τῶν ὀνομάτων οὐκ ἐπί τινι καλεῖς; ἔγωγε. τί οὖν; τὸ αὐτὸ ὄνομα εἴποις ἂν πλεονάκις ἢ ἅπαξ; ἔγωγε. πότερον οὖν ἐὰν μὲν ἅπαξ εἴπῃς, ἐκεῖνο προσαγορεύεις οὗπέρ ἐστι τοὔνομα, ἐὰν δὲ πολλάκις, οὐκ ἐκεῖνο; ἢ ἐάντε ἅπαξ ἐάντε πολλάκις ταὐτὸν ὄνομα φθέγξῃ, πολλὴ ἀνάγκη σε ταὐτὸν καὶ λέγειν ἀεί; τί μήν; οὐκοῦν καὶ τὸ ἕτερον ὄνομά ἐστιν ἐπί τινι; πάνυ γε.", "r": "прилагаешь ли ты к чему-нибудь? — Прилагаю. — Так что же? то же самое имя не произносишь ли и много раз, а не однажды? — Произношу. — Но если, выговаривая его однажды, ты называешь то, чего оно имя, то, выговаривая часто, — разве уже не то? Или, однажды ли, часто ли произносишь то самое имя, — крайне необходимо тебе всегда то̀ же самое и выражать? — Как же. — Не придается ли чему-нибудь и отличное в значении имени? — Конечно. — Стало быть, когда ты"}, "147e": {"g": "ὅταν ἄρα αὐτὸ φθέγγῃ, ἐάντε ἅπαξ ἐάντε πολλάκις, οὐκ ἐπʼ ἄλλῳ οὐδὲ ἄλλο τι ὀνομάζεις ἢ ἐκεῖνο οὗπερ ἦν ὄνομα. ἀνάγκη. ὅταν δὴ λέγωμεν ὅτι ἕτερον μὲν τἆλλα τοῦ ἑνός, ἕτερον δὲ τὸ ἓν τῶν ἄλλων, δὶς τὸ ἕτερον εἰπόντες οὐδέν τι μᾶλλον ἐπʼ ἄλλῃ, ἀλλʼ ἐπʼ ἐκείνῃ τῇ φύσει αὐτὸ ἀεὶ λέγομεν ἧσπερ ἦν τοὔνομα. πάνυ μὲν οὖν. ἧι ἄρα ἕτερον τῶν", "r": "произносишь его, — однажды ли, часто ли, — не к иному чему прилагаешь и не иное что называешь, как то, чему оно было именем. — Необходимо. — Поэтому, когда мы говорим, что иное отлично от одного и что одно отлично от инаго, тогда слово отлично, хоть и произносим его дважды, прилагаем ничуть не к иной, а всё к той же природе, которой оно было именем. — Конечно, так. — Стало быть, поскольку одно отлично от иных вещей и иные вещи отличны от одного, постольку одно, в силу именно того же свойства"}, "148a": {"g": "ἄλλων τὸ ἓν καὶ τἆλλα τοῦ ἑνός, κατʼ αὐτὸ τὸ ἕτερον πεπονθέναι οὐκ ἄλλο ἀλλὰ τὸ αὐτὸ ἂν πεπονθὸς εἴη τὸ ἓν τοῖς ἄλλοις· τὸ δέ που ταὐτὸν πεπονθὸς ὅμοιον· οὐχί; ναί. ἧι δὴ τὸ ἓν ἕτερον τῶν ἄλλων πέπονθεν εἶναι, κατʼ αὐτὸ τοῦτο ἅπαν ἅπασιν ὅμοιον ἂν εἴη· ἅπαν γὰρ ἁπάντων ἕτερόν ἐστιν. ἔοικεν. ἀλλὰ μὴν τό γε ὅμοιον τῷ ἀνομοίῳ ἐναντίον. ναί. οὐκοῦν καὶ τὸ ἕτερον τῷ ταὐτῷ. καὶ τοῦτο. ἀλλὰ μὴν καὶ τοῦτό γʼ ἐφάνη, ὡς ἄρα τὸ ἓν τοῖς", "r": "отличия, испытывает не иное, но то же самое, что и другие вещи. Но что̀ испытывает то самое, то подобно. Не так ли? — Да. — И поскольку одному свойственно быть отличным от иных вещей, постольку же каждое каждому подобно; потому что каждое от каждого отлично. — Походит. — Но подобное-то противно не подобному. — Да. — Равно и отличное — тожественному. — И это. — Да и то-то однакож оказалось, что одно тожественно с иными вещами. — Конечно, оказалось. — Но быть тем же с иными вещами, — это-то"}, "148b": {"g": "ἄλλοις ταὐτόν. ἐφάνη γάρ. τοὐναντίον δέ γε πάθος ἐστὶ τὸ εἶναι ταὐτὸν τοῖς ἄλλοις τῷ ἕτερον εἶναι τῶν ἄλλων. πάνυ γε. ἧι γε μὴν ἕτερον, ὅμοιον ἐφάνη. ναί. ἧι ἄρα ταὐτόν, ἀνόμοιον ἔσται κατὰ τοὐναντίον πάθος τῷ ὁμοιοῦντι πάθει. ὡμοίου δέ που τὸ ἕτερον; ναί. ἀνομοιώσει ἄρα τὸ ταὐτόν, ἢ οὐκ ἐναντίον ἔσται τῷ ἑτέρῳ.", "r": "свойство противно другому — быть отличным от иных вещей. — Конечно. — А поколику отлично-то, оно оказалось подобным. — Да. — Стало быть, при тожестве оно будет не подобно, в силу свойства, противного свойству уподобляющему; — ведь для уподобления служило отличие. — Да. — Значит, тожество сделает его не подобным; иначе не будет противно отличному. — Походит. — Стало быть, одно будет подобно и не подобно прочим вещам: поколику"}, "148c": {"g": "ἔοικεν. ὅμοιον ἄρα καὶ ἀνόμοιον ἔσται τὸ ἓν τοῖς ἄλλοις, ᾗ μὲν ἕτερον, ὅμοιον, ᾗ δὲ ταὐτόν, ἀνόμοιον. ἔχει γὰρ οὖν δή, ὡς ἔοικεν, καὶ τοιοῦτον λόγον. καὶ γὰρ τόνδε ἔχει. τίνα; ἧι ταὐτὸν πέπονθε, μὴ ἀλλοῖον πεπονθέναι, μὴ ἀλλοῖον δὲ πεπονθὸς μὴ ἀνόμοιον, μὴ ἀνόμοιον δὲ ὅμοιον εἶναι· ᾗ δʼ ἄλλο πέπονθεν, ἀλλοῖον, ἀλλοῖον δὲ ὂν ἀνόμοιον εἶναι. ἀληθῆ λέγεις. ταὐτόν τε ἄρα ὂν τὸ ἓν τοῖς ἄλλοις καὶ ὅτι ἕτερόν ἐστι, κατʼ ἀμφότερα καὶ κατὰ ἑκάτερον, ὅμοιόν", "r": "отлично, — подобно, поколику тожественно, — не подобно. — Да, будет, как видно, и такое отношение. — Притом и вот какое. — Какое? — Поколику испытало оно то же, испытало не иное; испытав не иное, оно не неподобно, а став не неподобным, уподобилось; но если испытало иное, оно становится иным, а будучи иным, оно не подобно. — Ты правду говоришь. — Стало быть, одно, будучи тожественно иным вещам и отлично от них, как по обоим свойствам, так и по каждому из них порознь, будет подобно и не подобно иным вещам. — Конечно."}, "148d": {"g": "τε ἂν εἴη καὶ ἀνόμοιον τοῖς ἄλλοις. πάνυ γε. οὐκοῦν καὶ ἑαυτῷ ὡσαύτως, ἐπείπερ ἕτερόν τε ἑαυτοῦ καὶ ταὐτὸν ἑαυτῷ ἐφάνη, κατʼ ἀμφότερα καὶ κατὰ ἑκάτερον ὅμοιόν τε καὶ ἀνόμοιον φανήσεται; ἀνάγκη. τί δὲ δή; περὶ τοῦ ἅπτεσθαι τὸ ἓν αὑτοῦ καὶ τῶν ἄλλων καὶ τοῦ μὴ ἅπτεσθαι πέρι πῶς ἔχει, σκόπει. σκοπῶ. αὐτὸ γάρ που ἐν ἑαυτῷ ὅλῳ τὸ ἓν ἐφάνη ὄν. ὀρθῶς. οὐκοῦν καὶ ἐν τοῖς ἄλλοις τὸ ἕν; ναί. ἧι μὲν ἄρα ἐν τοῖς ἄλλοις,", "r": "— Поэтому и себе таким же образом, — так как оказалось оно и отличным от себя, и тожественным с собою, — по обоим свойствам и по каждому порознь, окажется подобным и не подобным. — Необходимо. — Что же теперь относительно того, касается ли одно себя и иных вещей, или не касается, — как это будет? Наблюдай. — Наблюдаю. — Ведь одно оказалось существующим в себе, как в целом. — Правильно. — Но одно не находится ли и в иных вещах? — Да. — Стало быть, поскольку находится оно в иных вещах, постольку касается их; а поскольку"}, "148e": {"g": "τῶν ἄλλων ἅπτοιτο ἄν· ᾗ δὲ αὐτὸ ἐν ἑαυτῷ, τῶν μὲν ἄλλων ἀπείργοιτο ἅπτεσθαι, αὐτὸ δὲ αὑτοῦ ἅπτοιτο ἂν ἐν ἑαυτῷ ὄν. φαίνεται. οὕτω μὲν δὴ ἅπτοιτο ἂν τὸ ἓν αὑτοῦ τε καὶ τῶν ἄλλων. ἅπτοιτο. τί δὲ τῇδε; ἆρʼ οὐ πᾶν τὸ μέλλον ἅψεσθαί τινος ἐφεξῆς δεῖ κεῖσθαι ἐκείνῳ οὗ μέλλει ἅπτεσθαι, ταύτην τὴν ἕδραν κατέχον ἣ ἂν μετʼ ἐκείνην ᾖ ἕδρα ᾗ ἂν κέηται, ἅπτεται; ἀνάγκη. καὶ τὸ ἓν ἄρα εἰ μέλλει αὐτὸ αὑτοῦ ἅψεσθαι, ἐφεξῆς δεῖ εὐθὺς μετὰ ἑαυτὸ κεῖσθαι, τὴν ἐχομένην χώραν κατέχον ἐκείνης ἐν ᾗ αὐτό ἐστιν. δεῖ γὰρ οὖν. οὐκοῦν δύο μὲν ὂν τὸ ἓν ποιήσειεν", "r": "заключается в себе, постольку встречает препятствие касаться иных вещей и, будучи в себе, касается само себя. — Явно. — Таким образом одно касается и себя, и иных вещей. — Касается. — Что же тут-то? всё, имеющее коснуться чего-нибудь, не должно ли лечь рядом близ того, чего имеет коснуться, занимая место, смежное с другим, в котором если бы лежало, касалось бы его? — Необходимо. — Стало быть, одно, если оно имеет коснуться само себя, должно лечь как раз рядом за собою и занять место, смежное с тем, в котором само находится. — Конечно, должно. — И если бы одно было два, то сделало бы это, и в одно время находилось бы в"}, "149a": {"g": "ἂν ταῦτα καὶ ἐν δυοῖν χώραιν ἅμα γένοιτο· ἕως δʼ ἂν ᾖ ἕν, οὐκ ἐθελήσει; οὐ γὰρ οὖν. ἡ αὐτὴ ἄρα ἀνάγκη τῷ ἑνὶ μήτε δύο εἶναι μήτε ἅπτεσθαι αὐτῷ αὑτοῦ. ἡ αὐτή. ἀλλʼ οὐδὲ μὴν τῶν ἄλλων ἅψεται. τί δή; ὅτι, φαμέν, τὸ μέλλον ἅψεσθαι χωρὶς ὂν ἐφεξῆς δεῖ ἐκείνῳ εἶναι οὗ μέλλει ἅψεσθαι, τρίτον δὲ αὐτῶν ἐν μέσῳ μηδὲν εἶναι. ἀληθῆ. δύο ἄρα δεῖ τὸ ὀλίγιστον εἶναι, εἰ μέλλει ἅψις εἶναι. δεῖ. ἐὰν δὲ τοῖν δυοῖν ὅροιν τρίτον προσγένηται ἑξῆς, αὐτὰ", "r": "двух местах; но пока оно одно, ведь не захочет? — Конечно, не захочет. — Стало быть, та же необходимость требует, чтобы одно и не было двумя, и не касалось само себя. — Та же. — Да одно не будет касаться и иных вещей. — Почему так? — Потому, что имеющее коснуться, представляя нечто особое, должно, говорим, следовать за тем, чего имеет коснуться, так чтобы третьего между ними ничего не было. — Правда. — Следовательно, должно быть по крайней мере два, если имеет быть прикосновение. — Должно. — Когда же к двум присоединится потом третье, вещей будет"}, "149b": {"g": "μὲν τρία ἔσται, αἱ δὲ ἅψεις δύο. ναί. καὶ οὕτω δὴ ἀεὶ ἑνὸς προσγιγνομένου μία καὶ ἅψις προσγίγνεται, καὶ συμβαίνει τὰς ἅψεις τοῦ πλήθους τῶν ἀριθμῶν μιᾷ ἐλάττους εἶναι. ᾧ γὰρ τὰ πρῶτα δύο ἐπλεονέκτησεν τῶν ἅψεων εἰς τὸ πλείω εἶναι τὸν ἀριθμὸν ἢ τὰς ἅψεις, τῷ ἴσῳ τούτῳ καὶ ὁ ἔπειτα ἀριθμὸς πᾶς πασῶν τῶν ἅψεων πλεονεκτεῖ· ἤδη", "r": "три, а прикосновений два. — Да. — И таким образом, с присоединением одного члена, всегда прибавляется и одно прикосновение, и выходит, что прикосновений противу числа членов будет одним меньше; ибо насколько два первые члена превысили прикосновения, будучи числом больше последних, настолько и всё дальнейшее число их возвышается над всеми прикосновениями; так как далее к тому числу"}, "149c": {"g": "γὰρ τὸ λοιπὸν ἅμα ἕν τε τῷ ἀριθμῷ προσγίγνεται καὶ μία ἅψις ταῖς ἅψεσιν. ὀρθῶς. ὅσα ἄρα ἐστὶν τὰ ὄντα τὸν ἀριθμόν, ἀεὶ μιᾷ αἱ ἅψεις ἐλάττους εἰσὶν αὐτῶν. ἀληθῆ. εἰ δέ γε ἓν μόνον ἐστίν, δυὰς δὲ μὴ ἔστιν, ἅψις οὐκ ἂν εἴη. πῶς γάρ; οὔκουν, φαμέν, τὰ ἄλλα τοῦ ἑνὸς οὔτε ἕν ἐστιν οὔτε μετέχει αὐτοῦ, εἴπερ ἄλλα ἐστίν. οὐ γάρ. οὐκ ἄρα ἔνεστιν ἀριθμὸς ἐν τοῖς ἄλλοις, ἑνὸς μὴ ἐνόντος ἐν αὐτοῖς. πῶς γάρ; οὔτʼ ἄρα ἕν ἐστι τὰ ἄλλα οὔτε δύο οὔτε", "r": "их прибавляется по единице и к прикосновениям вместе по одному прикосновению. — Правильно. — Итак, сколько б ни было существенностей, — прикосновений всегда меньше их единицею. — Правда. — Но если есть только одно-то, а двоицы нет, — прикосновение будет невозможно. — Конечно, невозможно. — Но иное, в рассуждении одного, говорим, и не есть одно, и не причастно его, как скоро оно есть иное. — Конечно, нет. — Если же в ином нет одного, то в ином, стало быть, нет и числа. — Ка̀к быть. — Следовательно, иное не есть ни одно, ни два, и не имеет никакого"}, "149d": {"g": "ἄλλου ἀριθμοῦ ἔχοντα ὄνομα οὐδέν. οὔ. τὸ ἓν ἄρα μόνον ἐστὶν ἕν, καὶ δυὰς οὐκ ἂν εἴη. οὐ φαίνεται. ἅψις ἄρα οὐκ ἔστιν δυοῖν μὴ ὄντοιν. οὐκ ἔστιν. οὔτʼ ἄρα τὸ ἓν τῶν ἄλλων ἅπτεται οὔτε τὰ ἄλλα τοῦ ἑνός, ἐπείπερ ἅψις οὐκ ἔστιν. οὐ γὰρ οὖν. οὕτω δὴ κατὰ πάντα ταῦτα τὸ ἓν τῶν τε ἄλλων καὶ ἑαυτοῦ ἅπτεταί τε καὶ οὐχ ἅπτεται. ἔοικεν. ἆρʼ οὖν καὶ ἴσον ἐστὶ καὶ ἄνισον αὑτῷ τε καὶ τοῖς ἄλλοις; πῶς; εἰ μεῖζον εἴη τὸ ἓν ἢ τἆλλα ἢ ἔλαττον,", "r": "имени, принадлежащего другому числу. — Не имеет. — Стало быть, только одно есть одно, а двоицы не будет. — Явно, что не будет. — А когда нет двоицы, — нет и прикосновения. — Нет. — Если же нет прикосновения, то ни одно не касается инаго, ни иное — одного. — Конечно, не касается. — Так по всему этому одно и касается инаго и себя, и не касается. — Походит. — Не есть ли оно также равно и не равно как себе, так и иному? — Как? — Если бы одно было больше или меньше, чем иное, либо,"}, "149e": {"g": "ἢ αὖ τὰ ἄλλα τοῦ ἑνὸς μείζω ἢ ἐλάττω, ἆρα οὐκ ἂν τῷ μὲν ἓν εἶναι τὸ ἓν καὶ τἆλλα ἄλλα τοῦ ἑνὸς οὔτε τι μείζω οὔτε τι ἐλάττω ἂν εἴη ἀλλήλων αὐταῖς γε ταύταις ταῖς οὐσίαις; ἀλλʼ εἰ μὲν πρὸς τῷ τοιαῦτα εἶναι ἑκάτερα ἰσότητα ἔχοιεν, ἴσα ἂν εἴη πρὸς ἄλληλα· εἰ δὲ τὰ μὲν μέγεθος, τὸ δὲ σμικρότητα, ἢ καὶ μέγεθος μὲν τὸ ἕν, σμικρότητα δὲ τἆλλα, ὁποτέρῳ μὲν τῷ εἴδει μέγεθος προσείη, μεῖζον ἂν εἴη, ᾧ δὲ σμικρότης, ἔλαττον; ἀνάγκη. οὐκοῦν ἐστόν γέ τινε τούτω εἴδη, τό τε μέγεθος καὶ ἡ σμικρότης; οὐ γὰρ ἄν που μὴ ὄντε γε ἐναντίω τε ἀλλήλοιν εἴτην καὶ ἐν τοῖς", "r": "опять, иное больше или меньше, чем одно, то, — не правда ли, — не тем, что одно есть одно, а иное — иное по отношению к одному, — не этими-то самыми сущностями были бы они больше или меньше друг друга; но когда бы, кроме того, что оба эти члена таковы, присоединилось к ним равенство, они были бы между собою равны, а если бы к тому — великость, к этому — малость, — например, к одному великость, к иному малость, — то к которому виду подошла бы великость, тот был бы больше, а к которому — малость, тот меньше? — Необходимо. — Значит, такие какие-то виды — великость и малость — действительно есть? Потому что, если бы не было-то их, они, вероятно, не обнаруживали бы взаимной противности и не находились бы в сущем. — Ка̀к находиться бы. — Итак, когда малость находится в одном, —"}, "150a": {"g": "οὖσιν ἐγγιγνοίσθην. πῶς γὰρ ἄν; εἰ ἄρα ἐν τῷ ἑνὶ σμικρότης ἐγγίγνεται, ἤτοι ἐν ὅλῳ ἂν ἢ ἐν μέρει αὐτοῦ ἐνείη. ἀνάγκη. τί δʼ εἰ ἐν ὅλῳ ἐγγίγνοιτο; οὐχὶ ἢ ἐξ ἴσου ἂν τῷ ἑνὶ διʼ ὅλου αὐτοῦ τεταμένη εἴη ἢ περιέχουσα αὐτό; δῆλον δή. ἆρʼ οὖν οὐκ ἐξ ἴσου μὲν οὖσα ἡ σμικρότης τῷ ἑνὶ ἴση ἂν αὐτῷ εἴη, περιέχουσα δὲ μείζων; πῶς δʼ οὔ; δυνατὸν οὖν σμικρότητα ἴσην τῳ εἶναι ἢ μείζω τινός, καὶ πράττειν τὰ μεγέθους τε καὶ ἰσότητος, ἀλλὰ", "r": "находится она или в нём целом, или в его части. — Необходимо. — Что же? если будет находиться в целом, то не так ли, что либо распространится, вровень с одним, по всей его целости, либо обоймет его? — Явно. — Но малость, будучи вровень с одним, не будет ли равна ему, а объемля его, не будет ли больше? — Ка̀к не будет. — А возможно ли, чтобы малость была равна чему-нибудь, или больше чего-нибудь, и производила дела великости и равенства, а не свои? — Невозможно. — Стало быть, в целом"}, "150b": {"g": "μὴ τὰ ἑαυτῆς; ἀδύνατον. ἐν μὲν ὅλῳ ἄρα τῷ ἑνὶ οὐκ ἂν εἴη σμικρότης, ἀλλʼ εἴπερ, ἐν μέρει. ναί. οὐδέ γε ἐν παντὶ αὖ τῷ μέρει· εἰ δὲ μή, ταὐτὰ ποιήσει ἅπερ πρὸς τὸ ὅλον· ἴση ἔσται ἢ μείζων τοῦ μέρους ἐν ᾧ ἂν ἀεὶ ἐνῇ. ἀνάγκη. οὐδενί ποτε ἄρα ἐνέσται τῶν ὄντων σμικρότης, μήτʼ ἐν μέρει μήτʼ ἐν ὅλῳ ἐγγιγνομένη· οὐδέ τι ἔσται σμικρὸν πλὴν αὐτῆς σμικρότητος. οὐκ ἔοικεν. οὐδʼ ἄρα μέγεθος ἐνέσται ἐν αὐτῷ· μεῖζον γὰρ ἄν τι εἴη ἄλλο καὶ", "r": "одном не будет малости, а разве в части. — Да. — Но даже и в части-то не будет; а иначе она сделает то же, что сделала в отношении к целому, то есть, будет или равна, или больше той части, в которой всякий раз находится. — Необходимо. — Следовательно, малость, не находясь ни в части, ни в целом, не будет содержаться ни в чём из существенностей; так что не будет ничего малого, кроме самой малости. — Походит, что нет. — Стало быть, не будет в нём и великости: ибо тогда было бы нечто"}, "150c": {"g": "πλὴν αὐτοῦ μεγέθους, ἐκεῖνο ἐν ᾧ τὸ μέγεθος ἐνείη, καὶ ταῦτα σμικροῦ αὐτῷ οὐκ ὄντος, οὗ ἀνάγκη ὑπερέχειν, ἐάνπερ ᾖ μέγα· τοῦτο δὲ ἀδύνατον, ἐπειδὴ σμικρότης οὐδαμοῦ ἔνι. ἀληθῆ. ἀλλὰ μὴν αὐτὸ μέγεθος οὐκ ἄλλου μεῖζον ἢ αὐτῆς σμικρότητος, οὐδὲ σμικρότης ἄλλου ἔλαττον ἢ αὐτοῦ μεγέθους. οὐ γάρ. οὔτε ἄρα τὰ ἄλλα μείζω τοῦ ἑνὸς οὐδὲ ἐλάττω, μήτε μέγεθος μήτε σμικρότητα ἔχοντα, οὔτε", "r": "иное большее, кроме самой великости, — то, в чём содержалась бы великость, и притом — при отсутствии само̀й малости, которую то, если оно велико, необходимо превышало бы; но это невозможно, так как малость не находится ни в чём. — Правда. — Между тем сама великость не инаго чего больше, как самой малости, и малость не инаго чего меньше, как самой великости. — Конечно, не инаго. — Стало быть, иное, не имея ни великости, ни малости, и не больше, и не меньше одного; да и сами эти (идеи) заключают в себе"}, "150d": {"g": "αὐτὼ τούτω πρὸς τὸ ἓν ἔχετον τὴν δύναμιν τὴν τοῦ ὑπερέχειν καὶ ὑπερέχεσθαι, ἀλλὰ πρὸς ἀλλήλω, οὔτε αὖ τὸ ἓν τούτοιν οὐδὲ τῶν ἄλλων μεῖζον ἂν οὐδʼ ἔλαττον εἴη, μήτε μέγεθος μήτε σμικρότητα ἔχον. οὔκουν φαίνεταί γε. ἆρʼ οὖν, εἰ μήτε μεῖζον μήτε ἔλαττον τὸ ἓν τῶν ἄλλων, ἀνάγκη αὐτὸ ἐκείνων μήτε ὑπερέχειν μήτε ὑπερέχεσθαι; ἀνάγκη. οὐκοῦν τό γε μήτε ὑπερέχον μήτε ὑπερεχόμενον πολλὴ ἀνάγκη ἐξ ἴσου εἶναι, ἐξ ἴσου δὲ ὂν ἴσον εἶναι. πῶς γὰρ", "r": "силу превышать и быть превышаемыми не в отношении к одному, а в отношении лишь друг к другу; и одно опять, не имея ни великости, ни малости, не будет ни больше, ни меньше как их самих, так и инаго. — Поэтому-то явно. — Если же одно и не больше, и не меньше инаго, то не необходимо ли, чтобы оно и не превышало последнего, и не было им превышаемо? — Необходимо. — А что̀ и не превышает-то, и не бывает превышаемо, тому крайне необходимо быть вровень; будучи же вровень, быть равным."}, "150e": {"g": "οὔ; καὶ μὴν καὶ αὐτό γε τὸ ἓν πρὸς ἑαυτὸ οὕτως ἂν ἔχοι· μήτε μέγεθος ἐν ἑαυτῷ μήτε σμικρότητα ἔχον οὔτʼ ἂν ὑπερέχοιτο οὔτʼ ἂν ὑπερέχοι ἑαυτοῦ, ἀλλʼ ἐξ ἴσου ὂν ἴσον ἂν εἴη ἑαυτῷ. πάνυ μὲν οὖν. τὸ ἓν ἄρα ἑαυτῷ τε καὶ τοῖς ἄλλοις ἴσον ἂν εἴη. φαίνεται. καὶ μὴν αὐτό γε ἐν ἑαυτῷ ὂν καὶ περὶ ἑαυτὸ ἂν εἴη ἔξωθεν, καὶ περιέχον μὲν μεῖζον", "r": "— Ка̀к не быть. — Но ведь таково будет и само-то одно в отношении к себе: не имея в себе ни великости, ни малости, оно не может ни превышать себя, ни превышаться собою, но, будучи вровень, будет равно себе. — Конечно, так. — Стало быть, одно будет равно себе и иному. — Явно. — Однакож, будучи в себе-то, оно будет и около себя, извне: как объемлющее, оно больше себя, а как объемлемое, меньше. Таким образом одно будет больше"}, "151a": {"g": "ἂν ἑαυτοῦ εἴη, περιεχόμενον δὲ ἔλαττον, καὶ οὕτω μεῖζον ἂν καὶ ἔλαττον εἴη αὐτὸ ἑαυτοῦ τὸ ἕν. εἴη γὰρ ἄν. οὐκοῦν καὶ τόδε ἀνάγκη, μηδὲν εἶναι ἐκτὸς τοῦ ἑνός τε καὶ τῶν ἄλλων; πῶς γὰρ οὔ; ἀλλὰ μὴν καὶ εἶναί που δεῖ τό γε ὂν ἀεί. ναί. οὐκοῦν τό γε ἔν τῳ ὂν ἐν μείζονι ἔσται ἔλαττον ὄν; οὐ γὰρ ἂν ἄλλως ἕτερον ἐν ἑτέρῳ εἴη. οὐ γάρ. ἐπειδὴ δὲ οὐδὲν ἕτερον ἔστι χωρὶς τῶν ἄλλων καὶ τοῦ ἑνός, δεῖ δὲ αὐτὰ ἔν τῳ εἶναι, οὐκ ἀνάγκη ἤδη ἐν ἀλλήλοις εἶναι, τά τε ἄλλα ἐν τῷ ἑνὶ καὶ τὸ ἓν ἐν τοῖς ἄλλοις,", "r": "и меньше само себя. — Конечно, будет. — Впрочем и то необходимо, что вне одного и инаго нет ничего. — Как не необходимо. — И то, что всегда сущее-то должно быть где-нибудь. — Да. — Но что находится в чём-нибудь, то̀ не будет ли содержаться в большем, как меньшее? Ведь одному находиться в другом возможно не иначе. — Конечно. — А так как ничто другое не существует особо от одного и инаго, эти же должны содержаться в чём-нибудь; то не необходимо ли уже быть им взаимно одному в другом, — иному в одном, а одному в ином, или не быть нигде? — Явно. — Стало быть, если одно находится"}, "151b": {"g": "ἢ μηδαμοῦ εἶναι; φαίνεται. ὅτι μὲν ἄρα τὸ ἓν ἐν τοῖς ἄλλοις ἔνεστι, μείζω ἂν εἴη τὰ ἄλλα τοῦ ἑνός, περιέχοντα αὐτό, τὸ δὲ ἓν ἔλαττον τῶν ἄλλων, περιεχόμενον· ὅτι δὲ τὰ ἄλλα ἐν τῷ ἑνί, τὸ ἓν τῶν ἄλλων κατὰ τὸν αὐτὸν λόγον μεῖζον ἂν εἴη, τὰ δὲ ἄλλα τοῦ ἑνὸς ἐλάττω. ἔοικεν. τὸ ἓν ἄρα ἴσον τε καὶ μεῖζον καὶ ἔλαττόν ἐστιν αὐτό τε αὑτοῦ καὶ τῶν ἄλλων. φαίνεται. καὶ μὴν εἴπερ μεῖζον καὶ ἔλαττον καὶ ἴσον, ἴσων ἂν εἴη μέτρων καὶ πλειόνων καὶ ἐλαττόνων", "r": "ином, то иное, объемля одно, будет больше его, а одно, объемлемое иным, — меньше его. Когда же иное находится в одном, одно, по той же самой причине, будет больше инаго, а иное — меньше одного. — Походит. — Стало быть, одно и равно, и больше, и меньше — как само себя, так и инаго. — Явно. — Но если оно и больше, и меньше,"}, "151c": {"g": "αὑτῷ καὶ τοῖς ἄλλοις, ἐπειδὴ δὲ μέτρων, καὶ μερῶν. πῶς δʼ οὔ; ἴσων μὲν ἄρα μέτρων ὂν καὶ πλειόνων καὶ ἐλαττόνων, καὶ ἀριθμῷ ἔλαττον ἂν καὶ πλέον εἴη αὐτό τε αὑτοῦ καὶ τῶν ἄλλων καὶ ἴσον αὑτῷ τε καὶ τοῖς ἄλλοις κατὰ ταὐτά. πῶς; ὧνπερ μεῖζόν ἐστι, πλειόνων που καὶ μέτρων ἂν εἴη αὐτῶν, ὅσων δὲ μέτρων, καὶ μερῶν· καὶ ὧν ἔλαττον, ὡσαύτως· καὶ οἷς ἴσον, κατὰ ταὐτά. οὕτως. οὐκοῦν ἑαυτοῦ μεῖζον καὶ ἔλαττον ὂν καὶ ἴσον ἴσων ἂν εἴη", "r": "и равно себе и иному, то, конечно, на известное число равных, бо̀льших и меньших мер, — а как скоро мер, то и частей. — Как же иначе. — Будучи же равных, бо̀льших и меньших мер, оно и числом будет меньше и больше само себя и инаго, а потому будет также и равно как себе, так и иному. — Как? — Чего оно больше, в отношении к тому будет иметь больше и мер, — а сколько мер, столько и частей; таким же образом, если чего оно меньше; то же — если чему равно. — Так. — Поэтому, будучи больше и меньше"}, "151d": {"g": "μέτρων καὶ πλειόνων καὶ ἐλαττόνων αὑτῷ, ἐπειδὴ δὲ μέτρων, καὶ μερῶν; πῶς δʼ οὔ; ἴσων μὲν ἄρα μερῶν ὂν αὑτῷ ἴσον ἂν τὸ πλῆθος αὑτῷ εἴη, πλειόνων δὲ πλέον, ἐλαττόνων δὲ ἔλαττον τὸν ἀριθμὸν αὑτοῦ. φαίνεται. οὐκοῦν καὶ πρὸς τἆλλα ὡσαύτως ἕξει τὸ ἕν; ὅτι μὲν μεῖζον αὐτῶν φαίνεται, ἀνάγκη πλέον εἶναι καὶ τὸν ἀριθμὸν αὐτῶν· ὅτι δὲ σμικρότερον, ἔλαττον· ὅτι δὲ ἴσον μεγέθει, ἴσον καὶ τὸ πλῆθος εἶναι τοῖς ἄλλοις; ἀνάγκη. οὕτω δὴ αὖ, ὡς", "r": "себя, или равно себе, не будет ли оно бо̀льших, равных или меньших мер сравнительно с собою? а когда мер, то и частей? — Как не будет! — Стало быть, имея равное с собою число частей, оно будет, по количеству, равно себе, при большем же числе их, больше себя, а при меньшем — меньше. — Явно. — Не так ли одно будет относиться и к иному? Когда оно оказывается больше инаго, — не необходимо ли ему быть и числом больше инаго, а когда меньше, — меньше? Или как скоро оно равно иному по величине, не необходимо ли ему быть равным и по количеству? — Необходимо. — Таким образом одно будет"}, "151e": {"g": "ἔοικε, τὸ ἓν καὶ ἴσον καὶ πλέον καὶ ἔλαττον τὸν ἀριθμὸν αὐτό τε αὑτοῦ ἔσται καὶ τῶν ἄλλων. ἔσται. ἆρʼ οὖν καὶ χρόνου μετέχει τὸ ἕν, καὶ ἐστί τε καὶ γίγνεται νεώτερόν τε καὶ πρεσβύτερον αὐτό τε ἑαυτοῦ καὶ τῶν ἄλλων, καὶ οὔτε νεώτερον οὔτε πρεσβύτερον οὔτε ἑαυτοῦ οὔτε τῶν ἄλλων, χρόνου μετέχον; πῶς; εἶναι μέν που αὐτῷ ὑπάρχει, εἴπερ ἓν ἔστιν. ναί. τὸ δὲ εἶναι ἄλλο τί ἐστιν ἢ μέθεξις οὐσίας μετὰ χρόνου τοῦ παρόντος, ὥσπερ", "r": "опять, как видно, числом и равно, и больше, и меньше как само себя, так и инаго. — Будет. — Одно не причастно ли также и времени, так что есть и бывает моложе и старше как само себя, так и инаго, и не моложе и не старше ни себя, ни инаго, как причастное времени? — Как? — Если одно есть, то, вероятно, приходится ему быть. — Да. — А быт иное ли что выражает, как не причастность сущности времени настоящему, как было есть"}, "152a": {"g": "τὸ ἦν μετὰ τοῦ παρεληλυθότος καὶ αὖ τὸ ἔσται μετὰ τοῦ μέλλοντος οὐσίας ἐστὶ κοινωνία; ἔστι γάρ. μετέχει μὲν ἄρα χρόνου, εἴπερ καὶ τοῦ εἶναι. πάνυ γε. οὐκοῦν πορευομένου τοῦ χρόνου; ναί. ἀεὶ ἄρα πρεσβύτερον γίγνεται ἑαυτοῦ, εἴπερ προέρχεται κατὰ χρόνον. ἀνάγκη. ἆρʼ οὖν μεμνήμεθα ὅτι νεωτέρου γιγνομένου τὸ πρεσβύτερον πρεσβύτερον γίγνεται; μεμνήμεθα. οὐκοῦν ἐπειδὴ πρεσβύτερον ἑαυτοῦ γίγνεται τὸ ἕν, νεωτέρου ἂν γιγνομένου ἑαυτοῦ πρεσβύτερον", "r": "общение сущности с временем прошедшим, а будет — с временем будущим? — Конечно, это самое. — Значит, если оно причастно бытия, то причастно и времени. — Конечно. — Именно, времени идущего? — Да. — А когда идет оно вперед с временем, всегда бывает старше себя. — Необходимо. — Не помним ли мы, что старшее бывает старше, когда бывает младшее? — Помним. — Поэтому так как одно бывает старше себя, то не становится ли оно старшим в той мере, как бывает младшим? —"}, "152b": {"g": "γίγνοιτο; ἀνάγκη. γίγνεται μὲν δὴ νεώτερόν τε καὶ πρεσβύτερον αὑτοῦ οὕτω. ναί. ἔστι δὲ πρεσβύτερον ἆρʼ οὐχ ὅταν κατὰ τὸν νῦν χρόνον ᾖ γιγνόμενον τὸν μεταξὺ τοῦ ἦν τε καὶ ἔσται; οὐ γάρ που πορευόμενόν γε ἐκ τοῦ ποτὲ εἰς τὸ ἔπειτα ὑπερβήσεται τὸ νῦν. οὐ γάρ. ἆρʼ οὖν οὐκ ἐπίσχει τότε τοῦ γίγνεσθαι πρεσβύτερον, ἐπειδὰν", "r": "Необходимо. — Значит, таким образом бывает оно и моложе, и старше себя. — Да. — Не старше ли оно тогда, когда бывает в теперешнем времени, находящемся между было и будет? Ведь идя от некогда к потом, оно не минует теперь. — Конечно, нет. — И не удерживается ли оно тогда от стремления стать старше, как только попадает на"}, "152c": {"g": "τῷ νῦν ἐντύχῃ, καὶ οὐ γίγνεται, ἀλλʼ ἔστι τότʼ ἤδη πρεσβύτερον; προϊὸν γὰρ οὐκ ἄν ποτε ληφθείη ὑπὸ τοῦ νῦν. τὸ γὰρ προϊὸν οὕτως ἔχει ὡς ἀμφοτέρων ἐφάπτεσθαι, τοῦ τε νῦν καὶ τοῦ ἔπειτα, τοῦ μὲν νῦν ἀφιέμενον, τοῦ δʼ ἔπειτα ἐπιλαμβανόμενον, μεταξὺ ἀμφοτέρων γιγνόμενον, τοῦ τε ἔπειτα καὶ τοῦ νῦν. ἀληθῆ. εἰ δέ γε ἀνάγκη μὴ παρελθεῖν τὸ νῦν πᾶν τὸ γιγνόμενον, ἐπειδὰν κατὰ τοῦτο ᾖ,", "r": "теперь, так что не становится, а уже есть старше? Ведь в движении вперед его никогда не нагоняет теперь; ибо идущему вперед свойственно касаться обоих — и теперь, и потом, поколику теперь оставляет, а потом встречает, находясь между тем и другим — между потом и теперь. — Правда. — Но если в самом деле необходимость требует, чтобы ничто бывающее не миновало"}, "152d": {"g": "ἐπίσχει ἀεὶ τοῦ γίγνεσθαι καὶ ἔστι τότε τοῦτο ὅτι ἂν τύχῃ γιγνόμενον. φαίνεται. καὶ τὸ ἓν ἄρα, ὅταν πρεσβύτερον γιγνόμενον ἐντύχῃ τῷ νῦν, ἐπέσχεν τοῦ γίγνεσθαι καὶ ἔστι τότε πρεσβύτερον. πάνυ μὲν οὖν. οὐκοῦν οὗπερ ἐγίγνετο πρεσβύτερον, τούτου καὶ ἔστιν· ἐγίγνετο δὲ αὑτοῦ; ναί. ἔστι δὲ τὸ πρεσβύτερον νεωτέρου πρεσβύτερον; ἔστιν. καὶ νεώτερον ἄρα τότε αὑτοῦ ἐστι τὸ ἕν, ὅταν πρεσβύτερον γιγνόμενον ἐντύχῃ τῷ νῦν. ἀνάγκη. τό γε μὴν", "r": "теперь, то, попав в него, оно всегда задерживается в бытии и в тот миг есть то, чем случилось ему стать. — Явно. — Стало быть, и одно, когда, становясь старше, попадает оно на теперь, задерживается в бытии и в то мгновение есть старше. — Конечно, так. — Но не того ли оно старше есть, чего старше стало, а стало оно старше не себя ли? — Да. — Старшее же не есть ли старше младшего? — Есть. — И стало быть, одно, когда, становясь старше, попадает на"}, "152e": {"g": "νῦν ἀεὶ πάρεστι τῷ ἑνὶ διὰ παντὸς τοῦ εἶναι· ἔστι γὰρ ἀεὶ νῦν ὅτανπερ ᾖ. πῶς γὰρ οὔ; ἀεὶ ἄρα ἐστί τε καὶ γίγνεται πρεσβύτερον ἑαυτοῦ καὶ νεώτερον τὸ ἕν. ἔοικεν. πλείω δὲ χρόνον αὐτὸ ἑαυτοῦ ἔστιν ἢ γίγνεται, ἢ τὸν ἴσον; τὸν ἴσον. ἀλλὰ μὴν τόν γε ἴσον χρόνον ἢ γιγνόμενον ἢ ὂν τὴν αὐτὴν ἡλικίαν ἔχει. πῶς δʼ οὔ; τὸ δὲ τὴν αὐτὴν ἡλικίαν ἔχον οὔτε πρεσβύτερον οὔτε νεώτερόν ἐστιν. οὐ γάρ. τὸ ἓν ἄρα τὸν ἴσον χρόνον αὐτὸ ἑαυτῷ καὶ γιγνόμενον καὶ ὂν οὔτε νεώτερον οὔτε πρεσβύτερον ἑαυτοῦ ἐστιν οὐδὲ γίγνεται. οὔ μοι δοκεῖ. τί δέ; τῶν ἄλλων; οὐκ ἔχω λέγειν.", "r": "теперь, тогда есть моложе себя. — Необходимо. — Однакож теперь всегда присуще одному, в течение всего его бытия; потому что одно всегда есть теперь, когда бы оно ни было. — Как не есть! — Стало быть, одно всегда есть и бывает как старше себя, так и моложе. — Походит. — Но большее ли, или равное с собою время есть оно или бывает? — Равное. — А если равное-то время и есть и бывает, то оно имеет тот же возраст. — Как же иначе. — Имеющее же тот самый возраст — ни старше, ни моложе. — Конечно, нет. — Стало быть, одно, когда оно и бывает и есть равное с самим собою время, — не бывает и не есть ни моложе, ни старше себя. — Мне кажется,"}, "153a": {"g": "τόδε γε μὴν ἔχεις λέγειν, ὅτι τὰ ἄλλα τοῦ ἑνός, εἴπερ ἕτερά ἐστιν, ἀλλὰ μὴ ἕτερον, πλείω ἐστὶν ἑνός· ἕτερον μὲν γὰρ ὂν ἓν ἂν ἦν, ἕτερα δὲ ὄντα πλείω ἑνός ἐστι καὶ πλῆθος ἂν ἔχοι. ἔχοι γὰρ ἄν. πλῆθος δὲ ὂν ἀριθμοῦ πλείονος ἂν μετέχοι ἢ τοῦ ἑνός. πῶς δʼ οὔ; τί οὖν; ἀριθμοῦ φήσομεν τὰ πλείω γίγνεσθαί τε καὶ γεγονέναι πρότερον, ἢ τὰ ἐλάττω; τὰ ἐλάττω. τὸ ὀλίγιστον ἄρα πρῶτον· τοῦτο", "r": "нет. — Что же теперь по отношению к иному? — Не могу сказать. — Но то-то однакож можешь сказать, что вещей иных по отношению к одному, — если они другие, а не другое, — больше чем одно; ибо если бы вещи были другое, то были бы одно; а так как они другие, то их больше одного. — Больше. — И они имеют количество. — Конечно, имеют. — Будучи же количеством, они будут причастны бо́льшего числа, нежели одно. — Как не будут. — Так что же? по отношению к числу, большее ли, скажем, является и явилось сначала, или меньшее? — Меньшее. — Значит, самое меньшее — первое; а это — одно. Не так ли? — Да. —"}, "153b": {"g": "δʼ ἔστι τὸ ἕν. ἦ γάρ; ναί. πάντων ἄρα τὸ ἓν πρῶτον γέγονε τῶν ἀριθμὸν ἐχόντων· ἔχει δὲ καὶ τἆλλα πάντα ἀριθμόν, εἴπερ ἄλλα καὶ μὴ ἄλλο ἐστίν. ἔχει γάρ. πρῶτον δέ γε οἶμαι γεγονὸς πρότερον γέγονε, τὰ δὲ ἄλλα ὕστερον, τὰ δʼ ὕστερον γεγονότα νεώτερα τοῦ πρότερον γεγονότος· καὶ οὕτως ἂν εἴη τἆλλα νεώτερα τοῦ ἑνός, τὸ δὲ ἓν πρεσβύτερον τῶν ἄλλων. εἴη γὰρ ἄν. τί δὲ τόδε; ἆρʼ ἂν εἴη τὸ ἓν παρὰ φύσιν τὴν αὑτοῦ", "r": "Стало быть, из всего, что имеет число, одно явилось первым. Но и все иные вещи имеют число, если они — иные, а не иное. — Конечно, имеют. — Явившись первым-то, одно явилось, думаю, прежде, а иные вещи — после. Явившееся же после моложе явившегося прежде. Таким образом и прочие вещи будут моложе одного, а одно — старше иных вещей — Конечно, будут. — Что же это-то? Вопреки ли своей природе произошло одно, — или это невозможно? — Невозможно. — Ведь одно-то, как оказалось, имеет"}, "153c": {"g": "γεγονός, ἢ ἀδύνατον; ἀδύνατον. ἀλλὰ μὴν μέρη γε ἔχον ἐφάνη τὸ ἕν, εἰ δὲ μέρη, καὶ ἀρχὴν καὶ τελευτὴν καὶ μέσον. ναί. οὐκοῦν πάντων πρῶτον ἀρχὴ γίγνεται, καὶ αὐτοῦ τοῦ ἑνὸς καὶ ἑκάστου τῶν ἄλλων, καὶ μετὰ τὴν ἀρχὴν καὶ τἆλλα πάντα μέχρι τοῦ τέλους; τί μήν; καὶ μὴν μόριά γε φήσομεν ταῦτʼ εἶναι πάντα τἆλλα τοῦ ὅλου τε καὶ ἑνός, αὐτὸ δὲ ἐκεῖνο ἅμα τῇ τελευτῇ γεγονέναι ἕν τε καὶ ὅλον. φήσομεν γάρ. τελευτὴ δέ γε οἶμαι ὕστατον γίγνεται, τούτῳ", "r": "части; а если имеет оно части, то и начало, и конец, и средину. — Да. — Но не прежде ли всего является начало, — как у самого одного, так и у каждой из иных вещей, и не после ли начала — всё прочее, до самого конца? — Как же. — А всё это прочее, скажем, суть части целого и одного; само же то явилось одним и целым вместе с концом. — Да, скажем. — Но конец-то, думаю, является как самое последнее, и происходить вместе с ним"}, "153d": {"g": "δʼ ἅμα τὸ ἓν πέφυκε γίγνεσθαι· ὥστʼ εἴπερ ἀνάγκη αὐτὸ τὸ ἓν μὴ παρὰ φύσιν γίγνεσθαι, ἅμα τελευτῇ ἂν γεγονὸς ὕστατον ἂν τῶν ἄλλων πεφυκὸς εἴη γίγνεσθαι. φαίνεται. νεώτερον ἄρα τῶν ἄλλων τὸ ἕν ἐστι, τὰ δʼ ἄλλα τοῦ ἑνὸς πρεσβύτερα. οὕτως αὖ μοι φαίνεται. τί δὲ δή; ἀρχὴν ἢ ἄλλο μέρος ὁτιοῦν τοῦ ἑνὸς ἢ ἄλλου ὁτουοῦν, ἐάνπερ μέρος ᾖ ἀλλὰ μὴ μέρη, οὐκ ἀναγκαῖον ἓν εἶναι, μέρος γε ὄν; ἀνάγκη. οὐκοῦν τὸ ἓν ἅμα τε τῷ πρώτῳ γιγνομένῳ γίγνοιτʼ ἂν καὶ", "r": "лежит в природе одного; так что если само одно необходимо является не вопреки природе, то, происшедши вместе с концом, оно должно, по природе, явиться в заключение всего. — Явно. — Стало быть, одно моложе иных вещей, а иные вещи старше одного. — Так опять представляется мне. — Что же далее? Если бы начало, или иная какая бы то ни было часть одного, либо инаго чего-нибудь, была часть, а не части, то, будучи частью, не необходимо ли ей быть одним? — Необходимо. — Поэтому одно произойдет и вместе с появлением"}, "153e": {"g": "ἅμα τῷ δευτέρῳ, καὶ οὐδενὸς ἀπολείπεται τῶν ἄλλων γιγνομένων, ὅτιπερ ἂν προσγίγνηται ὁτῳοῦν, ἕως ἂν πρὸς τὸ ἔσχατον διελθὸν ὅλον ἓν γένηται, οὔτε μέσου οὔτε πρώτου οὔτε ἐσχάτου οὔτε ἄλλου οὐδενὸς ἀπολειφθὲν ἐν τῇ γενέσει. ἀληθῆ. πᾶσιν ἄρα τοῖς ἄλλοις τὴν αὐτὴν ἡλικίαν ἴσχει τὸ ἕν· ὥστʼ εἰ μὴ παρὰ φύσιν πέφυκεν αὐτὸ τὸ ἕν, οὔτε πρότερον οὔτε ὕστερον τῶν ἄλλων γεγονὸς ἂν εἴη, ἀλλʼ ἅμα.", "r": "первой, и вместе с появлением второй, и не отступит ни от одной из являющихся частей, какая бы еще ни явилась, пока, дошедши до последней, не сделается целым одним, не отдельным в своем происхождении ни от средней, ни от последней, ни от первой, ни от какой иной. — Правда. — Стало быть, одно — того же возраста со всем прочим; так что если само одно идет не вопреки своей природе, то оно должно бы произойти и не"}, "154a": {"g": "καὶ κατὰ τοῦτον τὸν λόγον τὸ ἓν τῶν ἄλλων οὔτε πρεσβύτερον οὔτε νεώτερον ἂν εἴη, οὐδὲ τἆλλα τοῦ ἑνός· κατὰ δὲ τὸν πρόσθεν πρεσβύτερόν τε καὶ νεώτερον, καὶ τἆλλα ἐκείνου ὡσαύτως. πάνυ μὲν οὖν. ἔστι μὲν δὴ οὕτως ἔχον τε καὶ γεγονός. ἀλλὰ τί αὖ περὶ τοῦ γίγνεσθαι αὐτὸ πρεσβύτερόν τε καὶ νεώτερον τῶν ἄλλων καὶ τἆλλα τοῦ ἑνός, καὶ μήτε νεώτερον μήτε πρεσβύτερον γίγνεσθαι; ἆρα ὥσπερ περὶ τοῦ εἶναι, οὕτω καὶ περὶ τοῦ γίγνεσθαι ἔχει, ἢ ἑτέρως; οὐκ", "r": "прежде, и не после иных вещей, а вместе с ними. По той же причине одно будет и не старше иных вещей, и не моложе, как и иные вещи в отношении одного. А на прежнем основании одно и старше и моложе, равно как и иные вещи относительно его. — Конечно. — В таком оно положении и так произошло. Но что̀ сказать о том, что одно бывает старше и моложе иных вещей, а иные вещи старше и моложе одного, или, опять, что одно не бывает ни старше, ни моложе? То же ли имеет силу и относительно бывания, что относительно бытия, или иное? — Не могу сказать. — А я скажу по крайней мере то, что если"}, "154b": {"g": "ἔχω λέγειν. ἀλλʼ ἐγὼ τοσόνδε γε· εἰ καὶ ἔστιν πρεσβύτερον ἕτερον ἑτέρου, γίγνεσθαί γε αὐτὸ πρεσβύτερον ἔτι ἢ ὡς τὸ πρῶτον εὐθὺς γενόμενον διήνεγκε τῇ ἡλικίᾳ οὐκ ἂν ἔτι δύναιτο, οὐδʼ αὖ τὸ νεώτερον ὂν ἔτι νεώτερον γίγνεσθαι· ἀνίσοις γὰρ ἴσα προστιθέμενα, χρόνῳ τε καὶ ἄλλῳ ὁτῳοῦν, ἴσῳ ποιεῖ διαφέρειν ἀεὶ ὅσῳπερ ἂν τὸ πρῶτον διενέγκῃ. πῶς γὰρ οὔ; οὐκ ἄρα τό γε ὂν τοῦ ἑνὸς ὄντος γίγνοιτʼ", "r": "что-нибудь старше другого, то быть не может, чтобы старшее бывало еще более старым, чем сколько отличалось оно возрастом сначала, при самом своем появлении, или, наоборот, чтобы младшее становилось еще более молодо; ибо когда к неравным частям прибавляются равные, — по времени, или по чему иному, — разность всегда бывает равная, — та же, которою они различались прежде. — Ка̀к не равная. — Стало быть, если разность возрастов всегда равна, то сущее-то сущего никогда не будет ни старше, ни моложе, но старшее есть и явилось старше, а младшее — моложе, не"}, "154c": {"g": "ἄν ποτε πρεσβύτερον οὐδὲ νεώτερον, εἴπερ ἴσῳ διαφέρει ἀεὶ τὴν ἡλικίαν· ἀλλʼ ἔστι καὶ γέγονε πρεσβύτερον, τὸ δὲ νεώτερον, γίγνεται δʼ οὔ. ἀληθῆ. καὶ τὸ ἓν ἄρα ὂν τῶν ἄλλων ὄντων οὔτε πρεσβύτερόν ποτε οὔτε νεώτερον γίγνεται. οὐ γὰρ οὖν. ὅρα δὲ εἰ τῇδε πρεσβύτερα καὶ νεώτερα γίγνεται. πῇ δή; ἧι τό τε ἓν τῶν ἄλλων ἐφάνη πρεσβύτερον καὶ τἆλλα τοῦ ἑνός. τί οὖν; ὅταν τὸ ἓν τῶν ἄλλων πρεσβύτερον ᾖ, πλείω που χρόνον γέγονεν ἢ τὰ", "r": "бывая таким. — Правда. — И стало быть, одно, как сущее, никогда не бывает ни старше, ни моложе иных сущих. — Конечно, не бывает. — Смотри же, бывают ли таким-то образом предметы старшие и младшие? — Каким, то есть? — Которым и одно являлось старше иных вещей, и иные вещи — старше одного. — Так что же? — Когда одно старше иных вещей, оно провело, вероятно, больше времени, чем иные вещи. — Да. — Наблюдай же опять: если к большему"}, "154d": {"g": "ἄλλα. ναί. πάλιν δὴ σκόπει· ἐὰν πλέονι καὶ ἐλάττονι χρόνῳ προστιθῶμεν τὸν ἴσον χρόνον, ἆρα τῷ ἴσῳ μορίῳ διοίσει τὸ πλέον τοῦ ἐλάττονος ἢ σμικροτέρῳ; σμικροτέρῳ. οὐκ ἄρα ἔσται, ὅτιπερ τὸ πρῶτον ἦν πρὸς τἆλλα ἡλικίᾳ διαφέρον τὸ ἕν, τοῦτο καὶ εἰς τὸ ἔπειτα, ἀλλὰ ἴσον λαμβάνον χρόνον τοῖς ἄλλοις ἔλαττον ἀεὶ τῇ ἡλικίᾳ διοίσει αὐτῶν ἢ πρότερον· ἢ οὔ; ναί. οὐκοῦν τό γε ἔλαττον διαφέρον", "r": "и меньшему времени мы прибавим время равное, то равною ли долею будет различаться большее от меньшего, или меньшею? — Меньшею. — Стало быть, одно не будет потом настолько же, как и прежде, отличаться возрастом от иных вещей, но, получив равное с ними время, всегда относительно их будет иметь в возрасте меньшую, чем прежде, разность. Не так ли? — Да. — Но что̀ меньше-то"}, "154e": {"g": "ἡλικίᾳ πρός τι ἢ πρότερον νεώτερον γίγνοιτʼ ἂν ἢ ἐν τῷ πρόσθεν πρὸς ἐκεῖνα πρὸς ἃ ἦν πρεσβύτερον πρότερον; νεώτερον. εἰ δὲ ἐκεῖνο νεώτερον, οὐκ ἐκεῖνα αὖ τὰ ἄλλα πρὸς τὸ ἓν πρεσβύτερα ἢ πρότερον; πάνυ γε. τὸ μὲν νεώτερον ἄρα γεγονὸς πρεσβύτερον γίγνεται πρὸς τὸ πρότερον γεγονός τε καὶ πρεσβύτερον ὄν, ἔστι δὲ οὐδέποτε πρεσβύτερον, ἀλλὰ γίγνεται ἀεὶ ἐκείνου πρεσβύτερον· ἐκεῖνο μὲν γὰρ ἐπὶ τὸ νεώτερον ἐπιδίδωσιν, τὸ δʼ ἐπὶ τὸ πρεσβύτερον.", "r": "отличается возрастом от чего-нибудь, чем прежде, то̀ не моложе ли будет прежнего сравнительно с тем, в отношении к чему сперва было старше? — Моложе. — Если же моложе, то то̀ другое, опять, в отношении к тому одному, не будет ли старше, чем прежде? — Конечно. — Итак, младшее по рождению бывает старше по отношению к тому, что̀ родилось прежде и есть старше: но это никогда не есть, а всегда бывает старше того; ибо то всегда получает прибавку к младшинству, а это к старшинству."}, "155a": {"g": "τὸ δʼ αὖ πρεσβύτερον τοῦ νεωτέρου νεώτερον γίγνεται ὡσαύτως. ἰόντε γὰρ αὐτοῖν εἰς τὸ ἐναντίον τὸ ἐναντίον ἀλλήλοιν γίγνεσθον, τὸ μὲν νεώτερον πρεσβύτερον τοῦ πρεσβυτέρου, τὸ δὲ πρεσβύτερον νεώτερον τοῦ νεωτέρου· γενέσθαι δὲ οὐκ ἂν οἵω τε εἴτην. εἰ γὰρ γένοιντο, οὐκ ἂν ἔτι γίγνοιντο, ἀλλʼ εἶεν ἄν. νῦν δὲ γίγνονται μὲν πρεσβύτερα ἀλλήλων καὶ νεώτερα· τὸ μὲν ἓν τῶν ἄλλων νεώτερον γίγνεται, ὅτι πρεσβύτερον ἐφάνη ὂν καὶ πρότερον", "r": "Таким же образом, опять, старшее бывает моложе младшего; ибо, идя по противоположным направлениям, они становятся противоположными одно другому, — младшее старшим старшего, старшее младшим младшего. Но сделаться такими они не в состоянии; потому что если бы сделались, то уже не бывали бы, а были. Напротив, теперь они бывают старше и моложе одно другого: одно бывает моложе иных вещей, ибо оказалось старшим и возникшим прежде; а"}, "155b": {"g": "γεγονός, τὰ δὲ ἄλλα τοῦ ἑνὸς πρεσβύτερα, ὅτι ὕστερα γέγονε. κατὰ δὲ τὸν αὐτὸν λόγον καὶ τἆλλα οὕτω πρὸς τὸ ἓν ἴσχει, ἐπειδήπερ αὐτοῦ πρεσβύτερα ἐφάνη καὶ πρότερα γεγονότα. φαίνεται γὰρ οὖν οὕτως. οὐκοῦν ᾗ μὲν οὐδὲν ἕτερον ἑτέρου πρεσβύτερον γίγνεται οὐδὲ νεώτερον, κατὰ τὸ ἴσῳ ἀριθμῷ ἀλλήλων ἀεὶ διαφέρειν, οὔτε τὸ ἓν τῶν ἄλλων πρεσβύτερον γίγνοιτʼ ἂν οὐδὲ νεώτερον, οὔτε τἆλλα τοῦ ἑνός· ᾗ δὲ ἄλλῳ ἀεὶ μορίῳ διαφέρειν ἀνάγκη", "r": "иные вещи бывают старше одного, потому что родились после. По такой же причине и иные вещи та̀к относятся к одному, поколику оказались старшими и возникшими прежде его. — Да, представляется так. — Итак, если ничто не бывает ни старше, ни моложе одно другого, поскольку то и другое всегда различаются на равное число; то и одно могло бы бывать ни старше, ни моложе иных вещей, и иные вещи — ни старше, ни моложе одного. Но поскольку бывающее"}, "155c": {"g": "τὰ πρότερα τῶν ὑστέρων γενόμενα καὶ τὰ ὕστερα τῶν προτέρων, ταύτῃ δὴ ἀνάγκη πρεσβύτερά τε καὶ νεώτερα ἀλλήλων γίγνεσθαι τά τε ἄλλα τοῦ ἑνὸς καὶ τὸ ἓν τῶν ἄλλων; πάνυ μὲν οὖν. κατὰ δὴ πάντα ταῦτα τὸ ἓν αὐτό τε αὑτοῦ καὶ τῶν ἄλλων πρεσβύτερον καὶ νεώτερον ἔστι τε καὶ γίγνεται, καὶ οὔτε πρεσβύτερον οὔτε νεώτερον οὔτʼ ἔστιν οὔτε γίγνεται οὔτε αὑτοῦ οὔτε τῶν ἄλλων. παντελῶς μὲν οὖν. ἐπειδὴ δὲ χρόνου μετέχει τὸ ἓν καὶ τοῦ", "r": "прежде от позднейшего и позднейшее от бывающего прежде необходимо различаются всегда иною долею; постольку необходимо также бывать взаимно старше и моложе: одному — против иных вещей и иным вещам — против одного. — Конечно, так. — По всему же этому, одно как есть и бывает старше и моложе, и само себя, и иных вещей, так и не есть и не бывает ни старше, ни моложе, ни себя, ни иных вещей. — Совершенно так. — А как скоро одно причастно времени и свойства бывать"}, "155d": {"g": "πρεσβύτερόν τε καὶ νεώτερον γίγνεσθαι, ἆρʼ οὐκ ἀνάγκη καὶ τοῦ ποτὲ μετέχειν καὶ τοῦ ἔπειτα καὶ τοῦ νῦν, εἴπερ χρόνου μετέχει; ἀνάγκη. ἦν ἄρα τὸ ἓν καὶ ἔστι καὶ ἔσται καὶ ἐγίγνετο καὶ γίγνεται καὶ γενήσεται. τί μήν; καὶ εἴη ἄν τι ἐκείνῳ καὶ ἐκείνου, καὶ ἦν καὶ ἔστιν καὶ ἔσται. πάνυ γε. καὶ ἐπιστήμη δὴ εἴη ἂν αὐτοῦ καὶ δόξα καὶ αἴσθησις, εἴπερ καὶ νῦν ἡμεῖς περὶ αὐτοῦ πάντα ταῦτα πράττομεν. ὀρθῶς λέγεις. καὶ ὄνομα δὴ καὶ λόγος ἔστιν αὐτῷ, καὶ", "r": "и старше и моложе, то не необходимо ли ему, если оно причастно времени, быть причастным и этих — некогда, потом и теперь? — Необходимо. — Стало быть, одно и было, и есть, и будет, и бывало, и бывает, и будет бывать. — Как же. — И возможно, что было, есть и будет нечто такое, что̀ относится к нему и принадлежит ему. — Конечно. — Для него может быть и знание, и мнение, и чувство, как и теперь в отношении к нему мы проявляем всё это. — Ты говоришь правильно. — Есть для него и имя и слово, — оно и именуется, и высказывается; и всё, что есть"}, "155e": {"g": "ὀνομάζεται καὶ λέγεται· καὶ ὅσαπερ καὶ περὶ τὰ ἄλλα τῶν τοιούτων τυγχάνει ὄντα, καὶ περὶ τὸ ἓν ἔστιν. παντελῶς μὲν οὖν ἔχει οὕτως. ἔτι δὴ τὸ τρίτον λέγωμεν. τὸ ἓν εἰ ἔστιν οἷον διεληλύθαμεν, ἆρʼ οὐκ ἀνάγκη αὐτό, ἕν τε ὂν καὶ πολλὰ καὶ μήτε ἓν μήτε πολλὰ καὶ μετέχον χρόνου, ὅτι μὲν ἔστιν ἕν, οὐσίας μετέχειν ποτέ, ὅτι δʼ οὐκ ἔστι, μὴ μετέχειν αὖ ποτε οὐσίας; ἀνάγκη. ἆρʼ οὖν, ὅτε μετέχει, οἷόν τε ἔσται τότε μὴ μετέχειν, ἢ ὅτε μὴ μετέχει, μετέχειν; οὐχ οἷόν τε. ἐν ἄλλῳ ἄρα χρόνῳ μετέχει καὶ ἐν ἄλλῳ οὐ μετέχει· οὕτω γὰρ ἂν μόνως τοῦ αὐτοῦ μετέχοι τε καὶ οὐ μετέχοι.", "r": "в этом роде возможного по отношению к иным вещам, возможно и по отношению к одному. — Совершенно так. —\n\nИсследуем теперь еще третие. Если «одно есть» при тех условиях, как мы нашли, — есть одно и многое, и ни одно, ни многое, а также причастно времени, — не необходимо ли заключить, что оно, поколику есть одно, приобщается иногда сущности, а поколику не есть, не приобщается иногда сущности? — Необходимо. — И когда приобщается, возможно ли ему в то время не приобщаться, или, когда не приобщается, — приобщаться? — Невозможно. — Стало быть, в иное время оно приобщается, а в иное не приобщается; ибо так только могло бы оно того же самого и приобщаться,"}, "156a": {"g": "ὀρθῶς. οὐκοῦν ἔστι καὶ οὗτος χρόνος, ὅτε μεταλαμβάνει τοῦ εἶναι καὶ ὅτε ἀπαλλάττεται αὐτοῦ; ἢ πῶς οἷόν τε ἔσται τοτὲ μὲν ἔχειν τὸ αὐτό, τοτὲ δὲ μὴ ἔχειν, ἐὰν μή ποτε καὶ λαμβάνῃ αὐτὸ καὶ ἀφίῃ; οὐδαμῶς. τὸ δὴ οὐσίας μεταλαμβάνειν ἆρά γε οὐ γίγνεσθαι καλεῖς; ἔγωγε. τὸ δὲ ἀπαλλάττεσθαι οὐσίας ἆρα οὐκ ἀπόλλυσθαι; καὶ πάνυ γε. τὸ ἓν δή, ὡς ἔοικε, λαμβάνον τε καὶ ἀφιὲν οὐσίαν γίγνεταί", "r": "и не приобщаться. — Правильно. — Посему есть и такое время, когда оно воспринимает бытие, и когда оставляет его. Иначе как будет возможно то иметь то же самое, то не иметь, если оно в известный момент не примет бытия, и не оставит? — Никак. — А воспринимать сущность — не рождением ли ты называешь это? — Да. — Оставлять же сущность — не разрушением ли? — Конечно. — Так одно, принимая и оставляя сущность, как видно, рождается"}, "156b": {"g": "τε καὶ ἀπόλλυται. ἀνάγκη. ἓν δὲ καὶ πολλὰ ὂν καὶ γιγνόμενον καὶ ἀπολλύμενον ἆρʼ οὐχ, ὅταν μὲν γίγνηται ἕν, τὸ πολλὰ εἶναι ἀπόλλυται, ὅταν δὲ πολλά, τὸ ἓν εἶναι ἀπόλλυται; πάνυ γε. ἓν δὲ γιγνόμενον καὶ πολλὰ ἆρʼ οὐκ ἀνάγκη διακρίνεσθαί τε καὶ συγκρίνεσθαι; πολλή γε. καὶ μὴν ἀνόμοιόν γε καὶ ὅμοιον ὅταν γίγνηται, ὁμοιοῦσθαί τε καὶ ἀνομοιοῦσθαι; ναί. καὶ ὅταν μεῖζον καὶ ἔλαττον καὶ ἴσον, αὐξάνεσθαί τε καὶ φθίνειν καὶ ἰσοῦσθαι; οὕτως.", "r": "и разрушается. — Необходимо. — Но, будучи одним и многим, рождающимся и разрушающимся, не разрушается ли оно в значении многого, когда рождается одним, и не разрушается ли в значении одного, когда рождается многим? — Конечно. — Бывая же одним и многим, не необходимо ли ему разделяться и соединяться? — И очень. — Да тоже, когда оно подобно-то и не подобно, — уподобляться и лишаться подобия? — Да. — И опять, когда оно больше, меньше и равно, — увеличиваться,"}, "156c": {"g": "ὅταν δὲ κινούμενόν τε ἵστηται καὶ ὅταν ἑστὸς ἐπὶ τὸ κινεῖσθαι μεταβάλλῃ, δεῖ δήπου αὐτό γε μηδʼ ἐν ἑνὶ χρόνῳ εἶναι. πῶς δή; ἑστός τε πρότερον ὕστερον κινεῖσθαι καὶ πρότερον κινούμενον ὕστερον ἑστάναι, ἄνευ μὲν τοῦ μεταβάλλειν οὐχ οἷόν τε ἔσται ταῦτα πάσχειν. πῶς γάρ; χρόνος δέ γε οὐδεὶς ἔστιν, ἐν ᾧ τι οἷόν τε ἅμα μήτε κινεῖσθαι μήτε ἑστάναι. οὐ γὰρ οὖν. ἀλλʼ οὐδὲ μὴν μεταβάλλει ἄνευ τοῦ μεταβάλλειν. οὐκ εἰκός. πότʼ οὖν μεταβάλλει; οὔτε γὰρ ἑστὸς ὂν οὔτε κινούμενον μεταβάλλει, οὔτε ἐν", "r": "умаляться и равняться? — Так. — А когда оно, движась, останавливается, и стоя, переходит к движению, тогда само-то, вероятно, должно быть вне всякого времени. — Как так? — Прежде стоявшему потом двигаться, и прежде двигавшемуся потом стоять, — испытывать это, не подвергаясь перемене, невозможно. — Как возможно! — А нет такого (малого) времени, когда что-либо могло бы вместе и не двигаться, и не стоять. — Конечно, нет. — Однако ведь не будет же перемены без перемены. — Естественно, нет. — Когда же оно переменится? Ведь оно"}, "156d": {"g": "χρόνῳ ὄν. οὐ γὰρ οὖν. ἆρʼ οὖν ἔστι τὸ ἄτοπον τοῦτο, ἐν ᾧ τότʼ ἂν εἴη, ὅτε μεταβάλλει; τὸ ποῖον δή; τὸ ἐξαίφνης. τὸ γὰρ ἐξαίφνης τοιόνδε τι ἔοικε σημαίνειν, ὡς ἐξ ἐκείνου μεταβάλλον εἰς ἑκάτερον. οὐ γὰρ ἔκ γε τοῦ ἑστάναι ἑστῶτος ἔτι μεταβάλλει, οὐδʼ ἐκ τῆς κινήσεως κινουμένης ἔτι μεταβάλλει· ἀλλὰ ἡ ἐξαίφνης αὕτη φύσις ἄτοπός τις ἐγκάθηται μεταξὺ τῆς κινήσεώς τε καὶ στάσεως,", "r": "не может перемениться ни стоя, ни двигаясь, ни находясь во времени. — Конечно, не может. — Не странным ли выходит то, в чём оно должно находиться, когда переменяется? — Что же это такое? — Мгновенность. Ведь мгновенность, по-видимому, означает нечто такое, что из неё происходит перемена на обе стороны; ибо из стояния-то стоящего еще не выходит перемены, и из движения движущегося еще не выходит перемены; но эта странная какая-то природа мгновенности лежит между движением и стоянием, не находясь ни в каком времени, и (только)"}, "156e": {"g": "ἐν χρόνῳ οὐδενὶ οὖσα, καὶ εἰς ταύτην δὴ καὶ ἐκ ταύτης τό τε κινούμενον μεταβάλλει ἐπὶ τὸ ἑστάναι καὶ τὸ ἑστὸς ἐπὶ τὸ κινεῖσθαι. κινδυνεύει. καὶ τὸ ἓν δή, εἴπερ ἕστηκέ τε καὶ κινεῖται, μεταβάλλοι ἂν ἐφʼ ἑκάτερα—μόνως γὰρ ἂν οὕτως ἀμφότερα ποιοῖ—μεταβάλλον δʼ ἐξαίφνης μεταβάλλει, καὶ ὅτε μεταβάλλει, ἐν οὐδενὶ χρόνῳ ἂν εἴη, οὐδὲ κινοῖτʼ ἂν τότε, οὐδʼ ἂν σταίη. οὐ γάρ. ἆρʼ οὖν οὕτω καὶ πρὸς τὰς ἄλλας μεταβολὰς ἔχει, ὅταν ἐκ τοῦ εἶναι εἰς τὸ ἀπόλλυσθαι", "r": "в ней и из неё движущееся переходит к стоянию и стоящее к движению. — Должно быть. — Так одно, если оно и стоит, и движется, должно подвергаться перемене в том и другом отношении; ибо только так осуществляет оба состояния. Подвергаясь же перемене, оно подвергается ей мгновенно; и когда переменяется, оно не бывает ни в каком времени, и не движется тогда, и не стоит. — Конечно, нет. — Так ли относится одно и к иным переменам? Когда из бытия происходит в нём перемена к уничтожению, или из небытия к рождению, не бывает ли оно и тогда между некоторыми движениями и"}, "157a": {"g": "μεταβάλλῃ ἢ ἐκ τοῦ μὴ εἶναι εἰς τὸ γίγνεσθαι, μεταξύ τινων τότε γίγνεται κινήσεών τε καὶ στάσεων, καὶ οὔτε ἔστι τότε οὔτε οὐκ ἔστι, οὔτε γίγνεται οὔτε ἀπόλλυται; ἔοικε γοῦν. κατὰ δὴ τὸν αὐτὸν λόγον καὶ ἐξ ἑνὸς ἐπὶ πολλὰ ἰὸν καὶ ἐκ πολλῶν ἐφʼ ἓν οὔτε ἕν ἐστιν οὔτε πολλά, οὔτε διακρίνεται οὔτε συγκρίνεται. καὶ ἐξ ὁμοίου ἐπὶ ἀνόμοιον καὶ ἐξ ἀνομοίου ἐπὶ ὅμοιον ἰὸν οὔτε ὅμοιον οὔτε ἀνόμοιον, οὔτε ὁμοιούμενον οὔτε ἀνομοιούμενον· καὶ", "r": "стояниями, так что оно и есть тогда и не есть, и не рождается и не уничтожается? — В самом деле, походит. — По той же причине, когда переходит и из одного ко многому, и из многого к одному, одно не есть ни одно, ни многое, не разделяется и не соединяется; и идя из подобного к не подобному, и из не подобного к подобному, оно ни подобно, ни не подобно, и не уподобляется, и не делается не подобным; и идя из малого к великому и равному, либо"}, "157b": {"g": "ἐκ σμικροῦ ἐπὶ μέγα καὶ ἐπὶ ἴσον καὶ εἰς τὰ ἐναντία ἰὸν οὔτε σμικρὸν οὔτε μέγα οὔτε ἴσον, οὔτε αὐξανόμενον οὔτε φθῖνον οὔτε ἰσούμενον εἴη ἄν. οὐκ ἔοικε. ταῦτα δὴ τὰ παθήματα πάντʼ ἂν πάσχοι τὸ ἕν, εἰ ἔστιν. πῶς δʼ οὔ; τί δὲ τοῖς ἄλλοις προσήκοι ἂν πάσχειν, ἓν εἰ ἔστιν , ἆρα οὐ σκεπτέον; σκεπτέον. λέγωμεν δή, ἓν εἰ ἔστι , τἆλλα τοῦ ἑνὸς τί χρὴ πεπονθέναι; λέγωμεν. οὐκοῦν ἐπείπερ ἄλλα τοῦ ἑνός ἐστιν, οὔτε τὸ ἕν ἐστι τἆλλα· οὐ", "r": "наоборот, оно ни мало, ни велико, ни равно, и не увеличивается, и не уменьшается, и не равняется. — Походит, что нет. — Такие-то все свойства получает одно, если оно есть. — Ка̀к не такие.\n\nНе рассмотреть ли теперь, что̀ приходится испытывать иным вещам, если одно есть? — Надобно рассмотреть. — Скажем ли же, что̀ должно испытать иное относительно одного, если одно есть? — Скажем. — Итак, если иное относительно одного есть, то одно не есть иное; потому что иначе не было бы инаго относительно одного. — Правильно. — Однакож иное не совсем лишено одного, а каким-то образом причастно его. — Каким же образом? — Иное относительно одного есть иное, поколику имеет части; ибо если бы не имело оно частей, то было бы совершенно одно. — Правильно."}, "157c": {"g": "γὰρ ἂν ἄλλα τοῦ ἑνὸς ἦν. ὀρθῶς. οὐδὲ μὴν στέρεταί γε παντάπασι τοῦ ἑνὸς τἆλλα, ἀλλὰ μετέχει πῃ. πῇ δή; ὅτι που τὰ ἄλλα τοῦ ἑνὸς μόρια ἔχοντα ἄλλα ἐστίν· εἰ γὰρ μόρια μὴ ἔχοι, παντελῶς ἂν ἓν εἴη. ὀρθῶς. μόρια δέ γε, φαμέν, τούτου ἐστὶν ὃ ἂν ὅλον ᾖ. φαμὲν γάρ. ἀλλὰ μὴν τό γε ὅλον ἓν ἐκ πολλῶν ἀνάγκη εἶναι, οὗ ἔσται μόρια τὰ μόρια· ἕκαστον γὰρ τῶν μορίων οὐ πολλῶν μόριον χρὴ εἶναι, ἀλλὰ ὅλου. πῶς τοῦτο; εἴ τι πολλῶν μόριον εἴη,", "r": "— А части-то, говорим, свойственно иметь тому, что есть целое. — Да, говорим. — Целому же одному, которого части будут частями, необходимо состоять из многого; потому что каждая из частей должна быть частью не многого, а целого. — Как это? — Если бы что-нибудь было частью многого, к которому и само принадлежало, то"}, "157d": {"g": "ἐν οἷς αὐτὸ εἴη, ἑαυτοῦ τε δήπου μόριον ἔσται, ὅ ἐστιν ἀδύνατον, καὶ τῶν ἄλλων δὴ ἑνὸς ἑκάστου, εἴπερ καὶ πάντων. ἑνὸς γὰρ μὴ ὂν μόριον, πλὴν τούτου τῶν ἄλλων ἔσται, καὶ οὕτως ἑνὸς ἑκάστου οὐκ ἔσται μόριον, μὴ ὂν δὲ μόριον ἑκάστου οὐδενὸς τῶν πολλῶν ἔσται. μηδενὸς δὲ ὂν πάντων τούτων τι εἶναι, ὧν οὐδενὸς οὐδέν ἐστι, καὶ μόριον καὶ ἄλλο ὁτιοῦν ἀδύνατον εἶναι . φαίνεταί γε δή. οὐκ ἄρα τῶν πολλῶν οὐδὲ πάντων τὸ μόριον μόριον, ἀλλὰ μιᾶς τινὸς ἰδέας καὶ", "r": "составляло бы, конечно, часть как себя, что невозможно, так и каждой из иных относительно одного вещей, если уж оно есть часть всего; ибо, не будучи частью одного, оно будет частью инаго кроме этого, и таким образом не будет частью чего-либо единичного, а коли так, не будет частью ничего во многом; не будучи же частью ничего, невозможно ему быть чем-либо во всём том, в чём оно есть ничто ничему, — ни часть, ни что бы то ни было иное. — Явно, что так. — Стало быть, часть есть часть не многого, и не всего, а некоторой одной идеи и чего-то одного, что мы называем целым, которое из всего стало"}, "157e": {"g": "ἑνός τινος ὃ καλοῦμεν ὅλον, ἐξ ἁπάντων ἓν τέλειον γεγονός, τούτου μόριον ἂν τὸ μόριον εἴη. παντάπασι μὲν οὖν. εἰ ἄρα τἆλλα μόρια ἔχει, κἂν τοῦ ὅλου τε καὶ ἑνὸς μετέχοι. πάνυ γε. ἓν ἄρα ὅλον τέλειον μόρια ἔχον ἀνάγκη εἶναι τἆλλα τοῦ ἑνός. ἀνάγκη. καὶ μὴν καὶ περὶ τοῦ μορίου γε ἑκάστου ὁ αὐτὸς λόγος· καὶ γὰρ τοῦτο ἀνάγκη μετέχειν", "r": "совершенным одним; этого-то частью должна быть часть. — Без сомнения, так. — Следовательно, если иное имеет части, то оно будет также причастно целого и одного. — Конечно. — Стало быть, иное относительно одного необходимо есть одно совершенное, целое, имеющее части. — Необходимо. — Да и для каждой части-то тот же закон; ведь и ей необходимо быть причастною одного: если, то есть, каждая из них — часть, то каждое-то означает, конечно, нечто одно, отделенное от инаго и существующее по"}, "158a": {"g": "τοῦ ἑνός. εἰ γὰρ ἕκαστον αὐτῶν μόριόν ἐστι, τό γε ἕκαστον εἶναι ἓν δήπου σημαίνει, ἀφωρισμένον μὲν τῶν ἄλλων, καθʼ αὑτὸ δὲ ὄν, εἴπερ ἕκαστον ἔσται. ὀρθῶς. μετέχοι δέ γε ἂν τοῦ ἑνὸς δῆλον ὅτι ἄλλο ὂν ἢ ἕν· οὐ γὰρ ἂν μετεῖχεν, ἀλλʼ ἦν ἂν αὐτὸ ἕν. νῦν δὲ ἑνὶ μὲν εἶναι πλὴν αὐτῷ τῷ ἑνὶ ἀδύνατόν που. ἀδύνατον. μετέχειν δέ γε τοῦ ἑνὸς ἀνάγκη τῷ τε ὅλῳ καὶ τῷ μορίῳ. τὸ μὲν γὰρ ἓν ὅλον ἔσται, οὗ μόρια τὰ μόρια· τὸ δʼ αὖ ἕκαστον ἓν μόριον τοῦ ὅλου, ὃ ἂν ᾖ", "r": "себе, как скоро уж будет каждое. — Правильно. — Но если оно будет причастно одного, то явно, что будет причастно как иное, а не одно; ибо иначе не приобщалось бы, а было бы самым одним; быть же чему одному, кроме самого одного, вероятно, невозможно. — Невозможно. — Но приобщаться-то одного необходимо и целому, и части: первое будет оттого одним целым, которого частями будут части; а каждая часть — опять одной частью целого, которое будет целым части. — Так. — То, что причастно одного, не будет ли приобщаться как отличное от него? — Ка̀к же иначе. — Отличное же от одного, будет, вероятно, многое;"}, "158b": {"g": "μόριον ὅλου. οὕτως. οὐκοῦν ἕτερα ὄντα τοῦ ἑνὸς μεθέξει τὰ μετέχοντα αὐτοῦ; πῶς δʼ οὔ; τὰ δʼ ἕτερα τοῦ ἑνὸς πολλά που ἂν εἴη· εἰ γὰρ μήτε ἓν μήτε ἑνὸς πλείω εἴη τἆλλα τοῦ ἑνός, οὐδὲν ἂν εἴη. οὐ γὰρ οὖν. ἐπεὶ δέ γε πλείω ἑνός ἐστι τά τε τοῦ ἑνὸς μορίου καὶ τὰ τοῦ ἑνὸς ὅλου μετέχοντα, οὐκ ἀνάγκη ἤδη πλήθει ἄπειρα εἶναι αὐτά γε ἐκεῖνα τὰ μεταλαμβάνοντα τοῦ ἑνός; πῶς; ὧδε ἴδωμεν. ἄλλο τι οὐχ ἓν ὄντα οὐδὲ μετέχοντα τοῦ ἑνὸς τότε, ὅτε μεταλαμβάνει αὐτοῦ, μεταλαμβάνει; δῆλα δή.", "r": "потому что если бы иное относительно одного было и не одно, и не больше одного, то оно было бы ничто. — Конечно, так. — А когда того, что̀ причастно одной части и одного целого, больше одного, то не необходимо ли уже тому-то самому, принимающему одно, быть, по количеству, беспредельным? — Как? — Посмотрим вот с какой стороны: не правда ли, что, тогда как вещь принимает одно, она принимает его еще не будучи ни одним, ни причастным одного?"}, "158c": {"g": "οὐκοῦν πλήθη ὄντα, ἐν οἷς τὸ ἓν οὐκ ἔνι; πλήθη μέντοι. τί οὖν; εἰ ἐθέλοιμεν τῇ διανοίᾳ τῶν τοιούτων ἀφελεῖν ὡς οἷοί τέ ἐσμεν ὅτι ὀλίγιστον, οὐκ ἀνάγκη καὶ τὸ ἀφαιρεθὲν ἐκεῖνο, εἴπερ τοῦ ἑνὸς μὴ μετέχοι, πλῆθος εἶναι καὶ οὐχ ἕν; ἀνάγκη. οὐκοῦν οὕτως ἀεὶ σκοποῦντες αὐτὴν καθʼ αὑτὴν τὴν ἑτέραν φύσιν τοῦ εἴδους ὅσον ἂν αὐτῆς ἀεὶ ὁρῶμεν ἄπειρον ἔσται πλήθει; παντάπασι μὲν οὖν. καὶ μὴν ἐπειδάν γε", "r": "— Явно. — Но будучи многим, в чём нет одного? — Конечно, многим. — Так что же? если бы мы захотели мысленно отделить от этого самое, сколько возможно, малое, то не необходимо ли, чтобы и это отделенное, так как оно не причастно одного, было многим, а не одним? — Необходимо. — И для того, кто всегда так наблюдает отличную природу вида, самою по себе, сколько можем мы всякий раз ее видеть, не будет ли она, по множеству, беспредельна? — Без сомнения, так. — А когда каждая часть становится одною частью, тогда части имеют уже предел"}, "158d": {"g": "ἓν ἕκαστον μόριον μόριον γένηται, πέρας ἤδη ἔχει πρὸς ἄλληλα καὶ πρὸς τὸ ὅλον, καὶ τὸ ὅλον πρὸς τὰ μόρια. κομιδῇ μὲν οὖν. τοῖς ἄλλοις δὴ τοῦ ἑνὸς συμβαίνει ἐκ μὲν τοῦ ἑνὸς καὶ ἐξ ἑαυτῶν κοινωνησάντων, ὡς ἔοικεν, ἕτερόν τι γίγνεσθαι ἐν ἑαυτοῖς, ὃ δὴ πέρας παρέσχε πρὸς ἄλληλα· ἡ δʼ ἑαυτῶν φύσις καθʼ ἑαυτὰ ἀπειρίαν. φαίνεται. οὕτω δὴ τὰ ἄλλα τοῦ ἑνὸς καὶ ὅλα καὶ κατὰ μόρια ἄπειρά τέ ἐστι καὶ πέρατος μετέχει. πάνυ γε.", "r": "и одна в отношении к другой и в отношении к целому, равно как целое — в отношении к частям. — Совершенно так. — Значит, иному относительно одного, когда произойдет общение самого его с одним, приходится, как видно, проявлять нечто отличное в самом себе, что̀ дает предел одному в отношении к другому, тогда как природа инаго сама по себе дает беспредельность. — Явно. — Таким образом иные вещи относительно одного, и как целое, и как частичное, и беспредельны, и причастны предела. — Конечно. — Не подобны ли также и не неподобны —"}, "158e": {"g": "οὐκοῦν καὶ ὅμοιά τε καὶ ἀνόμοια ἀλλήλοις τε καὶ ἑαυτοῖς; πῇ δή; ἧι μέν που ἄπειρά ἐστι κατὰ τὴν ἑαυτῶν φύσιν πάντα, ταὐτὸν πεπονθότα ἂν εἴη ταύτῃ. πάνυ γε. καὶ μὴν ᾗ γε ἅπαντα πέρατος μετέχει, καὶ ταύτῃ πάντʼ ἂν εἴη ταὐτὸν πεπονθότα. πῶς δʼ οὔ; ᾗ δέ γε πεπερασμένα τε εἶναι καὶ ἄπειρα πέπονθεν, ἐναντία πάθη ἀλλήλοις ὄντα ταῦτα τὰ", "r": "как одна другой, так и самим себе? — Каким же образом? — Поскольку они, по своей природе, вероятно, беспредельны, постольку все будут иметь те же свойства. — Конечно. — И поскольку все-то причастны предела, постольку, равным образом, будут иметь те же свойства. — Ка̀к не будут. — Но если приходится им быть в состоянии определенности и беспредельности, то, имея те свойства, они, по своим свойствам, будут взаимно противны. — Да. — Противное"}, "159a": {"g": "πάθη πέπονθεν. ναί. τὰ δʼ ἐναντία γε ὡς οἷόν τε ἀνομοιότατα. τί μήν; κατὰ μὲν ἄρα ἑκάτερον τὸ πάθος ὅμοια ἂν εἴη αὐτά τε αὑτοῖς καὶ ἀλλήλοις, κατὰ δʼ ἀμφότερα ἀμφοτέρως ἐναντιώτατά τε καὶ ἀνομοιότατα. κινδυνεύει. οὕτω δὴ τὰ ἄλλα αὐτά τε αὑτοῖς καὶ ἀλλήλοις ὅμοιά τε καὶ ἀνόμοια ἂν εἴη. οὕτως. καὶ ταὐτὰ δὴ καὶ ἕτερα ἀλλήλων, καὶ κινούμενα καὶ ἑστῶτα, καὶ πάντα τὰ ἐναντία πάθη οὐκέτι χαλεπῶς εὑρήσομεν πεπονθότα τἆλλα τοῦ ἑνός, ἐπείπερ καὶ", "r": "же всего более не подобно. — Как же. — Стало быть, по каждому из обоих этих состояний, они будут подобны и самим себе, и одна другой, и по обоим, в том и другом отношении, окажутся также самыми противными и самыми не подобными. — Должно быть. — Таким образом иные вещи и сами себе, и одни другим будут подобны и не подобны. — Так. — И будут те же, и взаимно различны, находиться и в движении, и в покое, и уже не трудно"}, "159b": {"g": "ταῦτα ἐφάνη πεπονθότα. ὀρθῶς λέγεις. οὐκοῦν, εἰ ταῦτα μὲν ἤδη ἐῷμεν ὡς φανερά, ἐπισκοποῖμεν δὲ πάλιν ἓν εἰ ἔστιν , ἆρα καὶ οὐχ οὕτως ἔχει τὰ ἄλλα τοῦ ἑνὸς ἢ οὕτω μόνον; πάνυ μὲν οὖν. λέγωμεν δὴ ἐξ ἀρχῆς ἓν εἰ ἔστι , τί χρὴ τὰ ἄλλα τοῦ ἑνὸς πεπονθέναι. λέγωμεν γάρ. ἆρʼ οὖν οὐ χωρὶς μὲν τὸ ἓν τῶν ἄλλων, χωρὶς δὲ τἆλλα τοῦ ἑνὸς εἶναι; τί δή; ὅτι που οὐκ ἔστι παρὰ ταῦτα ἕτερον, ὃ ἄλλο μέν ἐστι τοῦ ἑνός, ἄλλο δὲ τῶν ἄλλων·", "r": "найти, что иные вещи относительно одного обнаружат все противные свойства, если уж оказалось, что они испытывают эти. — Ты правильно говоришь.\n\nНо оставим это, как дело уже ясное, и рассмотримопять, — если есть одно, не иначе ли еще представится нам иное относительно одного, или только так? — Конечно, рассмотрим. — Скажем же сначала, что̀, — если есть одно, — должно испытывать иное относительно одного. — Да, скажем. — Одно не есть ли особое от инаго, и иное не есть ли особое от одного? — Почему так? — Потому что, кроме этого, нет ничего другого, что̀ было бы иное относительно"}, "159c": {"g": "πάντα γὰρ εἴρηται, ὅταν ῥηθῇ τό τε ἓν καὶ τἆλλα. πάντα γάρ. οὐκ ἄρα ἔτʼ ἔστιν ἕτερον τούτων, ἐν ᾧ τό τε ἓν ἂν εἴη τῷ αὐτῷ καὶ τἆλλα. οὐ γάρ. οὐδέποτε ἄρα ἐν ταὐτῷ ἐστι τὸ ἓν καὶ τἆλλα. οὐκ ἔοικεν. χωρὶς ἄρα; ναί. οὐδὲ μὴν μόριά γε ἔχειν φαμὲν τὸ ὡς ἀληθῶς ἕν. πῶς γάρ; οὔτʼ ἄρα ὅλον εἴη ἂν τὸ ἓν ἐν τοῖς ἄλλοις οὔτε μόρια αὐτοῦ, εἰ χωρίς τέ ἐστι τῶν ἄλλων καὶ μόρια μὴ ἔχει. πῶς", "r": "одного, и иное — относительно иных вещей: ведь когда сказано: одно и иное, — сказано всё. — Конечно, всё. — Стало быть, нет более ничего, отличного от этих, в чём, как том же, было бы одно и иное. — Конечно, нет. — Следовательно, одно и иное никогда не находятся в том же. — Походит, что нет. — Стало быть, особо? — Да. — А истинное одно, сказали мы, частей-то не имеет. — Как иметь? — Следовательно, одно не будет в ином ни как целое, ни частями, если оно есть особое от инаго и не имеет частей. — Как быть!"}, "159d": {"g": "γάρ; οὐδενὶ ἄρα τρόπῳ μετέχοι ἂν τἆλλα τοῦ ἑνός, μήτε κατὰ μόριόν τι αὐτοῦ μήτε κατὰ ὅλον μετέχοντα. οὐκ ἔοικεν. οὐδαμῇ ἄρα ἓν τἆλλά ἐστιν, οὐδʼ ἔχει ἐν ἑαυτοῖς ἓν οὐδέν. οὐ γὰρ οὖν. οὐδʼ ἄρα πολλά ἐστι τἆλλα· ἓν γὰρ ἂν ἦν ἕκαστον αὐτῶν μόριον τοῦ ὅλου, εἰ πολλὰ ἦν· νῦν δὲ οὔτε ἓν οὔτε πολλὰ οὔτε ὅλον οὔτε μόριά ἐστι τἆλλα τοῦ ἑνός, ἐπειδὴ αὐτοῦ οὐδαμῇ μετέχει. ὀρθῶς. οὐδʼ ἄρα δύο οὐδὲ τρία οὔτε αὐτά ἐστι τὰ ἄλλα οὔτε ἔνεστιν ἐν αὐτοῖς,", "r": "— Поэтому иное никаким образом не причастно одного, коль скоро не причастно ни какой-нибудь части его, ни целого. — Походит, что нет. — Стало быть, иное никаким образом не есть одно и не имеет в себе никакого единства. — Конечно, не имеет. — Следовательно, иное не есть и многое: ибо каждая часть его была бы одною частью целого, если бы их было много. Значит, иное, так как оно никаким образом не причастно одного, не есть ни одно, ни многое, ни целое, ни частичное. — Правильно. — Стало быть,"}, "159e": {"g": "εἴπερ τοῦ ἑνὸς πανταχῇ στέρεται. οὕτως. οὐδὲ ὅμοια ἄρα καὶ ἀνόμοια οὔτε αὐτά ἐστι τῷ ἑνὶ τὰ ἄλλα, οὔτε ἔνεστιν ἐν αὐτοῖς ὁμοιότης καὶ ἀνομοιότης· εἰ γὰρ ὅμοια καὶ ἀνόμοια αὐτὰ εἴη ἢ ἔχοι ἐν ἑαυτοῖς ὁμοιότητα καὶ ἀνομοιότητα, δύο που εἴδη ἐναντία ἀλλήλοις ἔχοι ἂν ἐν ἑαυτοῖς τὰ ἄλλα τοῦ ἑνός. φαίνεται. ἦν δέ γε ἀδύνατον δυοῖν τινοῖν μετέχειν ἃ μηδʼ ἑνὸς μετέχοι. ἀδύνατον. οὔτʼ ἄρα ὅμοια οὔτʼ ἀνόμοιά ἐστιν οὔτʼ ἀμφότερα τἆλλα.", "r": "иное, если оно везде лишено одного, не есть ни два, ни три, — ни само по себе, ни содержит их. — Так. — Посему иное, как само ни подобно, ни не подобно одному, так и в нём не заключается ни подобия, ни неподобия; потому что если бы иное относительно одного было подобно и не подобно, или имело в себе подобие и неподобие, то заключало бы в себе, вероятно, два взаимно противных вида. — Явно. — Но быть не может, чтобы иное причастно было чего-нибудь двоичного, когда оно не причастно ничего. — Невозможно. — Стало быть, иное не есть ни подобное,"}, "160a": {"g": "ὅμοια μὲν γὰρ ἂν ὄντα ἢ ἀνόμοια ἑνὸς ἂν τοῦ ἑτέρου εἴδους μετέχοι, ἀμφότερα δὲ ὄντα δυοῖν τοῖν ἐναντίοιν· ταῦτα δὲ ἀδύνατον ἐφάνη. ἀληθῆ. οὐδʼ ἄρα τὰ αὐτὰ οὐδʼ ἕτερα, οὐδὲ κινούμενα οὐδὲ ἑστῶτα, οὐδὲ γιγνόμενα οὐδὲ ἀπολλύμενα, οὐδὲ μείζω οὐδὲ ἐλάττω οὐδὲ ἴσα· οὐδὲ ἄλλο οὐδὲν πέπονθε τῶν τοιούτων· εἰ γάρ τι τοιοῦτον πεπονθέναι ὑπομένει τὰ ἄλλα, καὶ ἑνὸς καὶ δυοῖν καὶ τριῶν καὶ περιττοῦ καὶ ἀρτίου μεθέξει, ὧν αὐτοῖς ἀδύνατον", "r": "ни не подобное, ни то и другое вместе; потому что, будучи подобным или не подобным, оно было бы причастно одного которого-нибудь вида, а будучи тем и другим вместе, было бы причастно двух противных, — что оказалось невозможным. — Правда. — Поэтому оно не то же и не различно, не движется и не стоит, не рождается и не погибает, не есть ни больше, ни меньше, ни равно, и не имеет иных подобных свойств; ибо если бы иное было в состоянии испытывать что-нибудь такое, то приобщалось бы и одного, и двух, и трех, и нечета и чета, — чего иному, как скоро оно совершенно и всячески лишено одного-то, быть причастным оказалось делом невозможным. — Сущая правда. — Таким-то"}, "160b": {"g": "ἐφάνη μετέχειν τοῦ ἑνός γε πάντῃ πάντως στερομένοις. ἀληθέστατα. οὕτω δὴ ἓν εἰ ἔστιν, πάντα τέ ἐστι τὸ ἓν καὶ οὐδὲ ἕν ἐστι καὶ πρὸς ἑαυτὸ καὶ πρὸς τὰ ἄλλα ὡσαύτως. παντελῶς μὲν οὖν. εἶεν· εἰ δὲ δὴ μὴ ἔστι τὸ ἕν, τί χρὴ συμβαίνειν ἆρʼ οὐ σκεπτέον μετὰ τοῦτο; σκεπτέον γάρ. τίς οὖν ἂν εἴη αὕτη ἡ ὑπόθεσις, εἰ ἓν μὴ ἔστιν ; ἆρά τι διαφέρει τῆσδε, εἰ μὴ ἓν μὴ ἔστιν ; διαφέρει μέντοι. διαφέρει μόνον, ἢ καὶ πᾶν", "r": "образом, если есть одно, то оно и есть всё, и не есть одно — ни для себя, ни также для инаго. — Совершенно справедливо. —\n\nПусть. Но что должно произойти, если одного нет? не рассмотреть ли теперь и этого? — Да, надобно рассмотреть. — Так что же это будет за предположение: если одного нет? отличается ли оно от этого: если не одного нет? — Конечно, отличается. — Различны ли только, или"}, "160c": {"g": "τοὐναντίον ἐστὶν εἰπεῖν εἰ μὴ ἓν μὴ ἔστι τοῦ εἰ ἓν μὴ ἔστιν ; πᾶν τοὐναντίον. τί δʼ εἴ τις λέγοι εἰ μέγεθος μὴ ἔστιν ἢ σμικρότης μὴ ἔστιν ἤ τι ἄλλο τῶν τοιούτων, ἆρα ἐφʼ ἑκάστου ἂν δηλοῖ ὅτι ἕτερόν τι λέγοι τὸ μὴ ὄν; πάνυ γε. οὐκοῦν καὶ νῦν δηλοῖ ὅτι ἕτερον λέγει τῶν ἄλλων τὸ μὴ ὄν, ὅταν εἴπῃ ἓν εἰ μὴ ἔστι , καὶ ἴσμεν ὃ λέγει; ἴσμεν. πρῶτον μὲν ἄρα γνωστόν τι λέγει, ἔπειτα ἕτερον τῶν ἄλλων, ὅταν εἴπῃ ἕν, εἴτε τὸ εἶναι αὐτῷ προσθεὶς εἴτε", "r": "совершенно противны будут положения: если не одного нет, и если одного нет? — Совершенно противны. — Что же, когда кто скажет: если великости нет, или малости нет, или что-нибудь иное подобное, — не покажет ли он каждым таким положением, что под не существующим разумеет нечто отличное? — Конечно. — Не покажет ли он и теперь, что под не существующим разумеет нечто отличное от другого, когда полагает: если одного нет? И знаем ли мы, что̀ говорит он? — Знаем. — Стало быть, он говорит, во-первых, о чём-то подлежащем знанию, потом, об отличном от иных вещей, если уж полагает одно, — бытие ли приложит к этому, или небытие:"}, "160d": {"g": "τὸ μὴ εἶναι· οὐδὲν γὰρ ἧττον γιγνώσκεται, τί τὸ λεγόμενον μὴ εἶναι, καὶ ὅτι διάφορον τῶν ἄλλων. ἢ οὔ; ἀνάγκη. ὧδε ἄρα λεκτέον ἐξ ἀρχῆς, ἓν εἰ μὴ ἔστι , τί χρὴ εἶναι. πρῶτον μὲν οὖν αὐτῷ τοῦτο ὑπάρχειν δεῖ, ὡς ἔοικεν, εἶναι αὐτοῦ ἐπιστήμην, ἢ μηδὲ ὅτι λέγεται γιγνώσκεσθαι, ὅταν τις εἴπῃ ἓν εἰ μὴ ἔστιν . ἀληθῆ. οὐκοῦν καὶ τὰ ἄλλα ἕτερα αὐτοῦ εἶναι, ἢ μηδὲ ἐκεῖνο ἕτερον τῶν ἄλλων λέγεσθαι; πάνυ γε. καὶ ἑτεροιότης ἄρα ἐστὶν αὐτῷ πρὸς τῇ ἐπιστήμῃ.", "r": "ведь что полагается не существующим, познается оттого ничуть не менее, как нечто, и притом отличное от иных вещей. Или нет? — Необходимо. — Итак, уже на первых порах надобно сказать вот что: если одного нет, то что̀ (оно) должно быть? Во-первых, ему, как видно, надобно приписать то, что относительно его есть познание, а иначе и не знали бы, о чём говорится, когда бы кто полагал «если одного нет». — Правда. — Потом, не то ли, что от него отлично прочее? — а иначе и оно не может быть называемо отличным от прочих вещей. — Конечно. — Стало быть, кроме познания, приложимо к нему и отличие. Ведь"}, "160e": {"g": "οὐ γὰρ τὴν τῶν ἄλλων ἑτεροιότητα λέγει, ὅταν τὸ ἓν ἕτερον τῶν ἄλλων λέγῃ, ἀλλὰ τὴν ἐκείνου. φαίνεται. καὶ μὴν τοῦ γε ἐκείνου καὶ τοῦ τινὸς καὶ τούτου καὶ τούτῳ καὶ τούτων καὶ πάντων τῶν τοιούτων μετέχει τὸ μὴ ὂν ἕν· οὐ γὰρ ἂν τὸ ἓν ἐλέγετο οὐδʼ ἂν τοῦ ἑνὸς ἕτερα, οὐδʼ ἐκείνῳ ἄν τι ἦν οὐδʼ ἐκείνου, οὐδʼ ἄν τι ἐλέγετο, εἰ μήτε τοῦ τινὸς αὐτῷ μετῆν μήτε τῶν ἄλλων τούτων. ὀρθῶς. εἶναι μὲν δὴ τῷ ἑνὶ οὐχ οἷόν τε, εἴπερ γε μὴ ἔστι, μετέχειν δὲ πολλῶν οὐδὲν", "r": "тот говорит об отличии не в иных вещах, когда одно называет отличным от иных вещей, а об отличии именно его. — Явно. — Да это не существующее одно причастно и того, и чего-нибудь, и этого, и этому, и этих, и всего подобного; потому что иначе не могло бы быть и речи об одном и от одного отличном; иначе и в нём ничего не было бы, и ему ничто не принадлежало бы, и оно не выдавалось бы за нечто, — если бы не причастно было ни чего-нибудь, ни инаго подобного, — Правильно. — Быть то одному нельзя, если действительно его нет: но одному быть причастным многого ничто не мешает, и"}, "161a": {"g": "κωλύει, ἀλλὰ καὶ ἀνάγκη, εἴπερ τό γε ἓν ἐκεῖνο καὶ μὴ ἄλλο μὴ ἔστιν. εἰ μέντοι μήτε τὸ ἓν μήτʼ ἐκεῖνο μὴ ἔσται, ἀλλὰ περὶ ἄλλου του ὁ λόγος, οὐδὲ φθέγγεσθαι δεῖ οὐδέν· εἰ δὲ τὸ ἓν ἐκεῖνο καὶ μὴ ἄλλο ὑπόκειται μὴ εἶναι, καὶ τοῦ ἐκείνου καὶ ἄλλων πολλῶν ἀνάγκη αὐτῷ μετεῖναι. καὶ πάνυ γε. καὶ ἀνομοιότης ἄρα ἐστὶν αὐτῷ πρὸς τὰ ἄλλα· τὰ γὰρ ἄλλα τοῦ ἑνὸς ἕτερα ὄντα ἑτεροῖα καὶ εἴη ἄν. ναί. τὰ δʼ ἑτεροῖα οὐκ ἀλλοῖα; πῶς δʼ οὔ; τὰ δʼ ἀλλοῖα οὐκ", "r": "даже необходимо, как скоро нет именно того одного, а не инаго. Конечно, если не будет ни одного, ни того, но будет речь (также) об ином, то не следует ничего и произносить. Напротив, когда предполагается не существующим то̀ одно, а не иное, — необходимо быть ему причастным и того, и инаго многого. — Конечно. — Принадлежит ему, стало быть, и неподобие в отношении к иному; потому что иное, как чуждое одному, будет от него отлично. — Да. — А отличное не инородно ли? — Ка̀к не инородно! — Инородное же не не подобно ли? — Конечно, не подобно. — Но если"}, "161b": {"g": "ἀνόμοια; ἀνόμοια μὲν οὖν. οὐκοῦν εἴπερ τῷ ἑνὶ ἀνόμοιά ἐστι, δῆλον ὅτι ἀνομοίῳ τά γε ἀνόμοια ἀνόμοια ἂν εἴη. δῆλον. εἴη δὴ ἂν καὶ τῷ ἑνὶ ἀνομοιότης, πρὸς ἣν τὰ ἄλλα ἀνόμοια αὐτῷ ἐστιν. ἔοικεν. εἰ δὲ δὴ τῶν ἄλλων ἀνομοιότης ἔστιν αὐτῷ, ἆρʼ οὐκ ἀνάγκη ἑαυτοῦ ὁμοιότητα αὐτῷ εἶναι; πῶς; εἰ ἑνὸς ἀνομοιότης ἔστι τῷ ἑνί, οὐκ ἄν που περὶ τοῦ τοιούτου ὁ λόγος εἴη οἵου τοῦ ἑνός, οὐδʼ ἂν ἡ ὑπόθεσις εἴη περὶ ἑνός, ἀλλὰ περὶ ἄλλου ἢ ἑνός. πάνυ", "r": "оно не подобно одному, то явно, что не подобное-то будет не подобно не подобному. — Явно. — Значит, и в одном будет неподобие, в силу которого иное ему не подобно. — Походит. — А если есть в нём неподобие в отношении к иному, то не необходимо ли быть в нём подобию по отношению к себе? — Как? — Если есть в одном неподобие одному, то не могло бы быть и речи о таком предмете как об одном, и предположение касалось бы не одного, а"}, "161c": {"g": "γε. οὐ δεῖ δέ γε. οὐ δῆτα. δεῖ ἄρα ὁμοιότητα τῷ ἑνὶ αὐτοῦ ἑαυτῷ εἶναι. δεῖ. καὶ μὴν οὐδʼ αὖ ἴσον γʼ ἐστὶ τοῖς ἄλλοις· εἰ γὰρ εἴη ἴσον, εἴη τε ἂν ἤδη καὶ ὅμοιον ἂν εἴη αὐτοῖς κατὰ τὴν ἰσότητα. ταῦτα δʼ ἀμφότερα ἀδύνατα, εἴπερ μὴ ἔστιν ἕν. ἀδύνατα. ἐπειδὴ δὲ οὐκ ἔστι τοῖς ἄλλοις ἴσον, ἆρα οὐκ ἀνάγκη καὶ τἆλλα ἐκείνῳ μὴ ἴσα εἶναι; ἀνάγκη. τὰ δὲ μὴ ἴσα οὐκ ἄνισα; ναί. τὰ δὲ ἄνισα οὐ τῷ ἀνίσῳ ἄνισα; πῶς δʼ οὔ; καὶ ἀνισότητος δὴ μετέχει τὸ ἕν,", "r": "(чего-либо) инаго вразсуждении одного. — Конечно. — А ведь не должно̀ бы. — Конечно, нет. — Стало быть, одному надобно иметь подобие самому с собою. — Надобно. — Да оно опять и не равно иному; потому что если бы было равно, то уже было бы и, но равности, было бы и подобно иному; а оба эти положения, как скоро одного нет, невозможны. — Невозможны. — Но так как оно не равно иному, то не необходимо ли, чтобы и иное было не равно ему? — Необходимо. — А то, что̀ не равно, не есть ли не равное? — Да. — Не равное же не есть ли не равное не равному? — Ка̀к же иначе. — Так что одно причастно и неравности, в силу которой"}, "161d": {"g": "πρὸς ἣν τἆλλα αὐτῷ ἐστιν ἄνισα; μετέχει. ἀλλὰ μέντοι ἀνισότητός γε ἐστὶ μέγεθός τε καὶ σμικρότης. ἔστι γάρ. ἔστιν ἄρα καὶ μέγεθός τε καὶ σμικρότης τῷ τοιούτῳ ἑνί; κινδυνεύει. μέγεθος μὴν καὶ σμικρότης ἀεὶ ἀφέστατον ἀλλήλοιν. πάνυ γε. μεταξὺ ἄρα τι αὐτοῖν ἀεί ἐστιν. ἔστιν. ἔχεις οὖν τι ἄλλο εἰπεῖν μεταξὺ αὐτοῖν ἢ ἰσότητα; οὔκ, ἀλλὰ τοῦτο. ὅτῳ ἄρα ἔστι μέγεθος καὶ σμικρότης, ἔστι καὶ ἰσότης αὐτῷ μεταξὺ τούτοιν οὖσα.", "r": "иное ему не равно? — Причастно. — Но ведь неравность-то есть великость и малость. — Да. — Стало быть, великость и малость тоже есть в таком одном. — Должно быть. — Однакож великость и малость всегда далеки одна от другой. — Конечно. — Стало быть, между ними всегда есть что-нибудь. — Есть. — Так можешь ли указать между ними что-нибудь иное, кроме равности? — Нет, только это. — Следовательно, в чём есть великость и малость, в том есть и находящаяся между ними равность. — Явно. —"}, "161e": {"g": "φαίνεται. τῷ δὴ ἑνὶ μὴ ὄντι, ὡς ἔοικε, καὶ ἰσότητος ἂν μετείη καὶ μεγέθους καὶ σμικρότητος. ἔοικεν. καὶ μὴν καὶ οὐσίας γε δεῖ αὐτὸ μετέχειν πῃ. πῶς δή; ἔχειν αὐτὸ δεῖ οὕτως ὡς λέγομεν· εἰ γὰρ μὴ οὕτως ἔχει, οὐκ ἂν ἀληθῆ λέγοιμεν ἡμεῖς λέγοντες τὸ ἓν μὴ εἶναι· εἰ δὲ ἀληθῆ, δῆλον ὅτι ὄντα αὐτὰ λέγομεν. ἢ οὐχ οὕτως; οὕτω μὲν οὖν. ἐπειδὴ δέ φαμεν ἀληθῆ λέγειν, ἀνάγκη", "r": "Так в одном не существующем имеются, как видно, и равность, и великость, и малость. — Походит. — Но, конечно, оно должно некоторым образом быть причастно и сущности. — Как же это? — Надо, чтоб это было так, как говорим: ведь если б оно было не так, мы говорили бы неправду, полагая, что одного нет (μὴ εἶναι); а когда правду, — явно, что говорим о сущем. Или не так? — Конечно, так. — Если мы полагаем, что говорим правду, то"}, "162a": {"g": "ἡμῖν φάναι καὶ ὄντα λέγειν. ἀνάγκη. ἔστιν ἄρα, ὡς ἔοικε, τὸ ἓν οὐκ ὄν· εἰ γὰρ μὴ ἔσται μὴ ὄν, ἀλλά πῃ τοῦ εἶναι ἀνήσει πρὸς τὸ μὴ εἶναι, εὐθὺς ἔσται ὄν. παντάπασι μὲν οὖν. δεῖ ἄρα αὐτὸ δεσμὸν ἔχειν τοῦ μὴ εἶναι τὸ εἶναι μὴ ὄν, εἰ μέλλει μὴ εἶναι, ὁμοίως ὥσπερ τὸ ὂν τὸ μὴ ὂν ἔχειν μὴ εἶναι, ἵνα τελέως αὖ εἶναι ᾖ· οὕτως γὰρ ἂν τό τε ὂν μάλιστʼ ἂν εἴη καὶ τὸ μὴ ὂν οὐκ ἂν εἴη, μετέχοντα τὸ μὲν ὂν οὐσίας τοῦ εἶναι ὄν, μὴ οὐσίας δὲ τοῦ μὴ εἶναι μὴ", "r": "необходимо нам полагать, что говорим и о сущем. — Необходимо. — Есть, стало быть, как видно, одно не существующее; потому что если не существующего не будет, — если, то есть, оно потеряет что-нибудь из бытия в пользу небытия, — то вдруг станет существующим. — Без сомнения, так. — Следовательно, чтобы не быть, оно должно связываться в небытии — бытием небытия, подобно тому, как существующее, чтобы совершенно быть, должно связываться в бытии — небытием небытия; ибо так-то особенно и существующее будет, и не существующего не будет, — когда, то есть, существующее будет причастно бытности быть существующим и небытности быть не существующим, — если уж имеет быть совершенно, — и когда не существующее будет причастно небытности не быть не существующим и бытности быть не"}, "162b": {"g": "ὄν, εἰ μέλλει τελέως εἶναι, τὸ δὲ μὴ ὂν μὴ οὐσίας μὲν τοῦ μὴ εἶναι μὴ ὄν, οὐσίας δὲ τοῦ εἶναι μὴ ὄν, εἰ καὶ τὸ μὴ ὂν αὖ τελέως μὴ ἔσται. ἀληθέστατα. οὐκοῦν ἐπείπερ τῷ τε ὄντι τοῦ μὴ εἶναι καὶ τῷ μὴ ὄντι τοῦ εἶναι μέτεστι, καὶ τῷ ἑνί, ἐπειδὴ οὐκ ἔστι, τοῦ εἶναι ἀνάγκη μετεῖναι εἰς τὸ μὴ εἶναι. ἀνάγκη. καὶ οὐσία δὴ φαίνεται τῷ ἑνί, εἰ μὴ ἔστιν. φαίνεται. καὶ μὴ οὐσία ἄρα, εἴπερ μὴ ἔστιν. πῶς δʼ οὔ; οἷόν τε οὖν τὸ ἔχον πως μὴ ἔχειν οὕτω, μὴ μεταβάλλον ἐκ ταύτης τῆς ἕξεως; οὐχ οἷόν τε. πᾶν ἄρα τὸ τοιοῦτον", "r": "существующим, — иначе и не существующего в собственном смысле опять не будет. — Весьма справедливо. — Поэтому, когда существующее причастно небытия, а не существующее — бытия, то необходимо и одному, если его нет, быть причастным бытия, чтобы не быть. — Необходимо. — Так и для одного открывается сущность, если его нет. — Открывается. — Стало быть, и несущность, если его нет. — Как же. — Возможно ли же, чтобы что-нибудь, будучи каким-либо, было не таким, не переходя из этого состояния? — Невозможно. — Следовательно, всё указывает на"}, "162c": {"g": "μεταβολὴν σημαίνει, ὃ ἂν οὕτω τε καὶ μὴ οὕτως ἔχῃ. πῶς δʼ οὔ; μεταβολὴ δὲ κίνησις· ἢ τί φήσομεν; κίνησις. οὐκοῦν τὸ ἓν ὄν τε καὶ οὐκ ὂν ἐφάνη; ναί. οὕτως ἄρα καὶ οὐχ οὕτως ἔχον φαίνεται. ἔοικεν. καὶ κινούμενον ἄρα τὸ οὐκ ὂν ἓν πέφανται, ἐπείπερ καὶ μεταβολὴν ἐκ τοῦ εἶναι ἐπὶ τὸ μὴ εἶναι ἔχον. κινδυνεύει. ἀλλὰ μὴν εἰ μηδαμοῦ γέ ἐστι τῶν ὄντων, ὡς οὐκ ἔστιν εἴπερ μὴ ἔστιν, οὐδʼ ἂν μεθίσταιτό ποθέν ποι. πῶς γάρ; οὐκ ἄρα τῷ γε", "r": "такой переход, что является таким и не таким. — Как же. — Переход же назовем движением, или чем? — Движением. — Но не явилось ли нам одно существующим и не существующим? — Да. — Стало быть, оно является таким, и не таким. — Походит. — Значит, одно не существующее оказалось и движущимся, если совершает переход из бытия в небытие. — Должно быть. — Однакож если в ряду-то существ оно нигде не существует, как не существующее, — поколику его нет, — то не может оно и переходить куда бы ни было. — Как может! — Стало быть, под образом"}, "162d": {"g": "μεταβαίνειν κινοῖτʼ ἄν. οὐ γάρ. οὐδὲ μὴν ἐν τῷ αὐτῷ ἂν στρέφοιτο· ταὐτοῦ γὰρ οὐδαμοῦ ἅπτεται. ὂν γὰρ ἐστὶ τὸ ταὐτόν· τὸ δὲ μὴ ὂν ἔν τῳ τῶν ὄντων ἀδύνατον εἶναι. ἀδύνατον γάρ. οὐκ ἄρα τὸ ἕν γε μὴ ὂν στρέφεσθαι ἂν δύναιτο ἐν ἐκείνῳ ἐν ᾧ μὴ ἔστιν. οὐ γὰρ οὖν. οὐδὲ μὴν ἀλλοιοῦταί που τὸ ἓν ἑαυτοῦ, οὔτε τὸ ὂν οὔτε τὸ μὴ ὄν· οὐ γὰρ ἂν ἦν ὁ λόγος ἔτι περὶ τοῦ ἑνός, εἴπερ ἠλλοιοῦτο αὐτὸ ἑαυτοῦ, ἀλλὰ περὶ ἄλλου τινός. ὀρθῶς. εἰ δὲ μήτʼ ἀλλοιοῦται μήτε ἐν ταὐτῷ στρέφεται μήτε μεταβαίνει, ἆρʼ", "r": "перехода, и двигаться. — Не может. — Да нельзя ему и вращаться в том же месте; ибо оно нигде не соприкасается с тожественным: тожественное ведь есть существующее; не существующему же быть в чём существующем невозможно. — Конечно. — Так что одно не существующее не может вращаться в том, в чём его нет. — Не может. — Да одно, вероятно, и не переиначивает себя, ни как существующее, ни как не существующее; потому что если бы оно переиначивалось, то речь была бы уже не об одном, а о чём-нибудь ином. — Правильно. Если же одно и не переиначивается, и не вращается в том же месте, и не переходит, то движется ли еще как-нибудь?"}, "162e": {"g": "ἄν πῃ ἔτι κινοῖτο; πῶς γάρ; τό γε μὴν ἀκίνητον ἀνάγκη ἡσυχίαν ἄγειν, τὸ δὲ ἡσυχάζον ἑστάναι. ἀνάγκη. τὸ ἓν ἄρα, ὡς ἔοικεν, οὐκ ὂν ἕστηκέ τε καὶ κινεῖται. ἔοικεν. καὶ μὴν εἴπερ γε κινεῖται, μεγάλη ἀνάγκη αὐτῷ ἀλλοιοῦσθαι·", "r": "— Как двигаться! — Но не движущемуся-то необходимо быть в покое, а покоющемуся — стоять. — Необходимо. — Стало быть, одно не существующее, как видно, и стоит, и движется. — Походит. — Но если оно движется-то, то крайне необходимо ему переиначиваться; ибо насколько что-нибудь двигалось, настолько бывает уже не таким, каким"}, "163a": {"g": "ὅπῃ γὰρ ἄν τι κινηθῇ, κατὰ τοσοῦτον οὐκέθʼ ὡσαύτως ἔχει ὡς εἶχεν, ἀλλʼ ἑτέρως. οὕτως. κινούμενον δὴ τὸ ἓν καὶ ἀλλοιοῦται. ναί. καὶ μὴν μηδαμῇ γε κινούμενον οὐδαμῇ ἂν ἀλλοιοῖτο. οὐ γάρ. ἧι μὲν ἄρα κινεῖται τὸ οὐκ ὂν ἕν, ἀλλοιοῦται· ᾗ δὲ μὴ κινεῖται, οὐκ ἀλλοιοῦται. οὐ γάρ. τὸ ἓν ἄρα μὴ ὂν ἀλλοιοῦταί τε καὶ οὐκ ἀλλοιοῦται. φαίνεται. τὸ δʼ ἀλλοιούμενον ἆρʼ οὐκ ἀνάγκη γίγνεσθαι μὲν ἕτερον ἢ πρότερον, ἀπόλλυσθαι δὲ ἐκ τῆς", "r": "было, а иным. — Так. — Значит, одно, как движимое, и переиначивается. — Да. — А как вовсе не движимое-то, вовсе и не переиначивалось бы. — Конечно, нет. — Стало быть, одно не существующее, поколику движется, переиначивается, а поколику не движется, не переиначивается. — Конечно, нет. — Следовательно, одно не существующее и переиначивается, и не переиначивается. — Явно. — Переиначивающемуся же не необходимо ли бывать отличным от того, чем оно было прежде, и погибать для состояния прежнего, а не переиначивающемуся — и не рождаться, и не погибать?"}, "163b": {"g": "προτέρας ἕξεως· τὸ δὲ μὴ ἀλλοιούμενον μήτε γίγνεσθαι μήτε ἀπόλλυσθαι; ἀνάγκη. καὶ τὸ ἓν ἄρα μὴ ὂν ἀλλοιούμενον μὲν γίγνεταί τε καὶ ἀπόλλυται, μὴ ἀλλοιούμενον δὲ οὔτε γίγνεται οὔτε ἀπόλλυται· καὶ οὕτω τὸ ἓν μὴ ὂν γίγνεταί τε καὶ ἀπόλλυται, καὶ οὔτε γίγνεται οὔτʼ ἀπόλλυται. οὐ γὰρ οὖν. αὖθις δὴ ἐπὶ τὴν ἀρχὴν ἴωμεν πάλιν ὀψόμενοι εἰ ταὐτὰ ἡμῖν φανεῖται ἅπερ καὶ νῦν ἢ ἕτερα. ἀλλὰ χρή. οὐκοῦν", "r": "— Необходимо. — И одно не существующее, будучи переиначиваемо, стало быть, рождается и погибает, а не переиначиваемое, ни рождается, ни погибает. Таким образом одно не существующее и рождается и погибает, и не рождается и не погибает. — Конечно, так.\n\nОбратимся же опять к началу, и посмотрим, то же ли представится нам, что̀ теперь, или другое. — Да, надобно. — Итак, если одного нет, что̀ должно, говорим, по"}, "163c": {"g": "ἓν εἰ μὴ ἔστι , φαμέν, τί χρὴ περὶ αὐτοῦ συμβαίνειν; ναί. τὸ δὲ μὴ ἔστιν ὅταν λέγωμεν, ἆρα μή τι ἄλλο σημαίνει ἢ οὐσίας ἀπουσίαν τούτῳ ᾧ ἂν φῶμεν μὴ εἶναι; οὐδὲν ἄλλο. πότερον οὖν, ὅταν φῶμεν μὴ εἶναί τι, πὼς οὐκ εἶναί φαμεν αὐτό, πὼς δὲ εἶναι; ἢ τοῦτο τὸ μὴ ἔστι λεγόμενον ἁπλῶς σημαίνει ὅτι οὐδαμῶς οὐδαμῇ ἔστιν οὐδέ πῃ μετέχει οὐσίας τό γε μὴ ὄν; ἁπλούστατα μὲν οὖν. οὔτε ἄρα εἶναι δύναιτο ἂν τὸ μὴ ὂν οὔτε ἄλλως οὐδαμῶς", "r": "отношению к нему оказаться? — Да. — Но когда мы говорим это нет, то иное ли что означается им, как не отсутствие сущности в том, чему мы отказываем в бытии? — Не иное. — Так, полагая, что чего-либо нет, полагаем ли мы некоторым образом его небытие и некоторым — бытие? Или это выражение нет означает просто, что не существующее-то вовсе нигде не есть, и никак не причастно сущности? — Да, совершенно просто. — Стало быть, не"}, "163d": {"g": "οὐσίας μετέχειν. οὐ γάρ. τὸ δὲ γίγνεσθαι καὶ τὸ ἀπόλλυσθαι μή τι ἄλλο ἦν ἢ τὸ μὲν οὐσίας μεταλαμβάνειν, τὸ δʼ ἀπολλύναι οὐσίαν; οὐδὲν ἄλλο. ὧι δέ γε μηδὲν τούτου μέτεστιν, οὔτʼ ἂν λαμβάνοι οὔτʼ ἀπολλύοι αὐτό. πῶς γάρ; τῷ ἑνὶ ἄρα, ἐπειδὴ οὐδαμῇ ἔστιν, οὔτε ἑκτέον οὔτε ἀπαλλακτέον οὔτε μεταληπτέον οὐσίας οὐδαμῶς. εἰκός. οὔτε ἄρα ἀπόλλυται τὸ μὴ ὂν ἓν οὔτε γίγνεται, ἐπείπερ οὐδαμῇ μετέχει οὐσίας. οὐ φαίνεται. οὐδʼ ἄρʼ", "r": "существующее не может ни быть, ни как-нибудь иначе приобщаться сущности. — Конечно, нет. — Но рождаться и погибать иное ли что было, как не воспринимать сущность и не терять ее? — Не иное. — А что̀ ничему этому не причастно, то̀ и не воспринимает, и не теряет сущности. — Как же. — Стало быть, одному, поколику оно вовсе не существует, ни иметь сущность, ни оставить ее, ни переменить никак нельзя. — Естественно. — Следовательно, одно не существующее, поколику никаким образом не причастно сущности,"}, "163e": {"g": "ἀλλοιοῦται οὐδαμῇ· ἤδη γὰρ ἂν γίγνοιτό τε καὶ ἀπολλύοιτο τοῦτο πάσχον. ἀληθῆ. εἰ δὲ μὴ ἀλλοιοῦται, οὐκ ἀνάγκη μηδὲ κινεῖσθαι; ἀνάγκη. οὐδὲ μὴν ἑστάναι φήσομεν τὸ μηδαμοῦ ὄν· τὸ γὰρ ἑστὸς ἐν τῷ αὐτῷ τινι δεῖ ἀεὶ εἶναι. τῷ αὐτῷ· πῶς γὰρ οὔ; οὕτω δὴ αὖ τὸ μὴ ὂν μήτε ποτὲ ἑστάναι μήτε κινεῖσθαι λέγωμεν. μὴ γὰρ οὖν. ἀλλὰ μὴν οὐδʼ ἔστι γε αὐτῷ τι τῶν ὄντων· ἤδη γὰρ ἂν τούτου", "r": "и не погибает, и не рождается. — Явно, что нет. — Стало быть, и никак не переиначивается; потому что, испытывая это, рождалось бы уже и погибало. — Правда. — Если же оно не переиначивается, не необходимо ли ему и не двигаться? — Необходимо. — Однакож, нигде не существуя, оно, скажем, и не стоит; ибо стоящее должно всегда быть в чём-нибудь том же. — В том же, не иначе. — Таким-то образом не существующее, скажем опять, и никогда не стоит, и не движется. — Конечно, нет. — Да и нет таки в нём чего-либо существующего; ибо, причастное существующего,"}, "164a": {"g": "μετέχον ὄντος οὐσίας μετέχοι. δῆλον. οὔτε ἄρα μέγεθος οὔτε σμικρότης οὔτε ἰσότης αὐτῷ ἔστιν. οὐ γάρ. οὐδὲ μὴν ὁμοιότης γε οὐδὲ ἑτεροιότης οὔτε πρὸς αὑτὸ οὔτε πρὸς τἆλλα εἴη ἂν αὐτῷ. οὐ φαίνεται. τί δέ; τἆλλα ἔσθʼ ὅπως ἂν εἴη αὐτῷ, εἰ μηδὲν αὐτῷ δεῖ εἶναι; οὐκ ἔστιν. οὔτε ἄρα ὅμοια οὔτε ἀνόμοια οὔτε ταὐτὰ οὔθʼ ἕτερά ἐστιν αὐτῷ τὰ ἄλλα. οὐ γάρ. τί δέ; τὸ ἐκείνου ἢ τὸ ἐκείνῳ ἢ τὸ τὶ ἢ τὸ τοῦτο ἢ τὸ τούτου ἢ ἄλλου ἢ ἄλλῳ ἢ ποτὲ ἢ", "r": "оно было бы уже причастно и сущности. — Явно. — Стало быть нет в нём ни великости, ни малости, ни равности. — Конечно, нет. — Да не будет в нём и подобия-то и инородности, ни в отношении к себе, ни в отношении к иному. — Явно, что не будет. — Что же? будет ли для него как-нибудь иное, если для него не должно быть ничего? — Невозможно. — Стало быть, иное для него ни подобно, ни не подобно, ни тожественно, ни отлично? — Конечно. — Что же? в отношении к не существующему будет ли иметь место того, или тому, или что, или это, или этого,"}, "164b": {"g": "ἔπειτα ἢ νῦν ἢ ἐπιστήμη ἢ δόξα ἢ αἴσθησις ἢ λόγος ἢ ὄνομα ἢ ἄλλο ὁτιοῦν τῶν ὄντων περὶ τὸ μὴ ὂν ἔσται; οὐκ ἔσται. οὕτω δὴ ἓν οὐκ ὂν οὐκ ἔχει πως οὐδαμῇ. οὔκουν δὴ ἔοικέν γε οὐδαμῇ ἔχειν. ἔτι δὴ λέγωμεν, ἓν εἰ μὴ ἔστι , τἆλλα τί χρὴ πεπονθέναι. λέγωμεν γάρ. ἄλλα μέν που δεῖ αὐτὰ εἶναι· εἰ γὰρ μηδὲ ἄλλα ἐστίν, οὐκ ἂν περὶ τῶν ἄλλων λέγοιτο. οὕτω. εἰ δὲ περὶ τῶν ἄλλων ὁ λόγος, τά γε ἄλλα ἕτερά ἐστιν. ἢ οὐκ ἐπὶ τῷ αὐτῷ καλεῖς τό τε ἄλλο καὶ τὸ", "r": "или инаго, или иному, или некогда, или потом, или теперь, или познание, или мнение, или чувство, или слово, или имя, или иное что-нибудь из существенностей? — Не будет. — Но так-то одно не существующее становится никаким. — Да, походит-таки, что оно — никакое. — \n\nРассудим еще: если одного нет, — что̀ должно испытать иное. — Рассудим. — Иное, вероятно, должно быть; потому что если и инаго нет, то не говорили бы об ином. — Так. — Если же речь идет об ином, то иное-то есть отличное. Или иное и отличное не прилагаешь ты к тому же самому? — Прилагаю. — Отличным-то мы называем,"}, "164c": {"g": "ἕτερον; ἔγωγε. ἕτερον δέ γέ πού φαμεν τὸ ἕτερον εἶναι ἑτέρου, καὶ τὸ ἄλλο δὴ ἄλλο εἶναι ἄλλου; ναί. καὶ τοῖς ἄλλοις ἄρα, εἰ μέλλει ἄλλα εἶναι, ἔστι τι οὗ ἄλλα ἔσται. ἀνάγκη. τί δὴ οὖν ἂν εἴη; τοῦ μὲν γὰρ ἑνὸς οὐκ ἔσται ἄλλα, μὴ ὄντος γε. οὐ γάρ. ἀλλήλων ἄρα ἐστί· τοῦτο γὰρ αὐτοῖς ἔτι λείπεται, ἢ μηδενὸς εἶναι ἄλλοις. ὀρθῶς. κατὰ πλήθη ἄρα ἕκαστα ἀλλήλων ἄλλα ἐστί· κατὰ ἓν γὰρ οὐκ ἂν οἷά τε εἴη, μὴ ὄντος ἑνός. ἀλλʼ ἕκαστος, ὡς", "r": "вероятно, отличное от другого, а иным — иное в отношении инаго? — Да. — Стало быть, у инаго, — чтобы быть ему иным, — есть нечто, в отношении чего оно будет иным. — Необходимо. — Что же будет оно? Ведь в отношении одного-то, если его нет, оно иным не будет. — Конечно, не будет. — Стало быть, под условием взаимного отношения вещей; ибо это только остается еще иному, — или уж быть иным в отношении к ничему. — Правильно. — Взятые, стало быть, во множестве вещи суть «иное», — каждая в отношении к другой; ибо в единстве, как скоро одного нет, это"}, "164d": {"g": "ἔοικεν, ὁ ὄγκος αὐτῶν ἄπειρός ἐστι πλήθει, κἂν τὸ σμικρότατον δοκοῦν εἶναι λάβῃ τις, ὥσπερ ὄναρ ἐν ὕπνῳ φαίνεται ἐξαίφνης ἀντὶ ἑνὸς δόξαντος εἶναι πολλὰ καὶ ἀντὶ σμικροτάτου παμμέγεθες πρὸς τὰ κερματιζόμενα ἐξ αὐτοῦ. ὀρθότατα. τοιούτων δὴ ὄγκων ἄλλα ἀλλήλων ἂν εἴη τἆλλα, εἰ ἑνὸς μὴ ὄντος ἄλλα ἐστίν. κομιδῇ μὲν οὖν. οὐκοῦν πολλοὶ ὄγκοι ἔσονται, εἷς ἕκαστος φαινόμενος, ὢν δὲ οὔ, εἴπερ ἓν μὴ ἔσται; οὕτω. καὶ ἀριθμὸς δὲ εἶναι αὐτῶν", "r": "для них невозможно: за то по множеству, каждая масса их, как видно, беспредельна, хотя бы кто взял, по-видимому, самое малое. Так во сне вдруг вместо кажущегося одного представляется многое, и вместо самомалейшего — чрезвычайно большое, по сравнению с тем, что из него выделяется. — Весьма справедливо. — Так иное будет иное во взаимном отношении таких-то масс, — если есть иное при несуществовании одного. — Совершенно так. — Но когда много масс, не явится ли каждая одною, — хотя в действительности"}, "164e": {"g": "δόξει, εἴπερ καὶ ἓν ἕκαστον, πολλῶν ὄντων. πάνυ γε. καὶ τὰ μὲν δὴ ἄρτια, τὰ δὲ περιττὰ ἐν αὐτοῖς ὄντα οὐκ ἀληθῶς φαίνεται, εἴπερ ἓν μὴ ἔσται. οὐ γὰρ οὖν. καὶ μὴν καὶ σμικρότατόν γε, φαμέν, δόξει ἐν αὐτοῖς ἐνεῖναι· φαίνεται δὲ τοῦτο πολλὰ καὶ μεγάλα πρὸς ἕκαστον τῶν", "r": "и не будет, если нет одного? — Так. — И покажется, что они имеют число, — если их много, и каждая составляет одно? — Конечно. — И одни из них явятся четными, другие нечетными, — но опять ложно, если одного не будет. — Конечно, ложно. — Притом покажется, говорим, что в них есть и самомалейшее-то; но оно представится многим и великим, в сравнении с каждым из многих и малых существ. — Ка̀к не представиться! — И каждая масса покажется также равною многому"}, "165a": {"g": "πολλῶν ὡς σμικρῶν ὄντων. πῶς δʼ οὔ; καὶ ἴσος μὴν τοῖς πολλοῖς καὶ σμικροῖς ἕκαστος ὄγκος δοξασθήσεται εἶναι· οὐ γὰρ ἂν μετέβαινεν ἐκ μείζονος εἰς ἔλαττον φαινόμενος, πρὶν εἰς τὸ μεταξὺ δόξειεν ἐλθεῖν, τοῦτο δʼ εἴη ἂν φάντασμα ἰσότητος. εἰκός. οὐκοῦν καὶ πρὸς ἄλλον ὄγκον πέρας ἔχων, αὐτός γε πρὸς αὑτὸν οὔτε ἀρχὴν οὔτε πέρας οὔτε μέσον ἔχων; πῇ δή; ὅτι ἀεὶ αὐτῶν ὅταν τίς τι λάβῃ τῇ διανοίᾳ ὥς τι τούτων ὄν, πρό τε τῆς ἀρχῆς ἄλλη", "r": "малому; потому что являющееся не перейдет от бо̀льшего к меньшему, прежде чем представится в средине между ними; а это будет представление равности. — Естественно. — Но, и в отношении к иной массе, и в отношении к самой себе имея предел, не покажется ли каждая масса вместе и не имеющею ни начала, ни конца, ни средины? — Каким же образом? — Ведь когда мысленно допустишь в них какое-нибудь из тех свойств, — всегда прежде начала является иное начало, после конца — другой, остающийся конец, а в средине — иная, еще более средняя средина, но"}, "165b": {"g": "ἀεὶ φαίνεται ἀρχή, μετά τε τὴν τελευτὴν ἑτέρα ὑπολειπομένη τελευτή, ἔν τε τῷ μέσῳ ἄλλα μεσαίτερα τοῦ μέσου, σμικρότερα δέ, διὰ τὸ μὴ δύνασθαι ἑνὸς αὐτῶν ἑκάστου λαμβάνεσθαι, ἅτε οὐκ ὄντος τοῦ ἑνός. ἀληθέστατα. θρύπτεσθαι δὴ οἶμαι κερματιζόμενον ἀνάγκη πᾶν τὸ ὄν, ὃ ἄν τις λάβῃ τῇ διανοίᾳ· ὄγκος γάρ που ἄνευ ἑνὸς ἀεὶ λαμβάνοιτʼ ἄν. πάνυ μὲν οὖν. οὐκοῦν τό γε τοιοῦτον πόρρωθεν μὲν", "r": "меньшая — потому, что, за несуществованием одного, невозможно схватить каждую из них, как одну. — Весьма справедливо. — И та̀к необходимо, думаю, дробится в делении всё сущее, какое кто берет мысленно; потому что берется, вероятно, масса, без одного. — Конечно, так. — Такое-то сущее — тому, кто смотрит издали и тупо, не необходимо ли является одним, но мыслящему вблизи и остро —"}, "165c": {"g": "ὁρῶντι καὶ ἀμβλὺ ἓν φαίνεσθαι ἀνάγκη, ἐγγύθεν δὲ καὶ ὀξὺ νοοῦντι πλήθει ἄπειρον ἓν ἕκαστον φανῆναι, εἴπερ στέρεται τοῦ ἑνὸς μὴ ὄντος; ἀναγκαιότατον μὲν οὖν. οὕτω δὴ ἄπειρά τε καὶ πέρας ἔχοντα καὶ ἓν καὶ πολλὰ ἕκαστα τἆλλα δεῖ φαίνεσθαι, ἓν εἰ μὴ ἔστιν, τἆλλα δὲ τοῦ ἑνός . δεῖ γάρ. οὐκοῦν καὶ ὅμοιά τε καὶ ἀνόμοια δόξει εἶναι; πῇ δή; οἷον ἐσκιαγραφημένα ἀποστάντι μὲν ἓν πάντα φαινόμενα ταὐτὸν φαίνεσθαι πεπονθέναι καὶ ὅμοια εἶναι. πάνυ", "r": "беспредельным в каждой из отдельностей, — поколику они лишены одного, как не существующего? — Весьма необходимо. — Таким образом иное, в своих отдельностях, — как скоро одного нет, а есть иное в отношении одного, — должно являться беспредельным и имеющим предел, одним и многим. — Должно. — Не покажется ли оно также подобным и не подобным? — Почему же? — Например, фигуры на картине для стоящего вдали, сливаясь все в одно, являются с одними и теми же свойствами и становятся подобными. —"}, "165d": {"g": "γε. προσελθόντι δέ γε πολλὰ καὶ ἕτερα καὶ τῷ τοῦ ἑτέρου φαντάσματι ἑτεροῖα καὶ ἀνόμοια ἑαυτοῖς. οὕτω. καὶ ὁμοίους δὴ καὶ ἀνομοίους τοὺς ὄγκους αὐτούς τε αὑτοῖς ἀνάγκη φαίνεσθαι καὶ ἀλλήλοις. πάνυ μὲν οὖν. οὐκοῦν καὶ τοὺς αὐτοὺς καὶ ἑτέρους ἀλλήλων, καὶ ἁπτομένους καὶ χωρὶς ἑαυτῶν, καὶ κινουμένους πάσας κινήσεις καὶ ἑστῶτας πάντῃ, καὶ γιγνομένους καὶ ἀπολλυμένους καὶ μηδέτερα, καὶ πάντα που τὰ τοιαῦτα, ἃ διελθεῖν εὐπετὲς ἤδη ἡμῖν, εἰ ἑνὸς", "r": "Конечно. — А кто подошел-то, тот видит многое и различное; по представлению же различного, видимое признает инородным и не подобным одно другому. — Так. — Значит, и самые массы необходимо должны являться и подобными, и не подобными, как самим себе, так и одни другим. — Конечно. — А потому, и теми же и взаимно различными, и соприкасающимися и обособленными, и имеющими все виды движения и совершенно неподвижными, и рождающимися и погибающими, и ничего такого не обнаруживающими"}, "165e": {"g": "μὴ ὄντος πολλὰ ἔστιν. ἀληθέστατα μὲν οὖν. ἔτι δὴ ἅπαξ ἐλθόντες πάλιν ἐπὶ τὴν ἀρχὴν εἴπωμεν, ἓν εἰ μὴ ἔστι, τἆλλα δὲ τοῦ ἑνός , τί χρὴ εἶναι. εἴπωμεν γὰρ οὖν. οὐκοῦν ἓν μὲν οὐκ ἔσται τἆλλα. πῶς γάρ; οὐδὲ μὴν πολλά γε· ἐν γὰρ πολλοῖς οὖσιν ἐνείη ἂν καὶ ἕν. εἰ γὰρ μηδὲν αὐτῶν ἐστὶν ἕν, ἅπαντα οὐδέν ἐστιν, ὥστε οὐδʼ ἂν πολλὰ εἴη. ἀληθῆ. μὴ ἐνόντος δὲ ἑνὸς ἐν τοῖς ἄλλοις, οὔτε πολλὰ οὔτε ἕν ἐστι τἆλλα. οὐ γάρ. οὐδέ", "r": "и обнаруживающими всё такое, — что̀ раскрыть было бы нам уже не трудно, если, при несуществовании одного, мы положим многое. — Весьма справедливо.\n\nВзойдем еще однажды к началу, и скажем: если одного нет, то чем должно быть иное в отношении одного? — Да, скажем. — Ведь иное не будет одним. — Ка̀к быть. — Да не будет и многим-то; потому что во многом находилось бы и одно: а когда ни в чём этом нет одного, — всё вместе оно ничто; так что не будет и многого. — Правда. — Если нет одного в ином, иное не"}, "166a": {"g": "γε φαίνεται ἓν οὐδὲ πολλά. τί δή; ὅτι τἆλλα τῶν μὴ ὄντων οὐδενὶ οὐδαμῇ οὐδαμῶς οὐδεμίαν κοινωνίαν ἔχει, οὐδέ τι τῶν μὴ ὄντων παρὰ τῶν ἄλλων τῴ ἐστιν· οὐδὲν γὰρ μέρος ἐστὶ τοῖς μὴ οὖσιν. ἀληθῆ. οὐδʼ ἄρα δόξα τοῦ μὴ ὄντος παρὰ τοῖς ἄλλοις ἐστὶν οὐδέ τι φάντασμα, οὐδὲ δοξάζεται οὐδαμῇ οὐδαμῶς τὸ μὴ ὂν ἐπὶ τῶν ἄλλων. οὐ γὰρ οὖν. ἓν ἄρα εἰ μὴ ἔστιν, οὐδὲ δοξάζεταί τι τῶν", "r": "есть ни многое, ни одно. — Конечно, так. — Да и не является ни одним, ни многим. — Почему же? — Потому что иное ни с чем из не существующего нигде, никаким образом и никакого не имеет общения, и ничто из не существующего не содержится в чём-нибудь ином, так как у не существующего нет и частей. — Правда. — Стало быть, в ином нет и мнения о не существующем или представления, и не существующее вовсе никак не мнится для инаго. — Конечно, нет. — Следовательно, если одного нет, то и не мнится что-либо иное, ни как одно, ни как многое; потому"}, "166b": {"g": "ἄλλων ἓν εἶναι οὐδὲ πολλά· ἄνευ γὰρ ἑνὸς πολλὰ δοξάσαι ἀδύνατον. ἀδύνατον γάρ. ἓν ἄρα εἰ μὴ ἔστι, τἆλλα οὔτε ἔστιν οὔτε δοξάζεται ἓν οὐδὲ πολλά. οὐκ ἔοικεν. οὐδʼ ἄρα ὅμοια οὐδὲ ἀνόμοια. οὐ γάρ. οὐδὲ μὴν τὰ αὐτά γε οὐδʼ ἕτερα, οὐδὲ ἁπτόμενα οὐδὲ χωρίς, οὐδὲ ἄλλα ὅσα ἐν τοῖς πρόσθεν διήλθομεν ὡς φαινόμενα αὐτά, τούτων οὔτε τι ἔστιν οὔτε φαίνεται τἆλλα, ἓν εἰ μὴ ἔστιν. ἀληθῆ. οὐκοῦν καὶ", "r": "что без одного мнить многое невозможно. — Невозможно. — Стало быть, если нет одного, — иное и не есть, и не мнится — ни как одно, ни как многое. — Походит, что нет. — То же и как подобное и не подобное, — Конечно, нет. — Да и как тожественное и различное, соприкасающееся и обособленное, или в связи с другими свойствами, в которых мы проследили выше его явления: этих свойств иное не имеет и в них не является, если одного нет. —"}, "166c": {"g": "συλλήβδην εἰ εἴποιμεν, ἓν εἰ μὴ ἔστιν, οὐδέν ἐστιν, ὀρθῶς ἂν εἴποιμεν; παντάπασι μὲν οὖν. εἰρήσθω τοίνυν τοῦτό τε καὶ ὅτι, ὡς ἔοικεν, ἓν εἴτʼ ἔστιν εἴτε μὴ ἔστιν, αὐτό τε καὶ τἆλλα καὶ πρὸς αὑτὰ καὶ πρὸς ἄλληλα πάντα πάντως ἐστί τε καὶ οὐκ ἔστι καὶ φαίνεταί τε καὶ οὐ φαίνεται. ἀληθέστατα.", "r": "Правда. — Итак, сказав кратко: если одного нет, то нет ничего, — не правильно ли мы скажем? — Без сомнения, правильно. — Скажем же и это, и, как видно, то, что если одно есть, или одного нет, то как само оно, так и иное, и в отношении к себе, и в отношении одно к другому, совершенно всё есть и не есть, всем является и не является. — Весьма справедливо."}};
